#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_PACKETS 10000

typedef struct {
    int transmission_tag;
    int sequence_number;
    int data_size;
} TX_PACKET;

typedef struct {
    TX_PACKET* packets;
    int packet_count;
    pthread_mutex_t lock;
} PACKET_MANAGER;

PACKET_MANAGER* packet_manager_create() {
    PACKET_MANAGER* manager = (PACKET_MANAGER*)malloc(sizeof(PACKET_MANAGER));
    manager->packets = (TX_PACKET*)malloc(MAX_PACKETS * sizeof(TX_PACKET));
    manager->packet_count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void packet_manager_insert(PACKET_MANAGER* manager, TX_PACKET* packet) {
    pthread_mutex_lock(&manager->lock);
    int index = manager->packet_count++;
    manager->packets[index] = *packet;
    pthread_mutex_unlock(&manager->lock);
}

TX_PACKET* packet_manager_get_packet(PACKET_MANAGER* manager, int sequence_number) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->packet_count; i++) {
        if (manager->packets[i].sequence_number == sequence_number) {
            TX_PACKET* packet = &manager->packets[i];
            pthread_mutex_unlock(&manager->lock);
            return packet;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

int main() {
    // Create the packet manager
    PACKET_MANAGER* manager = packet_manager_create();

    // Insert packets into the manager
    TX_PACKET packet1 = {1, 0x1000, 100};
    TX_PACKET packet2 = {2, 0x2000, 200};
    packet_manager_insert(manager, &packet1);
    packet_manager_insert(manager, &packet2);

    // Retrieve a packet by sequence number
    TX_PACKET* packet = packet_manager_get_packet(manager, 0x1000);
    if (packet != NULL) {
        printf("Packet with sequence number 0x1000 found: %d\n", packet->data_size);
    } else {
        printf("Packet not found\n");
    }

    return 0;
}

