// Define the structure for a record
typedef struct {
    int key;
    void* value;
    struct offset_record* offsets;
} record;

// Define the structure for an offset record
typedef struct {
    int timestamp;
    void* data;
} offset_record;

// Create a new record
record* create_record(int key, void* value) {
    record* new_record = (record*)malloc(sizeof(record));
    new_record->key = key;
    new_record->value = value;
    new_record->offsets = NULL;
    return new_record;
}

// Add an offset to a record
void add_offset(record* record, int timestamp, void* data) {
    offset_record* new_offset = (offset_record*)malloc(sizeof(offset_record));
    new_offset->timestamp = timestamp;
    new_offset->data = data;
    if (record->offsets == NULL) {
        record->offsets = new_offset;
    } else {
        // If there are existing offsets, append the new one to the list
        offset_record* current = record->offsets;
        while (current != NULL && current->next != NULL) {
            current = current->next;
        }
        current->next = new_offset;
    }
}

// Remove an offset from a record
void remove_offset(record* record, int timestamp) {
    // Find the offset to remove and update the record's offsets pointer accordingly
    if (record->offsets == NULL || record->offsets->timestamp != timestamp) {
        return; // Offset not found or does not match the specified timestamp
    }
    offset_record* current = record->offsets;
    while (current->next != NULL) {
        free(current);
        current = current->next;
    }
    if (current != NULL) {
        free(current); // Free the last element in the list
    }
}

// Serialize a record and its offsets to a file
void serialize_record(record* record, FILE* file) {
    fwrite(&record->key, sizeof(int), 1, file);
    fwrite(record->value, sizeof(void*), 1, file);
    // Serialize the offset records
    offset_record* current = record->offsets;
    while (current != NULL) {
        fwrite(&current->timestamp, sizeof(int), 1, file);
        fwrite(current->data, sizeof(void*), 1, file);
        current = current->next;
    }
}

// Deserialize a record and its offsets from a file
record* deserialize_record(FILE* file) {
    record* new_record = (record*)malloc(sizeof(record));
    fread(&new_record->key, sizeof(int), 1, file);
    new_record->value = NULL; // Replace with actual deserialization code

    // Deserialize the offset records
    offset_record* current = NULL;
    while (fread(&temp_timestamp, sizeof(int), 1, file) == 1) {
        temp_data = NULL; // Replace with actual deserialization code
        if (current != NULL) {
            current->next = (offset_record*)malloc(sizeof(offset_record));
            current = current->next;
        } else {
            new_record->offsets = (offset_record*)malloc(sizeof(offset_record));
            current = new_record->offsets;
        }
        current->timestamp = temp_timestamp;
        current->data = temp_data;
    }

    return new_record;
}

// Periodic pruning of offset records based on timestamps
void prune_offsets(record* record, int timestamp) {
    // Find and remove offsets older than the specified timestamp
    offset_record* current = record->offsets;
    while (current != NULL && current->timestamp <= timestamp) {
        free(current);
        current = current->next;
    }
}

// Free a record and its offsets
void free_record(record* record) {
    // Recursively free the record's value and any associated data structures
    if (record->value != NULL) {
        // Replace with actual freeing code for 'record->value'
    }

    // Recursively free the offset records
    offset_record* current = record->offsets;
    while (current != NULL) {
        free(current);
        current = current->next;
    }
}

// Example usage of the library
int main() {
    record* my_record = create_record(1, "Hello");
    add_offset(my_record, 1643723400, "World");

    // Serialize and deserialize a record
    FILE* file = fopen("record.bin", "wb");
