#define CHUNK_SIZE 1024

void copyDataChunks(char** bufferedData, int chunkSize, int numChunks) {
    size_t bufferLen = 0;
    char* dstBuffer = malloc(CHUNK_SIZE);
    for (int i = 0; i < numChunks; i++) {
        size_t bytesRead = fread(dstBuffer, 1, CHUNK_SIZE, *bufferedData[i]);
        fwrite(dstBuffer, 1, bytesRead, *bufferedData[i]);
    }
    free(dstBuffer);
}

void processFile(char* filename) {
    CURL* curl;
    CURLcode res;
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Error opening file for writing");
        return;
    }

    // Initialize curl
    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (!curl) {
        printf("curl initialization failed\n");
        return;
    }

    // Set options and perform the actual transfer
    curl_easy_setopt(curl, CURLOPT_URL, "https://remote-data-service.com/api/endpoint");
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeData);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, file);

    do {
        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl error: %s\n", curl_easy_strerror(res));
            break;
        }
    } while (0);

    // Clean up
    curl_easy_cleanup(curl);
    fclose(file);
}

static size_t writeData(void* contents, size_t size, size_t nmemb, void* userp) {
    size_t bytesWritten = fwrite(contents, 1, size * nmemb, (FILE*)userp);
    return bytesWritten;
}
