        printf("Array is empty.\n");
    } else if (size > 0) {
        int max = arr[0];
        for (int i = 1; i < size; i++) {
            if (arr[i] > max) {
                max = arr[i];
            }
        }
        printf("Largest integer in the array: %d\n", max);
    } else {
        // All integers in the array are negative
        printf("All integers in the array are negative.\n");
    }
}

// Function to free dynamically allocated memory and handle potential errors
