['```
import os
import hashlib
from typing import Dict, Any
from fastapi import FastAPI, HTTPException, status
from fastapi.responses import JSONResponse
from fastapi.requests import Request
from pydantic import BaseModel
from requests_oauthlib import OAuth2Session
from loguru import logger

app = FastAPI()

class FileHashRequest(BaseModel):
    file_path: str
    action: str  # "hash" or "verify"

@app.post("/file_hash")
async def process_file_hash(request: Request, file_request: FileHashRequest):
    if request.state == None:
        return JSONResponse(status_code=400, content={"message": "Missing OAuth token"})

    cloud_storage_api = OAuth2Session(client_id=os.environ["CLOUD_STORAGE_CLIENT_ID"],
                                        client_secret=os.environ["CLOUD_STORAGE_CLIENT_SECRET"],
                                        redirect_uri=os.environ["CLOUD_STORAGE_REDIRECT_URI"])

    # Authenticate with Cloud Storage API
    cloud_storage_api.fetch_token(token_url="https://example.com/token")

    if file_request.action == "hash":
        return await hash_file(file_request.file_path)
    elif file_request.action == "verify":
        return await verify_file_hash(file_request.file_path)

def hash_file(file_path: str) -> Dict[str, Any]:
    # Chunk large files (>10 GB) into smaller pieces for efficient processing
    with open(file_path, "rb") as f:
        chunk_size = 64 * 1024  # 64 MB chunks
        file_chunks = [f.read(chunk_size)] if os.path.getsize(file_path) <= chunk_size else \
            [f.read(chunk_size)] + [(os.urandom(chunk_size)).join(f.read(chunk_size).decode().encode()) for _ in range((os.path.getsize(file_path) // chunk_size) - 1)]

    # Calculate SHA-256 hash of file chunks
    sha256_hash = hashlib.sha256()
    for chunk in file_chunks:
        sha256_hash.update(chunk)

    return {"file_path": file_path, "hash": sha256_hash.hexdigest()}

def verify_file_hash(file_path: str) -> Dict[str, Any]:
    # Download file from Cloud Storage and calculate SHA-256 hash
    cloud_storage_response = cloud_storage_api.get(f"https://example.com/files/{file_path}")

    if cloud_storage_response.status_code == 200:
        with open("temp_file", "wb") as f:
            f.write(cloud_storage_response.content)

        # Calculate SHA-256 hash of downloaded file
        sha256_hash = hashlib.sha256()
        with open("temp_file", "rb") as f:
            while chunk := f.read(4096):
                sha256_hash.update(chunk)

        os.remove("temp_file")

        return {"file_path": file_path, "hash": sha256_hash.hexdigest()}
    else:
        raise HTTPException(status_code=500, detail="Failed to download file")

if __name__ == "__main__":
    uvicorn.run(app, host="0.0.0.0", port=8000)
