#include <pthread.h>
#include <semaphore.h>
#include <time.h>

// Semaphore definition
sem_t *sem;

// Function to initialize the semaphore
void init_sem() {
    sem = sem_open("/my_semaphore", O_CREAT | O_RDWR, 0644, 1);
}

// Function to acquire the semaphore
int acquire_sem() {
    int result = sem_wait(sem);
    return result;
}

// Function to release the semaphore
int release_sem() {
    int result = sem_post(sem);
    return result;
}

// Function to destroy the semaphore
void destroy_sem() {
    sem_close(sem);
    sem_unlink("/my_semaphore");
}

// Thread function to test the semaphore
void* thread_func(void* arg) {
    // Acquire the semaphore
    int acquire_result = acquire_sem();
    if (acquire_result == -1) {
        printf("Error acquiring semaphore\n");
        return NULL;
    }

    // Perform some operation (e.g., access an external API)
    sleep(1);

    // Release the semaphore
    release_sem();

    pthread_exit(NULL);
}

// Main function to test the semaphore
int main() {
    int num_threads = 10000;

    // Initialize the semaphore
    init_sem();

    // Create and start threads
    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, thread_func, NULL);
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Destroy the semaphore
    destroy_sem();

    return 0;
}
