#include <forward_list>
#include <string>
#include <memory>

void insertAfterOrLogError(std::forward_list<std::string>& list,
                             const std::string& target,
                             const std::string& element,
                             std::shared_ptr<LoggingService> loggingService) {
    auto it = list.begin();
    bool targetFound = false;
    while (it != list.end()) {
        if (*it == target) {
            targetFound = true;
            break;
        }
        ++it;
    }

    if (!targetFound) {
        // Error log: Target not found, last searched position
        try {
            loggingService->logError(
                "Target '{}' not found. Last searched at index {}.",
                target,
                it.base() - list.begin()
            );
        } catch (const std::exception& e) {
            // Log error and skip further processing if exception occurs
            loggingService->logError("Error logging: {}", e.what());
            return;
        }
    }

    list.insert_after(it, element);
}
