using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Caching.Memory;
using Newtonsoft.Json;

namespace WeatherAndTrafficSystem.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class WeatherController : ControllerBase
    {
        private readonly IWeatherService _weatherService;
        private readonly ITrafficService _trafficService;
        private readonly IMemoryCache _cache;
        private readonly ILogger<WeatherController> _logger;

        public WeatherController(IWeatherService weatherService, ITrafficService trafficService, IMemoryCache cache, ILogger<WeatherController> logger)
        {
            _weatherService = weatherService;
            _trafficService = trafficService;
            _cache = cache;
            _logger = logger;
        }

        [HttpGet]
        public async Task<ActionResult<WeatherResponse>> GetWeather(string location, int? frequency = 1)
        {
            var cacheKey = $"weather:{location}:{frequency}";
            if (_cache.TryGetValue(cacheKey, out WeatherResponse cachedWeather))
            {
                return Ok(cachedWeather);
            }

            try
            {
                var weatherData = await _weatherService.GetWeather(location);
                var trafficData = await _trafficService.GetTraffic(location);

                var response = new WeatherResponse { Location = location, Weather = weatherData, Traffic = trafficData };

                // Cache the data for the specified frequency
                var cacheEntryOptions = new MemoryCacheEntryOptions().SetSlidingExpiration(TimeSpan.FromHours(frequency.Value));
                _cache.Set(cacheKey, response, cacheEntryOptions);

                return Ok(response);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error fetching weather data for {Location}", location);
                // Fallback to cached data or historical data
                if (_cache.TryGetValue(cacheKey, out WeatherResponse cachedWeather))
                {
                    return Ok(cachedWeather);
                }
                else
                {
                    return StatusCode(503, "Service Unavailable");
                }
            }
        }

        [HttpGet("{location}/alerts")]
        public async Task<ActionResult<IEnumerable<Alert>>> GetLocationAlerts(string location)
        {
            var cacheKey = $"alerts:{location}";
            if (_cache.TryGetValue(cacheKey, out IEnumerable<Alert> cachedAlerts))
            {
                return Ok(cachedAlerts);
            }

            try
            {
                var alerts = await _weatherService.GetLocationAlerts(location);

                // Cache the alerts for 1 hour
                _cache.Set(cacheKey, alerts, new MemoryCacheEntryOptions().SetSlidingExpiration(TimeSpan.FromHours(1)));

                return Ok(alerts);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error fetching location alerts for {Location}", location);
                // Fallback to cached data or historical data
                if (_cache.TryGetValue(cacheKey, out IEnumerable<Alert> cachedAlerts))
                {
                    return Ok(cachedAlerts);
                }
                else
                {
                    return StatusCode(503, "Service Unavailable");
                }
            }
        }

        private class WeatherResponse
        {
            public string Location { get; set; }
            public WeatherData Weather { get; set; }
            public TrafficData Traffic { get; set; }
        }
    }
}
