        private readonly ILogger _logger;
        private readonly XPathQueryFactory _xpathQueryFactory;

        public XmlProcessorService(IRedisConnection redisConnection, ISchemaLoader schemaLoader, ILogger logger, XPathQueryFactory xpathQueryFactory)
        {
            _redisConnection = redisConnection;
            _schemaLoader = schemaLoader;
            _logger = logger;
            _xpathQueryFactory = xpathQueryFactory;
        }

        public async Task ProcessXmlChunkAsync(byte[] chunk, string schemaId, int chunkIndex)
        {
            // Validate XML chunk against dynamically loaded schema
            var validationResult = await ValidateXmlChunkAgainstSchema(chunk, schemaId);

            if (!validationResult.IsValid)
            {
                _logger.LogError(validationResult.ErrorMessage);
                return;
            }

            // Merge parsed elements across chunks while maintaining thread safety and avoiding race conditions
            var mergedXml = await MergeChunksAsync(chunkIndex, validationResult.Xml);

            // Store frequently requested documents in distributed cache (Redis) for optimized retrieval
            await StoreDocumentInCacheAsync(mergedXml, schemaId);

            // Log processing events with configurable levels of detail for auditing and monitoring
            _logger.LogInformation($"Processed XML chunk {chunkIndex} successfully.");
        }

        private async Task<ValidationResult> ValidateXmlChunkAgainstSchema(byte[] chunk, string schemaId)
        {
            var schema = await _schemaLoader.LoadSchemaAsync(schemaId);
            // Validate XML chunk against loaded schema
            return new ValidationResult(XmlReader.Create(chunk), schema);
        }

