    public ResponseEntity<Resource> getResource(@PathVariable String id, HttpServletRequest request) {
        // TO DO: Implement authentication and authorization
        return ResponseEntity.ok(userRepository.findById(id).orElse(null));
    }

    @PutMapping("/resources/{id}")
    @ApiOperation(value = "Update a specific resource", notes = "Updates a specific resource by its ID")
    public ResponseEntity<Resource> updateResource(@PathVariable String id, @RequestBody Resource resource, HttpServletRequest request) {
        // TO DO: Implement authentication and authorization
        Resource existingResource = userRepository.findById(id).orElse(null);
        if (existingResource == null) {
            return ResponseEntity.status(HttpStatus.NOT_FOUND).body(new Resource());
        }
        existingResource.setName(resource.getName());
        existingResource.setDescription(resource.getDescription());
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            md.update(String.valueOf(existingResource).getBytes());
