import io.javalin.Javali;
import io.javalin.http.Context;
import io.javalin.http.HttpCode;
import org.apache.commons.validator.routines.EmailValidator;

public class UserAccountService {
    private final CloudDatabase cloudDatabase;
    private final IdentityProvider identityProvider;
    private final OAuth2Service oAuth2Service;
    private final CachingStrategy cachingStrategy;
    private final RetryLogic retryLogic;
    private final CircuitBreaker circuitBreaker;

    public UserAccountService(CloudDatabase cloudDatabase, IdentityProvider identityProvider, OAuth2Service oAuth2Service, CachingStrategy cachingStrategy, RetryLogic retryLogic, CircuitBreaker circuitBreaker) {
        this.cloudDatabase = cloudDatabase;
        this.identityProvider = identityProvider;
        this.oAuth2Service = oAuth2Service;
        this.cachingStrategy = cachingStrategy;
        this.retryLogic = retryLogic;
        this.circuitBreaker = circuitBreaker;
    }

    public void start() {
        Javali app = new Javali();

        app.get("/users/:id", this::getUser);
        app.put("/users/:id", this::updateUser);
        app.delete("/users/:id", this::deleteUser);
        app.post("/users", this::createUser);

        app.start();
    }

    private void createUser(Context ctx) {
        String name = ctx.formParam("name");
        String email = ctx.formParam("email");
        String password = ctx.formParam("password");

        if (!validateRequest(ctx, "create")) {
            return;
        }

        User user = new User(UUID.randomUUID().toString(), name, email);
        user.setPassword(password);

        cloudDatabase.save(user);

        oAuth2Service.createOAuthToken(user.getUuid());

        ctx.result(HttpCode.CREATED.render()).type("application/json");
    }

    private void getUser(Context ctx) {
        String id = ctx.pathParam("id");

        if (!validateRequest(ctx, "get")) {
            return;
        }

        User user = cloudDatabase.get(id);

        if (user == null) {
            ctx.status(HttpCode.NOT_FOUND.render());
            return;
        }

        ctx.result(user.toString()).type("application/json");
    }

    private void updateUser(Context ctx) {
        String id = ctx.pathParam("id");

        if (!validateRequest(ctx, "update")) {
            return;
        }

        User user = cloudDatabase.get(id);

        if (user == null) {
            ctx.status(HttpCode.NOT_FOUND.render());
            return;
        }

        String name = ctx.formParam("name");
        String email = ctx.formParam("email");

        user.setName(name);
        user.setEmail(email);

        cloudDatabase.save(user);

        ctx.result(HttpCode.OK.render()).type("application/json");
    }

    private void deleteUser(Context ctx) {
        String id = ctx.pathParam("id");

        if (!validateRequest(ctx, "delete")) {
            return;
        }

        User user = cloudDatabase.get(id);

        if (user == null) {
            ctx.status(HttpCode.NOT_FOUND.render());
            return;
        }

        oAuth2Service.revokeOAuthToken(user.getUuid());

        cloudDatabase.delete(id);

        ctx.result(HttpCode.OK.render()).type("application/json");
    }

    private boolean validateRequest(Context ctx, String action) {
        if (!EmailValidator.getInstance().isValid(ctx.formParam("email"))) {
            ctx.status(HttpCode.BAD_REQUEST.render());
            return false;
        }

        // Add more validation logic as needed

        return true;
    }
}

