#include <iostream>
#include <thread>
#include "octree_service.h"

void updatePageSection(int pageSectionId, int elementId, std::string htmlContent) {
    // Initialize octree service with feature size and number of leaf nodes
    OctreeService octreeService(16, 1024);

    // Allocate memory for prefix leaves and data arrays dynamically
    auto octree = octreeService.createOctree();
    octree->allocateMemory();

    // Update the element's HTML content using the octree service
    std::unique_ptr<octree_node> node = octreeService.updateElementContent(octree, pageSectionId, elementId, htmlContent);

    // Handle concurrent access and race conditions
    std::mutex mutex;
    bool updating = false;

    void updateOctree() {
        std::lock_guard<std::mutex> lock(mutex);
        if (!updating) {
            updating = true;
            try {
                octreeService.updateOctree(octree, node.get());
            } catch (const std::exception& e) {
                // Handle errors and exceptions
                std::cerr << "Error: " << e.what() << std::endl;
            }
            finally {
                updating = false;
            }
        }
    }

    // Create a separate thread for concurrent updates
    std::thread updateThread(updateOctree);

    // Wait for the thread to finish and the octree to be updated
    updateThread.join();

    // Release memory and clean up resources
    octreeService.releaseMemory(octree);
}

int main() {
    updatePageSection(1, 2, "New content");
    return 0;
}
