public class MoSTStateLoader {
    private static final String STATE_FILE_SUFFIX = ".state";
    private static final int CACHE_SIZE = 100;
    private MetadataService metadataService;
    private FileCache fileCache;
    private Logger logger;

    public MoSTStateLoader(MetadataService metadataService, FileCache fileCache) {
        this.metadataService = metadataService;
        this.fileCache = fileCache;
        this.logger = new Logger();
    }

    public MoSTState loadStateFromFile(String fileName) throws IOException {
        String filePath = getFilePath(fileName);
        MoSTState state = null;

        try (FileInputStream fis = new FileInputStream(filePath)) {
            state = deserializeState(fis);
        } catch (IOException e) {
            logger.error("Failed to read file: " + filePath, e);
        }

        if (state != null) {
            verifyState(state);
        }

        return state;
    }

    private String getFilePath(String fileName) {
        return new File(fileName).getPath();
    }

    private MoSTState deserializeState(FileInputStream fis) throws IOException {
        ObjectInputStream ois = new ObjectInputStream(fis);
        return (MoSTState) ois.readObject();
    }

    private void verifyState(MoSTState state) throws IOException {
        if (metadataService.isAvailable()) {
            boolean isValid = metadataService.verifyState(state);
            if (!isValid) {
                logger.warn("Loaded state is invalid. Proceeding with caution.");
            }
        } else {
            logger.warn("Metadata service unavailable. Proceeding without verification.");
        }
    }

    public void cacheState(MoSTState state, String fileName) throws IOException {
        fileCache.put(fileName, state);
    }

    public MoSTState loadCachedState(String fileName) {
        return fileCache.get(fileName);
    }

    private class Logger {
        public void error(String message, Throwable t) {
            System.err.println(message + ": " + t.getMessage());
        }

        public void warn(String message) {
            System.out.println("Warning: " + message);
        }
    }
}
