// fileProcessor.js

const { promisify } = require('util');
const fs = require('fs');
const path = require('path');
const csv = require('csv-parser');
const xmljs = require('xml-js');
const redis = require('redis');

class FileProcessor {
  constructor({
    directoryPath,
    apiEndpoint,
    cacheDuration = '1 hour',
  }) {
    this.directoryPath = directoryPath;
    this.apiEndpoint = apiEndpoint;
    this.cacheDuration = cacheDuration;
    this.cacheClient = redis.createClient();
    this.processedFiles = {};
  }

  async filterFiles() {
    const files = await fs.readdir(this.directoryPath);
    return files.filter((file) => ['json', 'csv', 'xml'].includes(path.extname(file).slice(1)));
  }

  async processFile(file) {
    try {
      if (path.extname(file) === '.json') {
        this.processedFiles[file] = JSON.parse(await fs.readFileSync(`${this.directoryPath}/${file}`));
      } else if (path.extname(file) === '.csv') {
        const csvData = await csv.parse(await fs.readFileSync(`${this.directoryPath}/${file}`), { columns: true });
        this.processedFiles[file] = csvData;
      } else if (path.extname(file) === '.xml') {
        const xmlDoc = new xmljs.XMLParser().parseString(await fs.readFileSync(`${this.directoryPath}/${file}`));
        this.processedFiles[file] = xmlDoc.xml2js();
      }
    } catch (error) {
      console.error(`Error parsing ${file}:`, error);
      throw error;
    }
  }

  async mergeData() {
    const mergedData = {};
    Object.keys(this.processedFiles).forEach((file) => {
      if (!mergedData[file]) mergedData[file] = this.processedFiles[file];
    });
    return mergedData;
  }

  async cacheData(data) {
    for (const file in data) {
      await this.cacheClient.setex(file, parseInt(this.cacheDuration), JSON.stringify(data[file]));
    }
  }

  async getDataFromCache() {
    const cachedData = {};
    Object.keys(this.processedFiles).forEach((file) => {
      try {
        const cachedFile = await this.cacheClient.get(file);
        if (cachedFile) {
          cachedData[file] = JSON.parse(cachedFile);
        }
      } catch (error) {
        console.error(`Error fetching ${file} from cache:`, error);
      }
    });
    return cachedData;
  }

  async fetchMetadata(file) {
    try {
      const response = await axios.get(`${this.apiEndpoint}/${file}`);
      if (!response.data) throw new Error('Failed to fetch metadata');
      return response.data;
    } catch (error) {
      console.error(`Error fetching metadata for ${file}:`, error);
      throw error;
    }
  }

  async processDirectory() {
    const files = await this.filterFiles();
    await Promise.all(files.map((file) => this.processFile(file)));
    const mergedData = await this.mergeData();
    await this.cacheData(mergedData);
    return mergedData;
  }
}

module.exports = FileProcessor;
