            for message in self.kafka_consumer:
                await self.analyze_traffic(message.value.decode())
        except Exception as e:
            logging.error(f"Error consuming traffic: {str(e)}")

    async def analyze_traffic(self, traffic_data: str) -> None:
        try:
            # Parse traffic data into IP addresses and packets
            ip_addresses = [ip for ip in traffic_data.split(",") if ip]

            for ip in ip_addresses:
                # Classify IP using statistical analysis and machine learning models
                classification = await self.classify_ip(ip)

                # Send classified IP to Kafka producer
                await self.kafka_producer.send("classified_traffic", value=classification.encode())
        except Exception as e:
            logging.error(f"Error analyzing traffic: {str(e)}")

    async def classify_ip(self, ip: str) -> str:
