function injectScriptsFooter(scripts) {
  const scriptElements = [];
  let promiseChain = Promise.resolve();

  for (const { src, async } of scripts) {
    const scriptElement = document.createElement('script');
    scriptElement.src = src;
    scriptElement.async = async;
    scriptElements.push(scriptElement);
    promiseChain = promiseChain.then(() => new Promise((resolve, reject) => {
      scriptElement.onload = () => resolve();
      scriptElement.onerror = () => reject();
    }));
  }

  return new Promise((resolve, reject) => {
    document.body.appendChild(document.createElement('div')).appendChild(...scriptElements);
    promiseChain
      .then(() => resolve())
      .catch((error) => reject(error));
  }).then(() => {
    const footer = document.createElement('footer');
    for (const script of scriptElements) {
      footer.appendChild(script);
    }
    return footer.outerHTML;
  });
}
