const { Readable, Writable } = require('stream');
const axios = require('axios');
const PNG = require('pngjs').PNG;

class ImageStream {
  constructor({ cacheSize, imageProcessingServiceUrl }) {
    this.cache = new Map();
    this.readable = new Readable({
      objectMode: true,
      read(size) {
        const chunk = Buffer.alloc(size);
        this.push(chunk);
      }
    });
    this.writable = new Writable({
      objectMode: true,
      write(chunk, encoding, callback) {
        this.cache.set(Date.now(), chunk);
        callback();
      }
    });
    this.imageProcessingServiceUrl = imageProcessingServiceUrl;
  }

  async start() {
    const { data } = await axios.get('https://example.com/image-stream', {
      responseType: 'arraybuffer'
    });
    this.readable.push(data);

    process.on('SIGINT', () => {
      this.pause();
    });

    setImmediate(() => {
      this.resume();
    });
  }

  async pause() {
    this.readable.emit('pause');
  }

  async resume() {
    this.readable.emit('resume');
  }

  async decodePNG(chunk) {
    const png = new PNG({ filterType: 2 });
    png.data.push(...chunk);
    await new Promise((resolve) => setTimeout(resolve, 100));
    return png.encode();
  }
}

module.exports = ImageStream;
