import { Document } from 'html-parse';
import axios from 'axios';

interface ElementCriteria {
  class: string;
  id: string;
  attribute: string;
}

async function selectDOMElements(rootElement: Element | null, criteria: ElementCriteria[], apiEndpoints: string[]): Promise<Element[]> {
  const domTree = new Document();
  if (!rootElement) throw new Error('Root element is required');

  const selectedElements: Element[] = [];
  await traverseDOMTree(domTree, rootElement, criteria);

  // Integrate with external APIs
  for (const apiEndpoint of apiEndpoints) {
    try {
      const response = await axios.get(apiEndpoint);
      if (response.data && Array.isArray(response.data)) {
        selectedElements.push(...response.data);
      }
    } catch (error) {
      console.error(`Error fetching data from ${apiEndpoint}:`, error);
    }
  }

  return selectedElements;

  async function traverseDOMTree(domTree: Document, element: Element | null, criteria: ElementCriteria[]) {
    if (!element) return;
    const elementsMatchingCriteria = domTree.querySelectorAll(`.${criteria.class}#${criteria.id}[${criteria.attribute}]`);
    for (const matchingElement of elementsMatchingCriteria) {
      selectedElements.push(matchingElement);
    }
    await Promise.all(elementsMatchingCriteria.map(async (element) => traverseDOMTree(domTree, element, criteria)));
  }
}

export { selectDOMElements };
