import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;
import io.vertx.core.Vertx;
import io.vertx.core.http.HttpServerOptions;
import io.vertx.core.net.JksOptions;
import io.vertx.ext.web.RoutingContext;
import io.vertx.ext.web.handler.BodyHandler;
import io.vertx.ext.web.handler.CorsHandler;
import io.vertx.ext.web.handler.ErrorHandler;
import org.apache.commons.lang3.tuple.Pair;

import java.io.IOException;
import java.util.*;

public class UserInteractionService {
    private static final int MAX_BATCH_SIZE = 1000;
    private static final int REQUEST_TIMEOUT_MILLIS = 30000;
    private static final String INTERACTION_API_ENDPOINT = "https://interaction-api.com";
    private static final String UNIFIED_LOGGING_ID = "user-interaction-service";

    private Vertx vertx;
    private Cache<String, Set<String>> userPairCache;
    private UnionFind unionFind;

    public UserInteractionService(Vertx vertx) {
        this.vertx = vertx;
        this.userPairCache = CacheBuilder.newBuilder()
                .maximumSize(10000)
                .build();
        this.unionFind = new UnionFind();

        vertx.createHttpServer(new HttpServerOptions().setHost("0.0.0.0").setPort(8080))
                .requestHandler(BodyHandler.create())
                .handler(CorsHandler.create("*", "*"))
                .handler(ErrorHandler.create())
                .listen(routingContext -> {
                    System.out.println("User Interaction Service started on port 8080");
                });
    }

    public void processUserPairs(Pair<String, String> userPair) {
        if (!userPairCache.getIfPresent(userPair.getLeft()).contains(userPair.getRight())) {
            unionFind.union(userPair.getLeft(), userPair.getRight());
        }
    }

    private class UnionFind {
        private Map<String, Integer> parent = new HashMap<>();
        private Map<String, Integer> rank = new HashMap<>();

        public void union(String u, String v) {
            int rootU = find(u);
            int rootV = find(v);

            if (rootU != rootV) {
                if (rank.getOrDefault(rootU, 0) < rank.getOrDefault(rootV, 0)) {
                    parent.put(rootU, rootV);
                } else if (rank.getOrDefault(rootU, 0) > rank.getOrDefault(rootV, 0)) {
                    parent.put(rootV, rootU);
                } else {
                    parent.put(rootV, rootU);
                    rank.put(rootU, rank.getOrDefault(rootU, 0) + 1);
                }
            }
        }

        public int find(String u) {
            if (!parent.containsKey(u)) {
                parent.put(u, u);
                rank.put(u, 0);
            }

            if (u.equals(parent.get(u))) {
                return u;
            } else {
                parent.put(u, find(parent.get(u)));
                return parent.get(u);
            }
        }
    }
}
