// Define the environment-specific security module
mod security {
    use reqwest::blocking::get;

    pub fn disable_certificate_validation(is_development: bool) -> Result<(), Box<dyn std::error::Error>> {
        if is_development {
            // Disable certificate validation in development environments
            println!("Certificate validation disabled for development");
        } else {
            // Enforce strict SSL/TLS verification elsewhere
            println!("Certificate validation enabled for production/staging");
        }
