mod errors {
    use reqwest::blocking::get;
    use std::time::{Duration, Instant};

    pub enum ErrorType {
        Temporary,
        Permanent,
    }

    pub fn handle_error(err: &reqwest::Error) -> Result<(), Box<dyn std::error::Error>> {
        match err.kind() {
            reqwest::ErrorKind::ConnectTimeout => {
                // Handle connection timeouts
                println!("Connection timeout occurred");
            }
            reqwest::ErrorKind::ReadTimeout => {
                // Handle read timeouts
                println!("Read timeout occurred");
            }
            _ => {
                // Handle other types of errors
                println!("Unknown error occurred: {}", err.to_string());
            }
        }

        Ok(())
    }

    pub fn retry_request(req: &reqwest::blocking::RequestBuilder, max_retries: u32) -> Result<(), Box<dyn std::error::Error>> {
        let mut retries = 0;
        let start_time = Instant::now();

        loop {
            match req.send() {
                Ok(response) => return response.error_for_status(),
                Err(err) => {
                    if retries < max_retries {
                        // Handle transient errors
                        println!("Transient error occurred. Retrying in {} seconds", 5);
                        std::thread::sleep(std::time::Duration::from_millis(5000));
                        continue;
                    } else {
                        // Handle permanent errors
                        return Err(Box::new(reqwest::Error::new(err, "Permanent error")));
                    }
                }
            }

            retries += 1;
        }
    }
}

