```rust
use std::path::{Path, PathBuf};
use std::process::Command;
use log::{info, error};
use chrono::prelude::*;

mod compiler {
    use std::process::Command;
    pub struct Compiler {
        root_dir: String,
    }

    impl Compiler {
        fn new(root_dir: &str) -> Self {
            Compiler {
                root_dir: root_dir.to_string(),
            }
        }

        pub fn compile(&self, crate_name: &str) -> Result<(), String> {
            let command = format!("cargo build --manifest-path {}/Cargo.toml --quiet", self.root_dir);
            match Command::new("bash")
                .arg("-c")
                .arg(&format!("cd {} && {}", self.root_dir, command))
                .output()
            {
                Ok(output) => {
                    let stdout = String::from_utf8_lossy(&output.stdout);
                    let stderr = String::from_utf8_lossy(&output.stderr);

                    if !stdout.is_empty() {
                        info!("{}", stdout.trim());
                    }

                    if !stderr.is_empty() {
                        error!("{}", stderr.trim());
                    }

                    Ok(())
                }
                Err(err) => Err(format!("Error compiling {}: {}", crate_name, err)),
            }
        }
    }
}

mod logger {
    use log::{info, error};
    use chrono::prelude::*;

    pub fn compile_log(crate_name: &str, result: Result<(), String>) -> String {
        let now = Utc::now().to_rfc3339();

        match result {
            Ok(_) => format!("{} | Compiled {} successfully.", now, crate_name),
            Err(err) => format!("{} | Error compiling {}: {}", now, crate_name, err),
        }
    }
}

fn main() {
    let root_dir = "path/to/your/crates";

    let compiler = compiler::Compiler::new(root_dir);
    let logger = logger::Logger;

    if let Err(err) = compiler.compile("my_crate") {
        error!("{}", err);
    } else {
        info!("{}", logger.compile_log("my_crate", Ok(())));
    }
}

