<?php

class UserService {
    private $db;
    private $authApi;
    private $messageQueue;

    public function __construct($db, $authApi, $messageQueue) {
        $this->db = $db;
        $this->authApi = $authApi;
        $this->messageQueue = $messageQueue;
    }

    public function updateUserPassword($userId, $newPassword): Promise {
        $promise = new Promise();

        // Perform database read to retrieve existing user data
        $user = $this->db->getUser($userId);

        if (!$user) {
            return $promise->reject(false); // User not found
        }

        // Offload password complexity check to message queue
        $this->messageQueue->send([
            'type' => 'validate_password',
            'data' => ['password' => $newPassword],
            'callback' => function ($result) use ($promise, $user, $userId) {
                if (!$result['valid']) {
                    return $promise->reject(false); // Password invalid
                }

                // Update user password in database
                $this->db->updateUserPassword($user['id'], $newPassword);

                // Verify updated password meets security policies using auth API
                $authResult = $this->authApi->validatePassword($userId, $newPassword);
                if (!$authResult) {
                    return $promise->reject(false); // Password update failed
                }

                return $promise->resolve(true); // Success
            }
        ]);

        return $promise;
    }
}

