import json
import requests
from functools import lru_cache
from threading import Lock
from logging import getLogger

class SequenceHandler:
    def __init__(self, api_url: str, cache_size: int = 100):
        self.api_url = api_url
        self.cache_size = cache_size
        self.sequence_cache = {}
        self.lock = Lock()
        self.logger = getLogger(__name__)

    @lru_cache(maxsize=cache_size)
    def get_sequence(self, sequence_id: str) -> dict:
        try:
            response = requests.get(f"{self.api_url}/sequences/{sequence_id}")
            response.raise_for_status()  # Raise exception for bad status code
            return json.loads(response.text)
        except requests.exceptions.RequestException as e:
            self.logger.error(f"Failed to fetch sequence {sequence_id}: {e}")
            raise

    def update_sequence(self, sequence_id: str, new_values: list) -> None:
        try:
            response = requests.put(f"{self.api_url}/sequences/{sequence_id}", json={"values": new_values})
            response.raise_for_status()  # Raise exception for bad status code
        except requests.exceptions.RequestException as e:
            self.logger.error(f"Failed to update sequence {sequence_id}: {e}")
            raise

    def get_current_value(self, sequence_id: str) -> int | None:
        with self.lock:
            if sequence_id not in self.sequence_cache:
                self.sequence_cache[sequence_id] = self.get_sequence(sequence_id)
            return self.sequence_cache[sequence_id].get("current_value")

    def put_current_value(self, sequence_id: str, value: int) -> None:
        try:
            response = requests.put(f"{self.api_url}/sequences/{sequence_id}", json={"current_value": value})
            response.raise_for_status()  # Raise exception for bad status code
        except requests.exceptions.RequestException as e:
            self.logger.error(f"Failed to update current value of sequence {sequence_id}: {e}")
            raise

    def get_historical_values(self, sequence_id: str) -> list | None:
        try:
            response = requests.get(f"{self.api_url}/sequences/{sequence_id}/history")
            response.raise_for_status()  # Raise exception for bad status code
            return json.loads(response.text)
        except requests.exceptions.RequestException as e:
            self.logger.error(f"Failed to fetch historical values of sequence {sequence_id}: {e}")
            raise

    def get_sequence_transformations(self, sequence_id: str) -> list | None:
        try:
            response = requests.get(f"{self.api_url}/sequences/{sequence_id}/transformations")
            response.raise_for_status()  # Raise exception for bad status code
            return json.loads(response.text)
        except requests.exceptions.RequestException as e:
            self.logger.error(f"Failed to fetch sequence transformations of sequence {sequence_id}: {e}")
            raise

    def apply_sequence_transformation(self, sequence_id: str, transformation_name: str) -> None:
        try:
            response = requests.post(
                f"{self.api_url}/sequences/{sequence_id}/transformations/{transformation_name}",
                json={"transformed_values": []},
            )
            response.raise_for_status()  # Raise exception for bad status code
        except requests.exceptions.RequestException as e:
            self.logger.error(f"Failed to apply sequence transformation {transformation_name} of sequence {sequence_id}: {e}")
            raise

# Example usage:

handler = SequenceHandler("https://api.example.com")
try:
    current_value = handler.get_current_value("my_sequence")
    print(current_value)
except Exception as e:
    print(f"Error: {e}")

try:
    transformed_values = handler.apply_sequence_transformation("my_sequence", "moving_average")
    print(transformed_values)
except Exception as e:
    print(f"Error: {e}")
