#include <stdlib.h>
#include <string.h>

typedef struct State {
    int id;
    int next;
} State;

State* create_state_list(int** states, int state_count, int last_state_id) {
    if (!states || !state_count || last_state_id < 0) return NULL;

    // Create a new state list
    State* new_states = (State*)malloc((state_count + 1) * sizeof(State));
    if (!new_states) return NULL;

    // Initialize the first state
    new_states[0].id = 0;
    new_states[0].next = -1; // No next state

    for (int i = 1; i <= last_state_id; i++) {
        new_states[i] = states[i];
    }

    return new_states;
}

int main() {
    int* states = (int*)malloc(5 * sizeof(int));
    states[0] = 0;
    states[1] = 1;
    states[2] = 2;
    states[3] = 3;
    states[4] = 4;

    State* new_states = create_state_list(&states, 5, 4);

    return 0;
}
