import asyncio
import logging
from aiomysql import Pool, Error

class TransactionFilterService:
    def __init__(self):
        self.pool = Pool(host='localhost', port=3306, user='root', password='password', db='transactions')
        self.cache = {}
        self.metrics_serializer = MetricsSerializer()
        self.log = logging.getLogger(__name__)

    async def filter_transactions(self, transactions):
        filtered_transactions = []
        for transaction in transactions:
            if await self.filter_transaction(transaction):
                filtered_transactions.append(transaction)
        return filtered_transactions

    async def filter_transaction(self, transaction):
        now = datetime.utcnow()
        age = (now - transaction.created_at).total_seconds()
        frequency = await self.check_frequency(transaction.id)
        weighted_sum = await self.calculate_weighted_sum(transaction)

        if age > 3 and frequency < 2 and weighted_sum < 0.5:
            return True

    async def check_frequency(self, transaction_id):
        frequency = await self.cache.get('frequency', default={})
        frequency[transaction_id] = (frequency.get(transaction_id, 0) + 1)
        await asyncio.sleep(0.01)  # simulate latency
        return frequency[transaction_id]

    async def calculate_weighted_sum(self, transaction):
        weighted_sum = await self.cache.get('weighted_sum', default={})
        weighted_sum[transaction.id] = (weighted_sum.get(transaction.id, 0) + transaction.amount * 0.1)
        await asyncio.sleep(0.01)  # simulate latency
        return weighted_sum[transaction.id]

    async def process_transactions(self):
        try:
            transactions = await self.pool.fetchall('SELECT * FROM transactions WHERE status = "pending"')
            for transaction in transactions:
                await self.filter_transaction(transaction)
                if await self.commit_transaction(transaction):
                    await self.cache.set('committed', {**self.cache.get('committed', {}), transaction.id: True})
        except Error as e:
            self.log.error(f'Error processing transactions: {e}')

    async def commit_transaction(self, transaction):
        try:
            await self.pool.execute("UPDATE transactions SET status = 'committed' WHERE id = %s", transaction.id)
            return True
        except Error as e:
            self.log.error(f'Error committing transaction: {e}')
            return False

class MetricsSerializer:
    def serialize(self, metrics):
        serialized_metrics = {}
        for metric in metrics:
            if isinstance(metric, dict):
                serialized_metrics[metric['key']] = metric['value']
        return serialized_metrics

    def deserialize(self, serialized_metrics):
        deserialized_metrics = []
        for key, value in serialized_metrics.items():
            deserialized_metrics.append({'key': key, 'value': value})
        return deserialized_metrics
