    AttackManager() : cooldowns(), lock(false) {}

    void addAttack(int characterId, Attack attack) {
        // Add the attack to the vector of available attacks
        attacks[characterId].push_back(attack);
    }

    void executeAttack(int characterId, int attackIndex) {
        if (attackIndex < 0 || attackIndex >= attacks[characterId].size())
            return;

        Attack currentAttack = attacks[characterId][attackIndex];
        // Check cooldown status
        if (cooldowns[characterId] > 0)
            return;

        // Start the attack execution
        startAttackExecution(currentAttack);
    }

private:
    std::vector<Attack> attacks[1001]; // Initialize with 1001 to accommodate 1000 characters and one more for future use
    std::vector<int> cooldowns(1001, 0); // Initialize cooldowns for each character
    bool lock;
    std::mutex mtx;
    std::condition_variable cv;

    void startAttackExecution(Attack attack) {
        // Simulate the execution of the attack
        auto start = std::chrono::high_resolution_clock::now();
        // Execute the attack logic here...
        auto end = std::chrono::high_resolution_clock::now();

        // Log the attack details
        std::cout << "Character ID: " << 1 << ", Attack: " << attack.name << ", Start Time: " << start.time_since_epoch().count() << ", End Time: " << end.time_since_epoch().count() << std::endl;

        // Update cooldowns for future attacks
        int cooldownTime = attack.cooldown;
        while (cooldownTime > 0) {
            cooldowns[1] -= 1; // Simulate the decrement of the cooldown timer
            if (cooldowns[1] <= 0)
                break;

            std::unique_lock<std::mutex> lock(mtx);
            cv.wait_for(lock, std::chrono::seconds(1));
        }
    }
};

