import re
import statistics
from datetime import datetime
from logging import Logger, getLogger

class TextProcessor:
    def __init__(self):
        self.logger = getLogger(__name__)
        self.min_numeric_fields = 2

    def process_file(self, input_file: str, output_file: str) -> None:
        with open(input_file, 'r') as f_in, open(output_file, 'w') as f_out:
            for line in f_in:
                fields = re.split(r'\W+', line.strip())
                if len(fields) < self.min_numeric_fields:
                    continue
                try:
                    last_two_nums = [float(field) for field in fields[-2:] if field.isnumeric()]
                    if len(last_two_nums) < 2:
                        raise ValueError("Invalid numeric data")
                    avg = statistics.mean(last_two_nums)
                    fields[-1] = str(avg)
                    f_out.write(' '.join(fields) + '\n')
                except (ValueError, Exception) as e:
                    self.logger.error(f"Error processing line: {e}")
                    f_out.write(line)

if __name__ == '__main__':
    processor = TextProcessor()
    processor.process_file('input.txt', 'output.txt')
