    // Generate a random number to prevent identical timestamps
    srand((unsigned int) timestamp);
    int rand_num = rand();

    // Combine the hash, timestamp, and prefix to create the GUID
    char* guid = (char*) malloc(strlen(hash) + 10); // Assuming 10 chars for timestamp and prefix
    sprintf(guid, "%s%lu%s", hash, timestamp + rand_num, prefix);

    *guid_out = guid;
