#define MAX_PASSWORD_LENGTH 64
#define MIN_KEY_SIZE 32
#define IV_SIZE 16

typedef struct {
    uint8_t *key;
    uint8_t *iv;
} EncryptionContext;

void derive_key_and_iv(char *password, int password_length,
                        uint8_t **derived_key, uint8_t **iv) {
    // Set up PBKDF2 parameters
    const EVP_MD *digest = EVP_sha256();
    const EVP_PBE_CTX *pbe_ctx = NULL;
    uint32_t iterations = 100000;

    // Derive the key and IV using PBKDF2
    uint8_t salt[] = {0x12, 0x34, 0x56, 0x78, 0x90, 0xAB, 0xCD, 0xEF};
    size_t derived_key_len = MIN_KEY_SIZE;
    size_t iv_len = IV_SIZE;

    *derived_key = (uint8_t *)OPENSSL_malloc(derived_key_len);
    *iv = (uint8_t *)OPENSSL_malloc(iv_len);

    PBKDF2_CTX *ctx = PBKDF2_CTX_new();
    PBKDF2_init(ctx, NULL, password, password_length, salt,
                 sizeof(salt), iterations, digest, derived_key_len + iv_len,
                 &derived_key_len, &iv_len);

    uint8_t *derived_data = (uint8_t *)OPENSSL_malloc(derived_key_len + iv_len);
    PBKDF2(ctx, NULL, password, password_length, salt,
           sizeof(salt), iterations, digest, derived_data, derived_key_len + iv_len);

    // Extract the key and IV from the derived data
    memcpy(*derived_key, &derived_data[0], MIN_KEY_SIZE);
    memcpy(*iv, &derived_data[MIN_KEY_SIZE], IV_SIZE);

    OPENSSL_free(derived_data);
    PBKDF2_CTX_free(ctx);
}

int encrypt_data(uint8_t *data, size_t data_len,
                 uint8_t *key, uint8_t *iv, uint8_t **encrypted_data) {
    // Set up AES-256-CBC encryption
    AES_KEY enc_key;
    AES_cbc_encrypt_init(&enc_key, key, MIN_KEY_SIZE);

    // Encrypt the data using AES-256-CBC
    uint8_t *encrypted_buffer = (uint8_t *)OPENSSL_malloc(data_len + 16);
    size_t encrypted_data_len = AES_cbc_encrypt(data, encrypted_buffer,
                                                 data_len, &enc_key, iv, 1);

    // Store the encrypted data and its length
    *encrypted_data = encrypted_buffer;
    return encrypted_data_len;
}

int decrypt_data(uint8_t *data, size_t data_len,
                 uint8_t *key, uint8_t *iv, uint8_t **decrypted_data) {
    // Set up AES-256-CBC decryption
    AES_KEY dec_key;
    AES_cbc_encrypt_init(&dec_key, key, MIN_KEY_SIZE);

    // Decrypt the data using AES-256-CBC
    uint8_t *decrypted_buffer = (uint8_t *)OPENSSL_malloc(data_len);
    size_t decrypted_data_len = AES_cbc_decrypt(data, decrypted_buffer,
                                                 data_len, &dec_key, iv, 1);

    // Store the decrypted data and its length
    *decrypted_data = decrypted_buffer;
    return decrypted_data_len;
}

int main() {
    // Example usage: Derive a key and IV from a password, then encrypt and decrypt some sample data

    char password[] = "my_secret_password";
    int password_length = strlen(password);

    EncryptionContext ctx;
    derive_key_and_iv(password, password_length, &ctx.key, &ctx.iv);

    uint8_t *data = (uint8_t *)malloc(1024);
    size_t data_len = 1024;

    // Encrypt the data
    uint8_t *encrypted_data;
    int encrypted_len = encrypt_data(data, data_len, ctx.key, ctx.iv,
                                       &encrypted_data);
    printf("Encrypted data: %s\n", encrypted_data);

    // Decrypt the data
    uint8_t *decrypted_data;
    int decrypted_len = decrypt_data(encrypted_data, encrypted_len, ctx.key,
                                      ctx.iv, &decrypted_data);
    printf("Decrypted data: %s\n", decrypted_data);

    // Clean up
    OPENSSL_free(ctx.key);
    OPENSSL_free(ctx.iv);
    free(data);
    free(encrypted_data);
    free(decrypted_data);

    return 0;
}
```

Note that this code is just an example implementation, and you should consider implementing additional error handling mechanisms to handle potential failures during key derivation, data encryption, and decryption processes.']

