    pthread_t thread;
    int status;
    int id;
} Command;

Command commands[MAX_QUEUE_SIZE];
int command_id = 0;
int num_commands = 0;

sem_t semaphore;

void* execute_command(void* arg) {
    Command* cmd = (Command*)arg;

    // Execute the command here
    system(cmd->command);

    // Update the status of the command
    cmd->status = 1; // Replace with actual status value

    return NULL;
}

int create_command(char* cmd, int id) {
    if(num_commands >= MAX_QUEUE_SIZE) {
        printf("Command queue is full.\n");
        return -1;
    }

    commands[num_commands].command = cmd;
    commands[num_commands].id = id;

    // Create a new thread for the command
    pthread_create(&commands[num_commands].thread, NULL, execute_command, &commands[num_commands]);

    num_commands++;

    return 0;
}

void query_command_status(int id) {
    int i;
    for(i = 0; i < num_commands; i++) {
        if(commands[i].id == id) {
            printf("Command with ID %d has status: %d\n", id, commands[i].status);
            return;
        }
    }

    printf("No command found with ID %d.\n", id);
}

void get_command_logs(int id) {
    int i;
    for(i = 0; i < num_commands; i++) {
        if(commands[i].id == id) {
            // Return the logs for the command here
            return;
        }
    }

    printf("No command found with ID %d.\n", id);
}

int main() {
    sem_init(&semaphore, 0, MAX_QUEUE_SIZE);

    while(1) {
        int choice;
        printf("Enter 1 to create a new command, 2 to query command status, or 3 to get command logs: ");
        scanf("%d", &choice);

        if(choice == 1) {
            char cmd[100];
            int id;
            printf("Enter the command and ID: ");
            scanf("%s %d", cmd, &id);
            create_command(cmd, id);
        } else if(choice == 2) {
            int id;
            printf("Enter the command ID to query status: ");
            scanf("%d", &id);
            query_command_status(id);
        } else if(choice == 3) {
            int id;
            printf("Enter the command ID to get logs: ");
            scanf("%d", &id);
            get_command_logs(id);
        }
    }

    sem_destroy(&semaphore);

    return 0;
}
