namespace ModularConsoleApp
{
    class Program
    {
        static void Main(string[] args)
        {
            while (true)
            {
                Console.WriteLine("Enter '1' for largest integer, '2' for decryption, or 'q' to quit:");
                string choice = Console.ReadLine();
                switch (choice)
                {
                    case "1":
                        LargestInteger();
                        break;
                    case "2":
                        Decrypt();
                        break;
                    case "q":
                        Environment.Exit(0);
                        break;
                    default:
                        Console.WriteLine("Invalid input. Please try again.");
                        break;
                }
            }
        }

        static void LargestInteger()
        {
            Console.Write("Enter integers (space-separated) or 'q' to quit: ");
            string[] inputs = Console.ReadLine().Split(' ');
            int max = int.MinValue;
            foreach (string s in inputs)
            {
                if (!string.IsNullOrEmpty(s))
                {
                    try
                    {
                        int num = Convert.ToInt32(s);
                        if (num > max) max = num;
                    }
                    catch
                    {
                        Console.WriteLine("Invalid integer. Skipping...");
                    }
                }
            }
            Console.WriteLine($"Largest integer: {max}");
        }

        static void Decrypt()
        {
            Console.Write("Enter Base64-encoded message or 'q' to quit: ");
            string encoded = Console.ReadLine();
            if (string.IsNullOrEmpty(encoded) || !Base64.IsEncoded(encoded))
            {
                Console.WriteLine("Invalid Base64 string. Skipping...");
                return;
            }
            try
            {
                byte[] decoded = Convert.FromBase64String(encoded);
                Aes des = Aes.Create();
                des.Key = ASCIIEncoding.GetBytes("your_secret_key");
                des.IV = ASCIIEncoding.GetBytes("your_initialization_vector");
                ICryptoTransform encryptor = des.CreateEncryptor();
                byte[] decrypted = decryptStream(new MemoryStream(decoded), encryptor);
                Console.WriteLine($"Decrypted message: {ASCII.GetString(decrypted)}");
            }
            catch (Exception ex)
            {
                Console.WriteLine("Decryption failed. Error: " + ex.Message);
            }
        }

        static byte[] decryptStream(MemoryStream stream, ICryptoTransform transform)
        {
            byte[] result = new byte[stream.Length];
            int read;
            CryptoStream cs = new CryptoStream(stream, transform, CryptoStreamMode.Read);
            using (MemoryStream ms = new MemoryStream())
            {
                do
                {
                    read = cs.Read(result, 0, result.Length);
                }
                while (read > 0);
                return ms.ToArray();
            }
        }
    }

    public static class Base64
    {
        public static bool IsEncoded(string str)
        {
            try
            {
                Convert.FromBase64String(str);
                return true;
            }
            catch
            {
                return false;
            }
        }
    }
}
