    private readonly HttpClient _httpClient;
    private readonly IMemoryCache _memoryCache;
    private readonly ICustomSerializer _serializer;

    public DataProcessor(HttpClient httpClient, IMemoryCache memoryCache, ICustomSerializer serializer)
    {
        _httpClient = httpClient;
        _memoryCache = memoryCache;
        _serializer = serializer;
    }

    public async Task ProcessEncryptedData(string filePath, CancellationToken cancellationToken, Action<Exception> onError = null)
    {
        // Retrieve encryption key and IV from external API
        await FetchEncryptionKeyAndIV();

        using var fileStream = new FileStream(filePath, FileMode.Open);
        await ProcessFile(fileStream, cancellationToken, onError);
    }

    private async Task FetchEncryptionKeyAndIV()
    {
        if (_memoryCache.TryGetValue("encryptionKey", out byte[] key) && _memoryCache.TryGetValue("iv", out byte[] iv))
            return;

        var response = await _httpClient.GetAsync("https://api.example.com/encryption-keys");
        response.EnsureSuccessStatusCode();
        var encryptionKeyResponse = await response.Content.ReadAsByteArrayAsync();
        var encryptionKey = encryptionKeyResponse.Take(32).ToArray(); // assuming 256-bit key
        var iv = encryptionKeyResponse.Skip(32).Take(16).ToArray(); // assuming 128-bit IV

        _memoryCache.Set("encryptionKey", encryptionKey);
        _memoryCache.Set("iv", iv);
    }

    private async Task ProcessFile(Stream fileStream, CancellationToken cancellationToken, Action<Exception> onError)
    {
        byte[] buffer = new byte[1024 * 1024]; // adjust chunk size according to your requirements
        using var decryptor = AesDecryptor.Create(_memoryCache.GetByteArray("encryptionKey"), _memoryCache.GetByteArray("iv"));

