// Define upload validation rules
const fileTypes = ['image/jpeg', 'application/pdf'];
const fileSizeLimit = 100 * 1024 * 1024; // 100MB

// Define worker pool configuration
const workerPoolSize = 5;
const workerQueueSize = 10;

// Define error handling and recovery strategy
const maxRetries = 3;
const retryDelayMs = 5000;
const circuitBreakerTimeoutMs = 60000;

