const express = require('express');
const { ConfigurationAPI } = require('./config-api');
const { SedCommand } = require('./sed-command');
const { Logger } = require('./logger');
const { Cacher } = require('./cacher');

const app = express();

app.use(express.json());

const configurationAPI = new ConfigurationAPI();
const sedCommand = new SedCommand();
const logger = new Logger('kickstart-service');
const cacher = new Cacher({ ttl: 3600, concurrency: 5 });

app.post('/update-config', async (req, res) => {
  try {
    const { configData, password } = req.body;
    const cachedConfig = await cacher.get(configData.configId);
    if (!cachedConfig) {
      const configResponse = await configurationAPI.getConfig(configData);
      if (!configResponse) {
        throw new Error('Failed to retrieve config from API');
      }
      const updatedConfig = await sedCommand.updateConfig(configResponse, configData);
      cacher.set(configData.configId, updatedConfig);
    } else {
      logger.info(`Using cached config for ${configData.configId}`);
    }

    const encryptedPassword = await password.encrypt();
    await sedCommand.appendPassword(updatedConfig, encryptedPassword);

    await configurationAPI.updateConfig(updatedConfig, configData);
  } catch (error) {
    logger.error('Error updating config:', error);
    res.status(500).send({ message: 'Failed to update config' });
  }
});

app.listen(3000, () => {
  logger.info('Kickstart service listening on port 3000');
});
