from datetime import datetime, timedelta
import time
import requests
import pandas as pd
import numpy as np
from flask import Flask, request, jsonify
from flask_caching import Cache
from flask_sqlalchemy import SQLAlchemy
from celery import Celery

app = Flask(__name__)
cache = Cache(app, config={'CACHE_TYPE': 'SimpleCache'})
db = SQLAlchemy(app)

celery_app = Celery('tasks', broker='amqp://guest:guest@localhost')

class StockData(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    symbol = db.Column(db.String(10), nullable=False)
    price = db.Column(db.Float, nullable=False)
    timestamp = db.Column(db.DateTime, default=datetime.utcnow)

@app.route('/stock_data', methods=['GET'])
def get_stock_data():
    stocks = StockData.query.all()
    return jsonify([{'symbol': s.symbol, 'price': s.price} for s in stocks])

@celery_app.task
def fetch_stock_data(symbol):
    response = requests.get(f'https://api.example.com/{symbol}')
    data = response.json()
    cache.set(f'stock_{symbol}', data, timeout=3600)
    return data

@app.route('/moving_average', methods=['GET'])
def get_moving_average():
    symbol = request.args.get('symbol')
    window_size = int(request.args.get('window_size'))
    stock_data = cache.get(f'stock_{symbol}')
    if not stock_data:
        stock_data = fetch_stock_data(symbol).get()
    data = pd.DataFrame(stock_data)
    ma = data.rolling(window=window_size).mean()
    return jsonify(ma.tolist())

@app.route('/trending_stocks', methods=['GET'])
def get_trending_stocks():
    stocks = StockData.query.all()
    trending_stocks = []
    for stock in stocks:
        price_diff = (stock.price - cache.get(f'stock_{stock.symbol}')['price']) / 100
        if abs(price_diff) > 0.5:
            trending_stocks.append({'symbol': stock.symbol, 'price_diff': price_diff})
    return jsonify(trending_stocks)

@app.route('/custom_metric', methods=['POST'])
def calculate_custom_metric():
    data = request.get_json()
    metric_name = data['metric_name']
    if metric_name == 'ema':
        ema = np.mean(data['stock_data']['close']) * 2 - np.mean(data['stock_data']['close']) 
        return jsonify({'ema': ema})
    elif metric_name == 'rsi':
        rsi = [0] * len(data['stock_data']['close'])
        for i in range(len(rsi)):
            gain, loss = 0, 0
            for j in range(i+1):
                if data['stock_data']['close'][j] > data['stock_data']['open'][j]:
                    gain += data['stock_data']['close'][j] - data['stock_data']['open'][j]
                else:
                    loss -= data['stock_data']['close'][j] - data['stock_data']['open'][j]
            rs = abs(gain) / loss
            rsi[i] = 100 - (100 / (1 + rs))
        return jsonify({'rsi': rsi})

if __name__ == '__main__':
    app.run(debug=True)
