// Function to rename a file
void rename_file(char *filename, char *directory) {
    // Split the filename into name and extension
    char *name = strtok(filename, ".");
    char *extension = strtok(NULL, ".");

    // Count the number of numeric characters in the name
    int count = 0;
    for (int i = 0; i < strlen(name); i++) {
        if (isdigit(name[i])) {
            count++;
        }
    }

    // Create a new filename by appending the count to the existing extension
    char *new_filename = malloc(strlen(directory) + strlen(name) + strlen(extension) + sizeof(int));
    sprintf(new_filename, "%s/%s_%d.%s", directory, name, count, extension);

    // Check for naming conflicts and implement retry logic if necessary
    int attempts = 0;
    while (access(new_filename, F_OK) == -1 && attempts < 5) {
        attempt++;
        sprintf(new_filename, "%s/%s_%d.%s", directory, name, count++, extension);
    }

    // Move the original file to the new filename
    rename(filename, new_filename);

    free(new_filename);
}

