namespace RealTimeValueGenerator
{
    public class RealTimeValueGenerator
    {
        private readonly Random _random = new();
        private readonly object _syncLock = new();
        private double _minValue, _maxValue;

        public RealTimeValueGenerator(double minValue, double maxValue)
        {
            _minValue = minValue;
            _maxValue = maxValue;
        }

        public double GenerateDoubleValue()
        {
            return _random.NextDouble() * (_maxValue - _minValue) + _minValue;
        }

        public int GenerateIntValue(int min, int max)
        {
            return _random.Next(min, max);
        }

        public async Task AdjustRangeAsync(double newMinValue, double newMaxValue)
        {
            lock (_syncLock)
            {
                if (newMaxValue < newMinValue)
                {
                    throw new ArgumentException("New maximum value cannot be less than the minimum value.");
                }
                _minValue = newMinValue;
                _maxValue = newMaxValue;
            }
        }

        public async Task<int> GetRandomInteger(int min, int max)
        {
            return await Task.Run(() => _random.Next(min, max));
        }
    }
}
