// Function to manage state transitions in a distributed FSA
void manage_state_transition(DistributedFSA *fsa, int* current_state_list, int num_states, int last_state) {

    // Create a new state and append it to the list
    FSAState* new_state = (FSAState*)malloc(sizeof(FSAState));
    *new_state.id = fsa->num_states;
    memcpy(&fsa->states[fsa->num_states], &new_state, sizeof(FSAState));
    fsa->num_states++;

    // Validate the integrity of the state list
    for(int i = 0; i < fsa->num_states; i++) {
        if(fsa->states[i].id != i) {
            printf("Invalid state transition! Rolling back to previous state.\n");
            return;
        }
    }

    // Implement a rollback mechanism for invalid state transitions
    if(last_state >= fsa->num_states) {
        for(int i = last_state; i < fsa->num_states; i++) {
            free(fsa->states[i]);
        }
        fsa->num_states = last_state;
    }

    // Optimize the function to automatically merge consecutive states with identical behavior
    for(int i = 0; i < fsa->num_states - 1; i++) {
        if(memcmp(&fsa->states[i], &fsa->states[i+1], sizeof(FSAState)) == 0) {
            free(fsa->states[i+1]);
            fsa->num_states--;
            i--;
        }
    }

    // Update the 'next' pointer of the last state
    fsa->last_state = &fsa->states[fsa->num_states - 1];
}

