        private final AtomicLong sequence = new AtomicLong();

        @GetMapping("/tokens")
        public ResponseEntity<List<Token>> getTokens() {
            List<Token> tokens = new ArrayList<>(tokenMap.values());
            return new ResponseEntity<>(tokens, HttpStatus.OK);
        }

        @PostMapping("/tokens")
        public ResponseEntity<Token> createToken(@RequestBody Token token) {
            if (!validateToken(token)) {
                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
            }
            token.setId(sequence.incrementAndGet().toString());
            tokenMap.put(token.getId(), token);
            return new ResponseEntity<>(token, HttpStatus.CREATED);
        }

        @PutMapping("/tokens/{id}")
        public ResponseEntity<Token> updateToken(@PathVariable String id, @RequestBody Token token) {
            if (!validateToken(token)) {
