// Define the structure for a command
typedef struct {
    int id;
    char* name;
    char* params;
} Command;

// Define the structure for a scheduler
typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int queue_size;
    Command** queue;
} Scheduler;

// Function to create and initialize the scheduler
Scheduler* create_scheduler() {
    Scheduler* s = (Scheduler*)malloc(sizeof(Scheduler));
    s->queue_size = 0;
    s->queue = NULL;
    pthread_mutex_init(&s->mutex, NULL);
    pthread_cond_init(&s->cond, NULL);
    return s;
}

// Function to add a command to the scheduler's queue
void add_command(Scheduler* s, Command* cmd) {
    pthread_mutex_lock(&s->mutex);
    s->queue = (Command**)realloc(s->queue, sizeof(Command*) * (s->queue_size + 1));
    s->queue[s->queue_size] = cmd;
    s->queue_size++;
    pthread_cond_signal(&s->cond);
    pthread_mutex_unlock(&s->mutex);
}

// Function to execute a command
void* execute_command(void* arg) {
    Command* cmd = (Command*)arg;
    // Execute the command here, e.g., using fork() and exec()
    printf("Executing command %d: %s\n", cmd->id, cmd->name);
    return NULL;
}

// Function to start a new thread for each command in the scheduler's queue
void start_threads(Scheduler* s) {
    pthread_t* threads = (pthread_t*)malloc(sizeof(pthread_t) * s->queue_size);
    for(int i = 0; i < s->queue_size; i++) {
        Command* cmd = s->queue[i];
        pthread_create(&threads[i], NULL, execute_command, cmd);
    }
    for(int i = 0; i < s->queue_size; i++) {
        pthread_join(threads[i], NULL);
    }
    free(threads);
}

int main() {
    Scheduler* s = create_scheduler();

    // Add some commands to the scheduler's queue
    Command* cmd1 = (Command*)malloc(sizeof(Command));
    cmd1->id = 1;
    cmd1->name = "ls";
    cmd1->params = "-l";
    add_command(s, cmd1);

    Command* cmd2 = (Command*)malloc(sizeof(Command));
    cmd2->id = 2;
    cmd2->name = "grep";
    cmd2->params = "-i -e 'hello'";
    add_command(s, cmd2);

    // Start a new thread for each command in the scheduler's queue
    start_threads(s);

    return 0;
}
