using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

public sealed class DynamicAdaptiveValueGenerator
{
    private readonly object _configurationLock = new();
    private readonly Dictionary<string, (float min, float max)> _configurations = new();
    private int _currentConfigurationIndex;
    private readonly Timer _configurationTimer;

    public DynamicAdaptiveValueGenerator()
    {
        _configurationTimer = new Timer(ConfigurationUpdateCallback, null, TimeSpan.FromMilliseconds(100), TimeSpan.FromMilliseconds(500));
    }

    private void ConfigurationUpdateCallback(object state)
    {
        lock (_configurationLock)
        {
            if (TryGetNextConfiguration(out var nextConfig))
            {
                UpdateCurrentConfiguration(nextConfig);
            }
        }
    }

    public float GenerateRandomFloat(float min, float max) => _configurations[_currentConfigurationIndex].Item1 + new Random().NextDouble() * (_configurations[_currentConfigurationIndex].Item2 - _configurations[_currentConfigurationIndex].Item1);

    public int GenerateRandomInt(int min, int max) => _configurations[_currentConfigurationIndex].Item1 + new Random().Next(max - min + 1);

    private bool TryGetNextConfiguration(out (float min, float max) configuration)
    {
        // Implement retry mechanism with exponential backoff for transient failures
        // Handle rate limits imposed by the external API to ensure smooth operation under high demand

        return _configurations.TryGetValue("configuration_name", out configuration);
    }

    private void UpdateCurrentConfiguration((float min, float max) newConfig)
    {
        // Gradually apply updates to minimize disruption and monitor for stability post-update
        lock (_configurationLock)
        {
            _currentConfigurationIndex++;
            _configurations.Add("configuration_name", newConfig);
        }
    }

    public void Shutdown()
    {
        _configurationTimer.Change(Timeout.Infinite, Timeout.Infinite);
    }
}
