['Here is a sample C code block that implements a dynamic collection of records, each containing an integer key, a value, and a linked list of offset records:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the structure for a record
typedef struct {
    int key;
    void* value;
    struct OffsetRecord* offset_list;
} Record;

// Define the structure for an offset record
typedef struct {
    int timestamp;
    Record* record;
} OffsetRecord;

// Define the dynamic collection of records
typedef struct {
    Record** records;
    int size;
    int capacity;
} DynamicCollection;

// Function to create a new dynamic collection
DynamicCollection* create_dynamic_collection(int initial_capacity) {
    DynamicCollection* dc = (DynamicCollection*)malloc(sizeof(DynamicCollection));
    dc->records = (Record**)malloc(initial_capacity * sizeof(Record*));
    dc->size = 0;
    dc->capacity = initial_capacity;
    return dc;
}

// Function to add a new record to the dynamic collection
void add_record(DynamicCollection* dc, Record* record) {
    if (dc->size == dc->capacity) {
        // Reallocate memory for the records array
        dc->records = (Record**)realloc(dc->records, (dc->capacity * 2 + 1) * sizeof(Record*));
        dc->capacity *= 2;
    }
    dc->records[dc->size] = record;
    dc->size++;
}

// Function to remove a record from the dynamic collection
void remove_record(DynamicCollection* dc, int key) {
    for (int i = 0; i < dc->size; i++) {
        if (dc->records[i]->key == key) {
            // Shift all records down after the removed record
            memmove(&dc->records[i], &dc->records[i + 1], (dc->size - i - 1) * sizeof(Record*));
            dc->size--;
            break;
        }
    }
}

// Function to serialize a dynamic collection
void serialize_dynamic_collection(DynamicCollection* dc, FILE* file) {
    // Serialize the size and capacity of the dynamic collection
    fwrite(&dc->size, sizeof(int), 1, file);
    fwrite(&dc->capacity, sizeof(int), 1, file);

    // Serialize each record in the dynamic collection
    for (int i = 0; i < dc->size; i++) {
        Record* record = dc->records[i];
        // Serialize the key and value of the record
        fwrite(&record->key, sizeof(int), 1, file);
        fwrite(&record->value, sizeof(void*), 1, file);

        // Serialize the offset list for the record
        OffsetRecord* offset_list = record->offset_list;
        int offset_list_size = 0;
        while (offset_list) {
            offset_list_size++;
            offset_list = offset_list->next;
        }
        fwrite(&offset_list_size, sizeof(int), 1, file);
        for (int j = 0; j < offset_list_size; j++) {
            OffsetRecord* current_offset_record = record->offset_list;
            for (int k = 0; k <= j; k++) {
                current_offset_record = current_offset_record->next;
            }
            fwrite(&current_offset_record->timestamp, sizeof(int), 1, file);
            fwrite(&current_offset_record->record, sizeof(void*), 1, file);
        }
    }
}

// Function to deserialize a dynamic collection
DynamicCollection* deserialize_dynamic_collection(FILE* file) {
    DynamicCollection* dc = (DynamicCollection*)malloc(sizeof(DynamicCollection));
    fread(&dc->size, sizeof(int), 1, file);
    fread(&dc->capacity, sizeof(int), 1, file);

    dc->records = (Record**)malloc(dc->size * sizeof(Record*));

    for (int i = 0; i < dc->size; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        fread(&record->key, sizeof(int), 1, file);
        fread(&record->value, sizeof(void*), 1, file);

        // Deserialize the offset list for the record
        int offset_list_size;
        fread(&offset_list_size, sizeof(int), 1, file);
        OffsetRecord* offset_list = (OffsetRecord*)malloc(sizeof(OffsetRecord));
        for (int j = 0; j < offset_list_size; j++) {
            OffsetRecord* current_offset_record = offset_list;
            for (int k = 0; k <= j; k++) {
                fread(&current_offset_record->timestamp, sizeof(int), 1, file);
                fread(&current_offset_record->record, sizeof(void*), 1, file);
                if (k < j) {
                    current_offset_record->next = (OffsetRecord*)malloc(sizeof(OffsetRecord));
                    current_offset_record = current_offset_record->next;
                }
            }
        }
        record->offset_list = offset_list;
    }

    return dc;
}

// Function to prune the dynamic collection based on timestamps
void prune_dynamic_collection(DynamicCollection* dc, int timestamp_threshold) {
    for (int i = 0; i < dc->size; i++) {
        Record* record = dc->records[i];
        OffsetRecord* offset_list = record->offset_list;
        while (offset_list) {
            if (offset_list->timestamp <= timestamp_threshold) {
                // Remove the offset record
                offset_list = offset_list->next;
                free(offset_list);
                break;
            }
            offset_list = offset_list->next;
        }
    }
}

int main() {
    DynamicCollection* dc = create_dynamic_collection(10);

    // Add some records to the dynamic collection
    Record* record1 = (Record*)malloc(sizeof(Record));
    record1->key = 1;
    record1->value = (void*)malloc(sizeof(int) * 2);
    ((int*)record1->value)[0] = 10; ((int*)record1->value)[1] = 20;
    record1->offset_list = NULL;

    Record* record2 = (Record*)malloc(sizeof(Record));
    record2->key = 2;
    record2->value = (void*)malloc(sizeof(int) * 3);
    ((int*)record2->value)[0] = 30; ((int*)record2->value)[1] = 40; ((int*)record2->value)[2] = 50;
    record2->offset_list = NULL;

    Record* record3 = (Record*)malloc(sizeof(Record));
    record3->key = 3;
    record3->value = (void*)malloc(sizeof(int) * 4);
    ((int*)record3->value)[0] = 60; ((int*)record3->value)[1] = 70; ((int*)record3->value)[2] = 80; ((int*)record3->value)[3] = 90;
    record3->offset_list = NULL;

    add_record(dc, record1);
    add_record(dc, record2);
    add_record(dc, record3);

    // Serialize the dynamic collection
    FILE* file = fopen("dynamic_collection.bin", "wb");
    serialize_dynamic_collection(dc, file);
    fclose(file);

    return 0;
}
```

This code provides basic functionality for a modular C library that efficiently manages a dynamic collection of records. The `create_dynamic_collection` function creates a new dynamic collection with an initial capacity. The `add_record` function adds a new record to the dynamic collection, and the `remove_record` function removes a record from the dynamic collection.

The `serialize_dynamic_collection` function serializes a dynamic collection by writing its size, capacity, and each record in the collection, along with their keys, values, and offset lists. The `deserialize_dynamic_collection` function deserializes a dynamic collection by reading its size, capacity, and each record in the collection, along with their keys, values, and offset lists.

The `prune_dynamic_collection` function prunes the dynamic collection based on timestamps by removing any records or offset records that have a timestamp less than or equal to the provided threshold.']

