```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a struct to represent a record
typedef struct {
    int key;
    void* value;
    pthread_mutex_t lock;
} Record;

// Define a struct to represent an offset record
typedef struct {
    int offset;
    Record* parent;
} OffsetRecord;

// Define the dynamic collection of records
typedef struct {
    Record** records;
    int size;
    pthread_mutex_t lock;
} RecordCollection;

// Function to initialize a new record collection
RecordCollection* record_collection_init(int initial_size) {
    RecordCollection* rc = (RecordCollection*)malloc(sizeof(RecordCollection));
    rc->records = (Record**)calloc(initial_size, sizeof(Record*));
    rc->size = initial_size;
    pthread_mutex_init(&rc->lock, NULL);
    return rc;
}

// Function to add a new record to the collection
void record_collection_add(RecordCollection* rc, int key, void* value) {
    Record* new_record = (Record*)malloc(sizeof(Record));
    new_record->key = key;
    new_record->value = value;
    pthread_mutex_lock(&rc->lock);
    for (int i = 0; i < rc->size; i++) {
        if (!rc->records[i]) {
            rc->records[i] = new_record;
            break;
        }
    }
    pthread_mutex_unlock(&rc->lock);
}

// Function to deserialize a record collection from a buffer
RecordCollection* record_collection_deserialize(char* buffer) {
    RecordCollection* rc = (RecordCollection*)malloc(sizeof(RecordCollection));
    int size = *(int*)buffer;
    rc->records = (Record**)calloc(size, sizeof(Record*));
    rc->size = size;
    pthread_mutex_init(&rc->lock, NULL);
    for (int i = 0; i < size; i++) {
        Record* record = (Record*)malloc(sizeof(Record));
        memcpy(&record->key, buffer + sizeof(int) * (i + 1), sizeof(int));
        memcpy(&record->value, buffer + sizeof(int) * (size + 1), sizeof(void*));
        rc->records[i] = record;
    }
    return rc;
}

// Function to serialize a record collection to a buffer
void record_collection_serialize(RecordCollection* rc, char* buffer) {
    *(int*)buffer = rc->size;
    for (int i = 0; i < rc->size; i++) {
        memcpy(buffer + sizeof(int) * i, &rc->records[i]->key, sizeof(int));
        memcpy(buffer + sizeof(int) * (i + 1), &rc->records[i]->value, sizeof(void*));
    }
}

// Function to prune offset records based on timestamps
void record_collection_prune(RecordCollection* rc, int timestamp_threshold) {
    pthread_mutex_lock(&rc->lock);
    for (int i = 0; i < rc->size; i++) {
        if (rc->records[i]->value && *(int*)rc->records[i]->value < timestamp_threshold) {
            free(rc->records[i]->value);
            free(rc->records[i]);
        }
    }
    pthread_mutex_unlock(&rc->lock);
}
