import graphql.schema.DataFetchingEnvironment;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.client.RestTemplate;

import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

public class PokemonService implements GraphQLQueryResolver {

    private final PokemonRepository pokemonRepository;
    private final RestTemplate restTemplate;
    private final ObjectMapper objectMapper;

    public PokemonService(PokemonRepository pokemonRepository, RestTemplate restTemplate, ObjectMapper objectMapper) {
        this.pokemonRepository = pokemonRepository;
        this.restTemplate = restTemplate;
        this.objectMapper = objectMapper;
    }

    @GetMapping("/pokemon")
    public ResponseEntity<List<Pokemon>> getPokemons(@RequestParam("name") String name) {
        List<Pokemon> pokemons = pokemonRepository.findByName(name);
        return new ResponseEntity<>(pokemons, HttpStatus.OK);
    }

    @PostMapping("/pokemon")
    public ResponseEntity<Pokemon> createPokemon(@RequestBody Pokemon pokemon) {
        Pokemon createdPokemon = pokemonRepository.save(pokemon);
        return new ResponseEntity<>(createdPokemon, HttpStatus.CREATED);
    }
}
