        retries++;
    }

    // If all retries fail, log a warning message and insert the element
    if (logging_service) {
        logging_service->log("Warning: Failed to log error after 3 attempts. Inserting element '" + element + "' anyway.");
    }
    list.insert_after(list.end(), element);
}
