// transaction-service.js
const express = require('express');
const app = express();
const uuid = require('uuid');
const redis = require('redis');
const messageQueue = require('message-queue')();
const externalPaymentGateway = require('payment-gateway-api');
const ledgerService = require('ledger-service-api');
const fraudDetection = require('fraud-detection-api');

app.use(express.json());

// Custom event-driven architecture
app.on('transaction:created', (tx) => {
  // Validate transaction
  validateTransaction(tx)
    .then((isValid) => {
      if (!isValid) {
        // Rejected by validation, log and reject
        console.error(`Rejected transaction ${tx.id}`);
        tx.status = 'rejected';
      } else {
        // Process transaction
        processTransaction(tx);
      }
    })
    .catch((err) => {
      // Log error and reject
      console.error(`Error processing transaction ${tx.id}: ${err}`);
      tx.status = 'error';
    });
});

// Distributed caching strategy
app.use(redis.createClient({ host: 'redis-host', port: 6379 }));

// Message queuing for batch processing
messageQueue.connect('amqp://guest:guest@localhost');

// External payment gateway integration
externalPaymentGateway.configure({
  apiEndpoint: 'https://payment-gateway.com/api',
  apiToken: 'YOUR_API_TOKEN',
});

// Ledger service integration
ledgerService.configure({
  apiEndpoint: 'https://ledger-service.com/api',
  apiToken: 'YOUR_API_TOKEN',
});

// Fraud detection integration
fraudDetection.configure({
  apiEndpoint: 'https://fraud-detection.com/api',
  apiToken: 'YOUR_API_TOKEN',
});

// Custom retry logic and circuit breakers for transient failures
app.on('transaction:failed', (tx) => {
  // Retry transaction after 5 seconds
  setTimeout(() => {
    processTransaction(tx);
  }, 5000);

  // Circuit breaker pattern to prevent cascading failures
  if (tx.status === 'error') {
    console.error(`Circuit breaker triggered for transaction ${tx.id}`);
  }
});

// Comprehensive integration tests
describe('Transaction Service', () => {
  it('validates and processes transactions correctly', async () => {
    // Test happy path: create, validate, process, and verify transaction
    const tx = { id: uuid.v4(), amount: 100.00 };
    await app.post('/transactions', tx);
    expect(tx.status).toBe('success');
  });

  it('handles errors and rejection', async () => {
    // Test error path: create, validate, reject, and verify transaction
    const tx = { id: uuid.v4(), amount: -100.00 };
    await app.post('/transactions', tx);
    expect(tx.status).toBe('rejected');
  });

  it('retries failed transactions after a short delay', async () => {
    // Test retry logic for transient failures
    const tx = { id: uuid.v4(), amount: 50.00 };
    await app.post('/transactions', tx);
    expect(tx.status).toBe('error');
    setTimeout(() => {
      processTransaction(tx);
    }, 5000);
    expect(tx.status).toBe('success');
  });
});

// Return JSON response with status and error messages
app.use((req, res) => {
  const tx = req.body;
  if (tx && tx.status) {
    res.json({ status: tx.status });
  } else {
    res.status(400).json({ error: 'Invalid request' });
  }
});

// Scale linearly with increased transaction volume
app.get('/transactions', (req, res) => {
  const limit = req.query.limit || 10;
  // Fetch transactions from ledger service and return JSON response
  ledgerService.getTransactions(limit)
    .then((txs) => {
      res.json({ status: 'success', transactions: txs });
    })
    .catch((err) => {
      res.status(500).json({ error: err.message });
    });
});

// Support real-time analytics through flexible data pipeline
app.use('/analytics', (req, res) => {
  // Forward request to analytics service and return JSON response
  analyticsService.analyze(req.body)
    .then((result) => {
      res.json(result);
    })
    .catch((err) => {
      res.status(500).json({ error: err.message });
    });
});
```
This code provides a starting point for building the Node.js microservice, but it's just an example. You'll need to modify and extend it based on your specific requirements and constraints."]

