class TestRunner {
  constructor(label, tests) {
    this.label = label;
    this.tests = tests;
    this.context = {};
    this.logger = new Logger();
    this.mockBlueslip = new MockBlueslip();
    this.retryConfig = { attempts: 3, delay: 500 };
  }

  async run() {
    await this.initialize();

    for (const test of this.tests) {
      try {
        await this.runTest(test);
      } catch (error) {
        await this.handleFailure(error);
      }
    }

    await this.teardown();
  }

  async initialize() {
    // Initialize logging and monitoring services
    this.logger.init();
    // Initialize mockBlueslip library
    await this.mockBlueslip.init();
  }

  async runTest(test) {
    try {
      this.context.testLabel = test.label;
      this.logger.log({ level: 'info', message: `Starting test ${test.label}` });
      await test(this.context);
      this.logger.log({ level: 'info', message: `Finished test ${test.label}` });
    } catch (error) {
      throw error;
    }
  }

  async handleFailure(error) {
    // Log the failure with a detailed error report
    this.logger.log({ level: 'error', message: `Test ${this.context.testLabel} failed`, error });
    // Retry failed tests with a configurable retry mechanism and delay
    await this.retryFailedTests();
  }

  async teardown() {
    // Clean up resources and services initialized during testing
    this.logger.destroy();
    this.mockBlueslip.destroy();
  }

  async retryFailedTests() {
    for (let attempt = 0; attempt < this.retryConfig.attempts; attempt++) {
      try {
        await this.runTest(this.context);
        return;
      } catch (error) {
        if (attempt < this.retryConfig.attempts - 1) {
          await new Promise((resolve) => setTimeout(resolve, this.retryConfig.delay));
        } else {
          throw error;
        }
      }
    }
  }

  async getTestsForCommitMessage(commitMessage) {
    // Filter tests based on commit message
    return this.tests.filter((test) => test.label.includes(commitMessage));
  }

  async getTestsForBranch(branch) {
    // Filter tests based on branch name
    return this.tests.filter((test) => test.branch === branch);
  }
}

class Logger {
  constructor() {
    this.levels = ['debug', 'info', 'warn', 'error'];
  }

  init() {}

  log({ level, message, error }) {
    console.log(`${this.levels.indexOf(level)}: ${message}`);
    if (error) {
      console.error(error.stack);
    }
  }

  destroy() {}
}

class MockBlueslip {
  constructor() {}

  async init() {}

  async destroy() {}
}
