    FileUploader(const std::string& configPath) : config_(configPath), threadPool_(4), semaphore_(0) {}

    void uploadFile(const std::string& fileName, const std::string& fileContent) {
        auto promise = std::makePromise<std::future<void>>([this, fileName, fileContent](auto f) {
            try {
                uploadToCloudStorage(fileName, fileContent);
                f.set_value();
            } catch (const std::exception& e) {
                f.set_exception(std::current_exception());
            }
        });
        auto future = promise.get_future();

        {
            std::unique_lock<std::mutex> lock(mutex_);
            semaphore_.wait(lock);
            // Upload the file
            uploadFileAsync(fileName, fileContent);
            // Release the semaphore
            lock.unlock();
            semaphore_.notify_one();
        }

        // Wait for the asynchronous upload to complete
        future.get();
    }

