        File::create(output_file_path.as_path())?.write_all(ir_code.as_bytes())?;
        File::create(output_file_path.as_path())?.write_all(pem_content.as_bytes())?;

        Ok(format!("Generated secure LLVM IR code and PEM file successfully!"))
    }
}

// Implement OAuth client with token expiration handling
fn get_oauth_token() -> String {
    // Initialize OAuth client and service
    let mut client = ClientBuilder::new("https://api.oauth.service.com")?
        .unwrap();

    // Handle token expiration with automatic refresh
    loop {
        // Get access token for the user
        let token_response = client.get("/token")?;
        let token = token_response.json::<serde_json::Value>()?;

        // Check if the token has expired
        if token["expires_in"] < 60 {
            // Refresh the token
            let refresh_token_response = client.post("/refresh-token")?;
            let new_token = refresh_token_response.json::<serde_json::Value>()?;

            // Update the OAuth client with the new token
            client.update_token(new_token)?;
        } else {
            break;
        }
    }

    Ok(token)
}

