}

// Generate PEM file for private key and certificate
fn generate_pem_file(private_key: &str, certificate: &str) -> Result<String, String> {
    // Read private key and certificate from storage
    let private_key = PKCS8Reader::new(private_key)?;
    let certificate = PemReader::new(certificate)?;

    // Generate PEM file for the private key and certificate
    let pem_file = PrivateKeyPemFile::generate(private_key, certificate)?;
