from flask import Flask, request, jsonify
from flask_caching import Cache
from flask_sqlalchemy import SQLAlchemy
from flask_marshmallow import Marshmallow
from celery import Celery
from kafka import KafkaProducer
from sklearn.ensemble import RandomForestClassifier

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///' + os.path.join(os.getcwd(), 'transactions.db')
db = SQLAlchemy(app)
marshmallow = Marshmallow(app)

cache = Cache(app, config={'CACHE_TYPE': 'SimpleCache'})

celery = Celery('worker', broker='amqp://guest:guest@localhost')

kafka_producer = KafkaProducer(bootstrap_servers=['localhost:9092'])

fraud_detection_model = RandomForestClassifier(n_estimators=100)
fraud_detection_model.load('fraud_detection_model.pkl')

class Transaction(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    amount = db.Column(db.Float)
    timestamp = db.Column(db.DateTime, default=datetime.utcnow)
    device_fingerprint = db.Column(db.String)
    geolocation = db.Column(db.String)

class TransactionSchema(marshmallow.Schema):
    class Meta:
        fields = ('id', 'amount', 'timestamp')

@app.route('/transactions', methods=['POST'])
def create_transaction():
    transaction_data = request.get_json()
    if not transaction_data:
        return jsonify({'error': 'Invalid data'}), 400
    try:
        transaction = Transaction(amount=transaction_data['amount'], device_fingerprint=transaction_data['device_fingerprint'], geolocation=transaction_data['geolocation'])
        db.session.add(transaction)
        db.session.commit()
        return jsonify({'message': 'Transaction created successfully'}), 201
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/transactions', methods=['GET'])
def get_transactions():
    transactions = Transaction.query.all()
    schema = TransactionSchema(many=True)
    data = schema.dump(transactions)
    return jsonify(data.data)

@celery.task
def process_transaction(transaction_id):
    transaction = Transaction.query.get(transaction_id)
    if not transaction:
        return 'Transaction not found'
    try:
        # Evaluate fraud detection model and score the transaction
        fraud_score = fraud_detection_model.predict([transaction.geolocation, transaction.device_fingerprint])[0]
        if fraud_score > 0.5:
            # Reject the transaction due to high fraud score
            return 'Transaction rejected due to high fraud score'
        else:
            # Allow the transaction
            return 'Transaction allowed'
    except Exception as e:
        return str(e)

@app.route('/transactions/<int:transaction_id>', methods=['GET'])
def get_transaction(transaction_id):
    try:
        transaction = Transaction.query.get(transaction_id)
        if not transaction:
            return jsonify({'error': 'Transaction not found'}), 404
        schema = TransactionSchema()
        data = schema.dump(transaction)
        return jsonify(data.data)
    except Exception as e:
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)

# Configure Kafka producer to send transactions for fraud detection
