// Service configuration
const config = {
  db: {
    host: 'localhost',
    port: 5432,
    database: 'reduction_service',
    user: 'root',
    password: 'password'
  },
  messageBroker: {
    host: 'localhost',
    port: 5672,
    exchange: 'reduction_tasks',
    queue: 'reduction_results'
  }
};

// Import required libraries
const { Client } = require('pg');
const amqp = require('amqplib');
const WebSocket = require('ws');

// Initialize the database client and message broker connection
const dbClient = new Client({
  host: config.db.host,
  port: config.db.port,
  database: config.db.database,
  user: config.db.user,
  password: config.db.password
});

const messageBrokerConnection = amqp.connect(`amqp://${config.messageBroker.host}:${config.messageBroker.port}`);

// Define the reduction service
class ReductionService {
  constructor() {
    this.tasksQueue = [];
    this.resultsQueue = [];
    this.websocketServer = new WebSocket.Server({ port: 8080 });
  }

  async processTasks() {
    try {
      while (true) {
        const task = await messageBrokerConnection.consume({ noAck: true, queue: config.messageBroker.queue});
        if (!task) break;
        this.tasksQueue.push(task);
      }
    } catch (error) {
      // Handle error and reconnect to the message broker
      console.error('Error processing tasks:', error);
      setTimeout(() => {
        processTasks();
      }, 1000);
    }
  }

  async reduce(data) {
    try {
      const result = await dbClient.query(`SELECT SUM(${data.column}) FROM ${data.table}`);
      return result.rows[0][0];
    } catch (error) {
      // Handle error and retry the operation
      console.error('Error reducing data:', error);
      setTimeout(() => {
        reduce(data);
      }, 1000);
    }
  }

  async handleTask(task) {
    try {
      const taskData = JSON.parse(task.body);
      const result = await this.reduce(taskData);
      this.resultsQueue.push({ id: task.id, result });
    } catch (error) {
      // Handle error and notify the message broker of the failure
      console.error('Error handling task:', error);
      messageBrokerConnection.nack(task);
    }
  }

  async handleWebSocketMessage(message) {
    try {
      const result = this.resultsQueue.shift();
      if (!result) return;
      message.send(`Result for task ${result.id}: ${result.result}`);
    } catch (error) {
      // Handle error and notify the client of the failure
      console.error('Error sending WebSocket message:', error);
      message.send(`Error: ${error.message}`);
    }
  }

