                // Store compressed data in buffer
                *buffer = malloc(compressed_len + 32); // Add space for SHA-256 hash
                memcpy(*buffer, compressed, compressed_len);
            } else {
                err = -6; // Error: Compression failed
            }
            deflateEnd(&z_stream);

