namespace crypto {
class EncryptionModule {
public:
    EncryptionModule() = default;

    std::string encrypt(const std::string& plaintext, const std::string& password) {
        // Derive AES key and authentication tag using PBKDF2 with SHA-256
        auto derivedKey = deriveKey(password);
        auto authTag = deriveAuthTag(derivedKey);

        // Create a new GCM context
        AES_GCM_CTX ctx;
        AES_GCM_init(&ctx, derivedKey.data(), derivedKey.size());

        // Encrypt the plaintext using AES-GCM
        std::string ciphertext = encryptAESGCM(plaintext, &ctx);

        return ciphertext;
    }

    std::string decrypt(const std::string& ciphertext, const std::string& password) {
        // Derive AES key and authentication tag using PBKDF2 with SHA-256
        auto derivedKey = deriveKey(password);
        auto authTag = deriveAuthTag(derivedKey);

        // Create a new GCM context
        AES_GCM_CTX ctx;
        AES_GCM_init(&ctx, derivedKey.data(), derivedKey.size());

        // Decrypt the ciphertext using AES-GCM
        std::string plaintext = decryptAESGCM(ciphertext, &ctx);

        return plaintext;
    }

private:
    // Derive a 32-byte AES key from a given password using PBKDF2 with SHA-256
    std::vector<uint8_t> deriveKey(const std::string& password) {
        // Initialize PBKDF2 context
        PBKDF2_CTX ctx;
        PBKDF2_init(&ctx, SHA256_CTX(), password.data(), password.size());

        // Derive the AES key
        uint32_t iterations = 100000;
        std::vector<uint8_t> derivedKey(32);
        for (int i = 0; i < iterations; i++) {
            PBKDF2_update(&ctx, &password[0], password.size(), &derivedKey[0], derivedKey.size());
        }

        return derivedKey;
    }

    // Derive a 12-byte authentication tag from the AES key
    std::vector<uint8_t> deriveAuthTag(const std::vector<uint8_t>& aesKey) {
        // Initialize SHA-256 context
        SHA256_CTX ctx;
        SHA256_init(&ctx);

        // Derive the authentication tag
        uint32_t iterations = 10000;
        std::vector<uint8_t> authTag(12);
        for (int i = 0; i < iterations; i++) {
            SHA256_update(&ctx, aesKey.data(), aesKey.size());
            SHA256_final(&ctx, &authTag[0]);
        }

        return authTag;
    }

    // Encrypt the plaintext using AES-GCM
    std::string encryptAESGCM(const std::string& plaintext, AES_GCM_CTX* ctx) {
        // Create a new GCM context
        uint8_t iv[AES_BLOCK_SIZE];
        for (int i = 0; i < AES_BLOCK_SIZE; i++) {
            iv[i] = (uint8_t)rand();
        }
        AES_GCM_setIV(ctx, iv);

        // Encrypt the plaintext
        std::string ciphertext;
        auto encrypted = AES_GCM_encrypt(plaintext.data(), plaintext.size(), ctx);
        ciphertext.resize(encrypted.size());
        memcpy(&ciphertext[0], encrypted.data(), encrypted.size());

        return ciphertext;
    }

    // Decrypt the ciphertext using AES-GCM
    std::string decryptAESGCM(const std::string& ciphertext, AES_GCM_CTX* ctx) {
        // Decrypt the ciphertext
        std::string plaintext;
        auto decrypted = AES_GCM_decrypt(ciphertext.data(), ciphertext.size(), ctx);
        plaintext.resize(decrypted.size());
        memcpy(&plaintext[0], decrypted.data(), decrypted.size());

        return plaintext;
    }
};
} // namespace crypto

int main() {
    crypto::EncryptionModule module;

    std::string plaintext = "Hello, World!";
    std::string password = "my_secret_password";
    auto ciphertext = module.encrypt(plaintext, password);
    std::cout << "Ciphertext: " << ciphertext << std::endl;

    auto decrypted = module.decrypt(ciphertext, password);
    std::cout << "Decrypted: " << decrypted << std::endl;

    return 0;
}
```
