// Define the event log entry structure
typedef struct {
    time_t timestamp;
    char* message;
} NetworkEventLogEntry;

// Create a new event log entry
NetworkEventLogEntry* create_event_log_entry(const char* message) {
    NetworkEventLogEntry* entry = (NetworkEventLogEntry*)malloc(sizeof(NetworkEventLogEntry));
    if (!entry) return NULL;

    entry->timestamp = time(NULL);
    entry->message = strdup(message);
    if (!entry->message) {
        free(entry);
        return NULL;
    }

    return entry;
}

// Add an event log entry to the list
void add_event_log_entry(NetworkEventLogEntry** entries, int* size, NetworkEventLogEntry* new_entry) {
    *size = (*size + 1) * 2; // Double the size of the array when adding a new element
    *entries = (NetworkEventLogEntry*)realloc(*entries, sizeof(NetworkEventLogEntry*) * (*size));

    if (!*entries || !new_entry) return;

    memcpy(&((*entries)[*size - 1]), &new_entry, sizeof(NetworkEventLogEntry));
}

// Print all event log entries
void print_event_log_entries(NetworkEventLogEntry** entries, int size) {
    for (int i = 0; i < size; i++) {
        printf("Timestamp: %ld, Message: %s\n", (*entries)[i]->timestamp, (*entries)[i]->message);
    }
}

// Free allocated memory
void free_event_log_entries(NetworkEventLogEntry** entries, int size) {
    for (int i = 0; i < size; i++) {
        free((*entries)[i]->message);
        free((*entries)[i]);
    }

    free(*entries);
}
