import java.util.concurrent.*;
import java.util.*;

public class DistributedCache {
    private static final int DEFAULT_MAX_CAPACITY = 1000000;
    private static final int DEFAULT_CONCURRENCY_LEVEL = 10;

    private Map<String, CacheItem> cacheMap;
    private ConcurrentHashMap<String, CacheItem> concurrentCacheMap;
    private ExecutorService executorService;
    private Lock lock;
    private Condition condition;

    public DistributedCache(int maxCapacity) {
        this.cacheMap = new HashMap<>();
        this.concurrentCacheMap = new ConcurrentHashMap<>();
        this.executorService = Executors.newFixedThreadPool(DEFAULT_CONCURRENCY_LEVEL);
        this.lock = new ReentrantLock();
        this.condition = lock.newCondition();

        setMaxCapacity(maxCapacity);
    }

    public void put(String key, Object value) {
        CacheItem item = new CacheItem(value);
        cacheMap.put(key, item);
        concurrentCacheMap.putIfAbsent(key, item);
    }

    public Object get(String key) {
        return concurrentCacheMap.getOrDefault(key, null);
    }

    public void invalidate(String key) {
        cacheMap.remove(key);
        concurrentCacheMap.remove(key);
    }

    private class CacheItem {
        private final Object value;
        private volatile long version;

        public CacheItem(Object value) {
            this.value = value;
            this.version = System.currentTimeMillis();
        }
    }
}

public class EventDrivenCacheInvalidator {
    private DistributedCache cache;
    private MessageBroker messageBroker;

    public EventDrivenCacheInvalidator(DistributedCache cache, MessageBroker messageBroker) {
        this.cache = cache;
        this.messageBroker = messageBroker;

        messageBroker.subscribe("cache_invalidated", this::handleInvalidation);
    }

    private void handleInvalidation(String key) {
        cache.invalidate(key);
    }
}

