// Create a dynamic list to store network event log entries
List* createNetworkEventLogList() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    return list;
}

// Add a new network event log entry to the dynamic list
void addNetworkEventLogEntryToList(NetworkEventLogEntry* entry, List* list) {
    if (!list || !entry) return;

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) return;
    newNode->data = entry;
    newNode->next = NULL;

    if (list->head == NULL) {
        list->head = newNode;
        list->tail = newNode;
    } else {
        list->tail->next = newNode;
        list->tail = newNode;
    }
    list->size++;
}

// Remove a network event log entry from the dynamic list
void removeNetworkEventLogEntryFromList(NetworkEventLogEntry* entry, List* list) {
    if (!list || !entry) return;

    Node* current = list->head;
    Node* previous = NULL;

    while (current != NULL && current->data != entry) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) return; // Entry not found in the list

    if (previous == NULL) { // Entry is at the head of the list
        list->head = current->next;
    } else { // Entry is somewhere in the middle or end of the list
        previous->next = current->next;
    }

    if (current == list->tail) {
        list->tail = previous;
    }

    free(current);
    list->size--;
}

