fn decrypt(encrypted_data: &str) -> String {
    let key = SecretKey::new(b"my_secret_key");
    let cipher = symmetric::Aes128Ctr::new(&key);
    let decrypted_data = cipher.decrypt(encrypted_data.as_bytes());
    String::from_utf8(decrypted_data).unwrap()
}

