    public async Task UpdateRangeAsync(double? minValue, double? maxValue)
    {
        await _semaphore.WaitAsync();
        try
        {
            if (_minValue.HasValue && _maxValue.HasValue)
            {
                // Update range and notify all waiting tasks
                _minValue = minValue;
                _maxValue = maxValue;
                NotifyTasks();
            }
            else
            {
                _logger.LogError("Invalid range values");
            }
        }
        catch (Exception ex)
        {
            _logger.LogError(ex, "Error updating range");
        }
        finally
        {
            _semaphore.Release();
        }
    }

