    if (!uuid) return NULL;

    // Set the prefix
    strncpy(uuid->prefix, prefix, 64);
    uuid->prefix[63] = '\0'; // Null-terminate the string

    // Set the timestamp
    uuid->timestamp = timestamp;

    // Set the content hash
