        router.post("/token").handler(oAuth2TokenManagerVerticle::handleCreateToken);
        router.put("/token/:tokenId").handler(oAuth2TokenManagerVerticle::handleUpdateToken);

        router.delete("/token/:tokenId").handler(oAuth2TokenManagerVerticle::handleDeleteToken);

        vertx.createHttpServer().requestHandler(router::accept).listen(8080, "localhost");

        System.out.println("OAuth 2.0 Token Manager service started on port 8080.");
    }

    // ...

    private void handleGetToken(HttpServerRequest request) {
        String tokenId = request.getParam("tokenId");
        if (tokenizer.get(tokenId) != null) {
            request.response().putHeader("Content-Type", "application/json").end(Json.encodePrettily(new TokenResponse()));
        } else {
            request.response().setStatusCode(404).end();
        }
    }

    private void handleCreateToken(HttpServerRequest request) {
        // Validate JSON structure and missing/invalid field values
        String requestBody = request.getBodyAsJsonString();

        if (requestBody != null) {
            Gson gson = new Gson();
            TokenRequest tokenRequest = gson.fromJson(requestBody, TokenRequest.class);
            String tokenId = createToken(tokenRequest);
            request.response().putHeader("Location", "/token/" + tokenId).setStatusCode(201).end();
        } else {
            request.response().setStatusCode(400).end();
        }
    }

    private void handleUpdateToken(HttpServerRequest request) {
        // Validate JSON structure and missing/invalid field values
        String requestBody = request.getBodyAsJsonString();

        if (requestBody != null) {
            Gson gson = new Gson();
            TokenRequest tokenRequest = gson.fromJson(requestBody, TokenRequest.class);
            String tokenId = request.getParam("tokenId");
            if (tokenizer.update(tokenId, tokenRequest)) {
                request.response().putHeader("Content-Type", "application/json").end(Json.encodePrettily(new TokenResponse()));
            } else {
                request.response().setStatusCode(404).end();
            }
        } else {
            request.response().setStatusCode(400).end();
        }
    }

    private void handleDeleteToken(HttpServerRequest request) {
        String tokenId = request.getParam("tokenId");
        if (tokenizer.remove(tokenId)) {
            request.response().putHeader("Content-Type", "application/json").end(Json.encodePrettily(new TokenResponse()));
        } else {
            request.response().setStatusCode(404).end();
        }
    }

    private class TokenRequest {
        // Your custom token request fields here
    }

    private class TokenResponse {
        // Your custom token response fields here
    }
}
