    ci->settings[ci->size].id = id;
    ci->settings[ci->size].key = (char*)malloc(strlen(key) + 1);
    strcpy(ci->settings[ci->size].key, key);
    ci->settings[ci->size].value = (char*)malloc(strlen(value) + 1);
    strcpy(ci->settings[ci->size].value, value);
    ci->size++;
