typedef struct {
    int rlc_pdu_id;
    char *data;
    size_t data_len;
} RLC_PDU;

// Function prototypes
RLC_PDU* create_rlc_pdu(int id, const char* data, size_t len);
void delete_rlc_pdu(RLC_PDU* p);
int add_rlc_pdu_to_collection(RLC_PDU** collection, int* size, RLC_PDU* new_pdu);
int remove_rlc_pdu_from_collection(RLC_PDU** collection, int* size, int pdu_id);

// Collection structure to manage a list of RLC PDUs
typedef struct {
    RLC_PDU** elements;
    int size;
} RLC_PDU_COLLECTION;

// Initialize the RLC PDU collection
RLC_PDU_COLLECTION* init_rlc_pdu_collection(int initial_size) {
    RLC_PDU_COLLECTION* collection = (RLC_PDU_COLLECTION*)malloc(sizeof(RLC_PDU_COLLECTION));
    collection->size = initial_size;
    collection->elements = (RLC_PDU**)calloc(initial_size, sizeof(RLC_PDU*));
    return collection;
}

// Add a new RLC PDU to the collection
int add_rlc_pdu_to_collection(RLC_PDU** collection, int* size, RLC_PDU* new_pdu) {
    if (*size <= 0) {
        *size = 1;
        *collection = (RLC_PDU**)realloc(*collection, sizeof(RLC_PDU*) * (*size));
    }

    for (int i = 0; i < *size; i++) {
        if ((*collection)[i] == NULL) {
            (*collection)[i] = new_pdu;
            return 1;
        }
    }

    // Collection is full, resize and add the new PDU
    int new_size = *size * 2;
    *collection = (RLC_PDU**)realloc(*collection, sizeof(RLC_PDU*) * new_size);
    (*collection)[*size - 1] = new_pdu;
    *size = new_size;

    return 0;
}

// Remove an RLC PDU from the collection
int remove_rlc_pdu_from_collection(RLC_PDU** collection, int* size, int pdu_id) {
    for (int i = 0; i < *size; i++) {
        if ((*collection)[i]->rlc_pdu_id == pdu_id) {
            // Mark the PDU as removed
            (*collection)[i] = NULL;

            // If the removed PDU was at the end, reduce size and reallocate memory
            for (int j = i; j < *size - 1; j++) {
                (*collection)[j] = (*collection)[j + 1];
            }
            (*size)--;
            return 1;
        }
    }

    return 0;
}

// Create a new RLC PDU
RLC_PDU* create_rlc_pdu(int id, const char* data, size_t len) {
    RLC_PDU* p = (RLC_PDU*)malloc(sizeof(RLC_PDU));
    p->rlc_pdu_id = id;
    p->data = (char*)malloc(len * sizeof(char));
    strcpy(p->data, data);
    p->data_len = len;

    return p;
}

// Delete an RLC PDU
void delete_rlc_pdu(RLC_PDU* p) {
    if (p != NULL) {
        free(p->data);
        free(p);
    }
}
