```cpp
#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <unordered_map>

// Define a struct to represent a log entry
struct LogEntry {
    int timestamp;
    std::string eventType;
    int uid;
    std::map<std::string, std::string> metadata;
};

class LogManager {
public:
    // Initialize the logger with a maximum queue size and buffer size
    LogManager(size_t maxQueueSize = 1000, size_t bufferSize = 1024) : 
        maxQueueSize_(maxQueueSize), bufferSize_(bufferSize), 
        logQueue_(), eventLock_(), isStopped_(false) {}

    // Start the logger thread
    void start() {
        std::thread(&LogManager::loggerThread, this).detach();
    }

    // Stop the logger thread
    void stop() {
        isStopped_ = true;
    }

    // Log an entry asynchronously
    void log(const LogEntry& entry) {
        eventLock_.lock();
        logQueue_.push(entry);
        if (logQueue_.size() >= maxQueueSize_) {
            std::cout << "Log queue full, discarding oldest entries.\n";
            while (!logQueue_.empty()) {
                logQueue_.pop();
            }
        }
        eventLock_.unlock();
    }

private:
    // Logger thread function
    void loggerThread() {
        size_t bufferIndex = 0;
        std::string buffer(bufferSize_);
        while (!isStopped_) {
            LogEntry entry;
            if (logQueue_.try_pop(entry)) {
                buffer[bufferIndex] = '\0';
                std::cout << "Logged: "
                    << "Timestamp: " << entry.timestamp 
                    << ", Event Type: " << entry.eventType
                    << ", UID: " << entry.uid 
                    << ", Metadata: " << entry.metadataToString()
                    << "\n";
                bufferIndex += entry.metadata.size() * 16;
            }
        }
    }

    // Convert metadata to a string for logging
    std::string LogEntry::metadataToString() const {
        std::string str;
        for (const auto& pair : metadata) {
            str.append(pair.first).append(": ").append(pair.second).append(", ");
        }
        return str;
    }

    size_t maxQueueSize_;
    size_t bufferSize_;
    std::queue<LogEntry> logQueue_;
    std::mutex eventLock_;
    std::condition_variable isStopped_;
};
