#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>

// Configuration settings structure
typedef struct {
    char *key;
    char *value;
} ConfigSetting;

// Configuration store structure
typedef struct {
    int fd; // File descriptor for external config store
    pthread_mutex_t lock; // Mutex for concurrent access
    int size; // Current number of settings in the store
    ConfigSetting **settings; // Array of settings
} ConfigStore;

// Create a new configuration store
ConfigStore *config_store_create(int fd) {
    ConfigStore *store = (ConfigStore *)malloc(sizeof(ConfigStore));
    store->fd = fd;
    pthread_mutex_init(&store->lock, NULL);
    store->size = 0;
    store->settings = NULL;
    return store;
}

// Add a new configuration setting to the store
int config_store_add(ConfigStore *store, char *key, char *value) {
    ConfigSetting *setting = (ConfigSetting *)malloc(sizeof(ConfigSetting));
    setting->key = key;
    setting->value = value;

    pthread_mutex_lock(&store->lock);
    store->settings = realloc(store->settings, (store->size + 1) * sizeof(ConfigSetting *));
    store->settings[store->size] = setting;
    store->size++;
    pthread_mutex_unlock(&store->lock);

    return 0;
}

// Update an existing configuration setting in the store
int config_store_update(ConfigStore *store, char *key, char *value) {
    for (int i = 0; i < store->size; i++) {
        if (!strcmp(store->settings[i]->key, key)) {
            free(store->settings[i]->value);
            store->settings[i]->value = value;
            return 0;
        }
    }

    return -1; // Setting not found
}

// Remove a configuration setting from the store
int config_store_remove(ConfigStore *store, char *key) {
    for (int i = 0; i < store->size; i++) {
        if (!strcmp(store->settings[i]->key, key)) {
            free(store->settings[i]);
            memmove(&store->settings[i], &store->settings[i + 1], (store->size - i - 1) * sizeof(ConfigSetting *));
            store->size--;
            return 0;
        }
    }

    return -1; // Setting not found
}

// Read configuration settings from the store
int config_store_read(ConfigStore *store, char **keys, char ***values, int *count) {
    *count = store->size;

    for (int i = 0; i < store->size; i++) {
        keys[i] = strdup(store->settings[i]->key);
        values[i] = &store->settings[i]->value;
    }

    return 0;
}

// Close the configuration store
void config_store_close(ConfigStore *store) {
    for (int i = 0; i < store->size; i++) {
        free(store->settings[i]->key);
        free(store->settings[i]->value);
    }
    free(store->settings);
    pthread_mutex_destroy(&store->lock);
    close(store->fd);
    free(store);
}

// Example usage
int main() {
    int fd = socket(AF_UNIX, SOCK_STREAM, 0); // Create a Unix domain socket

    ConfigStore *store = config_store_create(fd);

    char *key1 = "key1";
    char *value1 = "value1";

    char *key2 = "key2";
    char *value2 = "value2";

    config_store_add(store, key1, value1);
    config_store_update(store, key1, "new_value1");

    int count;
    char **keys;
    char ***values;

    config_store_read(store, &keys, &values, &count);

    for (int i = 0; i < count; i++) {
        printf("Key: %s, Value: %s\n", keys[i], *values[i]);
    }

    config_store_remove(store, key2);
    config_store_close(store);

    return 0;
}
```

This code provides the core functionality for a modular C library to dynamically manage configuration settings. It includes functions for creating and closing a configuration store, adding, updating, and removing settings, and reading settings from the store.']

