    ue_context_t* ctx = (ue_context_t*)malloc(sizeof(ue_context_t));
    ctx->ue_id = ue_id;
    strcpy(ctx->mac_address, mac_address);
    ctx->ip_config = *ip_config;
    ctx->active_services = strdup(active_services);
    return ctx;
}

// Function to destroy a UE context
void ue_destroy(ue_context_t* ctx) {
    free(ctx->active_services);
    free(ctx);
}

// Function to add a UE context to the list
void ue_add(ue_context_t** ue_list, int* size, ue_context_t* new_ue) {
    pthread_mutex_lock(&mutex);
    (*size)++;
    *ue_list = (ue_context_t**)realloc(*ue_list, sizeof(ue_context_t*) * (*size));
    (*ue_list)[(*size)-1] = new_ue;
    pthread_mutex_unlock(&mutex);
}

// Function to remove a UE context from the list
void ue_remove(ue_context_t** ue_list, int* size, int index) {
    pthread_mutex_lock(&mutex);
    if (index < *size) {
        for (int i = index; i < *size - 1; i++) {
            (*ue_list)[i] = (*ue_list)[i+1];
        }
        free((*ue_list)[*size-1]);
        (*size]--;
        *ue_list = (ue_context_t**)realloc(*ue_list, sizeof(ue_context_t*) * (*size));
    }
    pthread_mutex_unlock(&mutex);
}

// Function to periodically detect and remove expired contexts
void ue_purge(ue_context_t** ue_list, int* size) {
    for (int i = 0; i < *size; i++) {
        if (/* check expiration criteria */) {
            ue_remove(ue_list, size, i);
            i--;
