#include <iostream>
#include <string>
#include <openssl/md5.h>

std::string getMD5Hash(const std::string& input) {
    unsigned char* result = new unsigned char[MD5_DIGEST_LENGTH];
    MD5_CTX mdContext;
    MD5_Init(&mdContext);
    MD5_Update(&mdContext, input.c_str(), input.size());
    MD5_Final(result, &mdContext);

    std::string output;
    for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
        char temp[3];
        sprintf(temp, "%02x", result[i]);
        output += temp;
    }

    delete[] result;

    return output;
}

