namespace DynamicDataProcessor
{
    public class DynamicDataProcessor
    {
        private readonly ILogger _logger;
        private readonly Dictionary<string, IDataProcessor> _processors = new();
        private readonly IConcurrencyManager _concurrencyManager;
        private readonly IErrorHandlingStrategy _errorHandlingStrategy;
        private readonly IResourceManagementService _resourceManagementService;

        public DynamicDataProcessor(ILogger<DynamicDataProcessor> logger,
            IConcurrencyManager concurrencyManager,
            IErrorHandlingStrategy errorHandlingStrategy,
            IResourceManagementService resourceManagementService)
        {
            _logger = logger;
            _concurrencyManager = concurrencyManager;
            _errorHandlingStrategy = errorHandlingStrategy;
            _resourceManagementService = resourceManagementService;
        }

        public async Task ProcessData(string pipelineName, DataPacket dataPacket)
        {
            if (!_processors.TryGetValue(pipelineName, out IDataProcessor processor))
            {
                throw new ArgumentException("Invalid pipeline name", nameof(pipelineName));
            }

            await _concurrencyManager.ExecuteTaskWithLockAsync(() =>
            {
                try
                {
                    processor.ProcessData(dataPacket);
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error processing data");
                    _errorHandlingStrategy.HandleError(ex);
                }
            });

            _resourceManagementService.ReleaseResource();
        }

        public void AddProcessor(string pipelineName, IDataProcessor processor)
        {
            _processors.Add(pipelineName, processor);
        }

        public void RemoveProcessor(string pipelineName)
        {
            _processors.Remove(pipelineName);
        }
    }
}
