#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

// Structure to represent a record
typedef struct Record {
    int key;
    void* value;
    struct Record* next;
} Record;

// Structure to manage the dynamic collection of records
typedef struct RecordManager {
    Record* head;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    size_t size;
} RecordManager;

// Function to create a new record manager
RecordManager* record_manager_create() {
    RecordManager* rm = (RecordManager*)malloc(sizeof(RecordManager));
    rm->head = NULL;
    rm->size = 0;
    pthread_mutex_init(&rm->lock, NULL);
    pthread_cond_init(&rm->cond, NULL);
    return rm;
}

// Function to add a new record to the manager
void record_manager_add(RecordManager* rm, int key, void* value) {
    Record* record = (Record*)malloc(sizeof(Record));
    record->key = key;
    record->value = value;
    record->next = NULL;

    pthread_mutex_lock(&rm->lock);
    record->next = rm->head;
    rm->head = record;
    rm->size++;
    pthread_mutex_unlock(&rm->lock);

    // Notify waiting threads that a new record has been added
    pthread_cond_signal(&rm->cond);
}

// Function to remove the head record from the manager
void record_manager_remove_head(RecordManager* rm) {
    if (rm->head == NULL) return;

    Record* temp = rm->head;
    rm->head = rm->head->next;
    free(temp);

    pthread_mutex_lock(&rm->lock);
    rm->size--;
    pthread_mutex_unlock(&rm->lock);
}

// Function to get the size of the record manager
size_t record_manager_get_size(RecordManager* rm) {
    return rm->size;
}
