// Define the structure to hold configuration settings
typedef struct {
    char* key;
    char* value;
} config_setting_t;

// Define the library's internal data structure
typedef struct {
    int size;
    config_setting_t** settings;
} config_data_t;

// Initialize the library
config_data_t* config_init() {
    config_data_t* config = (config_data_t*)malloc(sizeof(config_data_t));
    config->size = 0;
    config->settings = NULL;
    return config;
}

// Add a configuration setting to the library
void config_add(config_data_t* config, char* key, char* value) {
    // Allocate memory for new setting
    config_setting_t* setting = (config_setting_t*)malloc(sizeof(config_setting_t));
    setting->key = strdup(key);
    setting->value = strdup(value);

    // Reallocate memory for settings array if necessary
    int new_size = config->size + 1;
    config_setting_t** new_settings = (config_setting_t**)realloc(config->settings, sizeof(config_setting_t*) * new_size);
    for (int i = config->size; i < new_size - 1; i++) {
        new_settings[i] = config->settings[i];
    }
    new_settings[new_size - 1] = setting;
    free(config->settings);
    config->settings = new_settings;
    config->size = new_size;
}

// Remove a configuration setting from the library
void config_remove(config_data_t* config, char* key) {
    // Find the index of the setting to remove
    int i;
    for (i = 0; i < config->size; i++) {
        if (strcmp(config->settings[i]->key, key) == 0) {
            break;
        }
    }

    // If found, reallocate memory for settings array and update size
    if (i < config->size - 1) {
        int new_size = config->size - 1;
        config_setting_t** new_settings = (config_setting_t**)realloc(config->settings, sizeof(config_setting_t*) * new_size);
        for (int j = i; j < new_size; j++) {
            new_settings[j] = config->settings[j + 1];
        }
        free(config->settings);
        config->settings = new_settings;
        config->size = new_size;
    }

    // Free the removed setting
    if (i >= 0) {
        free(config->settings[i]->key);
        free(config->settings[i]->value);
        free(config->settings[i]);
    }
}

