import os
import hashlib
from typing import Dict, Any

class FileIntegrityVerifier:
    def __init__(self):
        self.hash_algorithms = {'md5': hashlib.md5(), 'sha256': hashlib.sha256()}

    def verify_file_integrity(self, file_path: str, hash_algorithm: str) -> Dict[str, Any]:
        try:
            with open(file_path, 'rb') as file:
                file_hash = self.hash_algorithms[hash_algorithm].hexdigest()
                return {'file_name': os.path.basename(file_path), 
                        'hash_value': file_hash, 
                        'status': 'OK'}
        except FileNotFoundError:
            return {'error_message': f"File '{file_path}' not found."}
        except PermissionError:
            return {'error_message': f"Permission denied to access file '{file_path}'."}
        except Exception as e:
            return {'error_message': str(e)}

    def hash_file(self, file_path: str, hash_algorithm: str) -> Dict[str, Any]:
        try:
            with open(file_path, 'rb') as file:
                self.hash_algorithms[hash_algorithm].update(file.read())
                return {'file_name': os.path.basename(file_path), 
                        'hash_value': self.hash_algorithms[hash_algorithm].hexdigest()}
        except FileNotFoundError:
            return {'error_message': f"File '{file_path}' not found."}
        except PermissionError:
            return {'error_message': f"Permission denied to access file '{file_path}'."}
        except Exception as e:
            return {'error_message': str(e)}

    def get_file_size(self, file_path: str) -> int:
        try:
            return os.path.getsize(file_path)
        except FileNotFoundError:
            return 0
        except PermissionError:
            return 0

class FileIntegrityVerifierService:
    def __init__(self):
        self.verifier = FileIntegrityVerifier()

    def verify_file_integrity(self, file_path: str, hash_algorithm: str) -> Dict[str, Any]:
        return self.verifier.verify_file_integrity(file_path, hash_algorithm)

    def hash_file(self, file_path: str, hash_algorithm: str) -> Dict[str, Any]:
        return self.verifier.hash_file(file_path, hash_algorithm)

    def get_file_size(self, file_path: str) -> int:
        return self.verifier.get_file_size(file_path)
