// Define a struct for record
typedef struct {
    int key;
    char *value;
    struct {
        int offset;
    } *offset_records;
} Record;

// Define a struct for linked list of offset records
typedef struct {
    Record *record;
    struct OffsetList *next;
} OffsetList;

// Function to add a new record to the collection
Record *add_record(Record **collection, int key, char *value) {
    // Create a new record
    Record *new_record = (Record *)malloc(sizeof(Record));
    new_record->key = key;
    new_record->value = value;

    // Add the new record to the collection
    if (*collection == NULL) {
        *collection = new_record;
    } else {
        Record *current = *collection;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_record;
    }

    return new_record;
}

// Function to add a new offset record
void add_offset_record(OffsetList **offset_list, int key, Record *record) {
    // Create a new offset record
    OffsetList *new_offset_record = (OffsetList *)malloc(sizeof(OffsetList));
    new_offset_record->record = record;

    // Add the new offset record to the linked list
    if (*offset_list == NULL) {
        *offset_list = new_offset_record;
    } else {
        OffsetList *current = *offset_list;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_offset_record;
    }
}

// Function to get the offset record for a given key
Record *get_offset_record(OffsetList *offset_list, int key) {
    // Traverse the linked list and find the record with matching key
    OffsetList *current = offset_list;
    while (current != NULL) {
        if (current->record->key == key) {
            return current->record;
        }
        current = current->next;
    }

    return NULL;
}

// Function to free the resources allocated for records and linked lists
void free_records_and_offset_lists(Record **collection, OffsetList **offset_list) {
    // Free each record in the collection
    Record *current_record = *collection;
    while (current_record != NULL) {
        Record *next_record = current_record->next;
        free(current_record);
        current_record = next_record;
    }

    // Free each offset record in the linked list
    OffsetList *current_offset_record = *offset_list;
    while (current_offset_record != NULL) {
        OffsetList *next_offset_record = current_offset_record->next;
        free(current_offset_record);
        current_offset_record = next_offset_record;
    }
}

// Function to hash a file using MD5 and SHA-256
void hash_file(char *file_path) {
    // Open the file for hashing
    FILE *file = fopen(file_path, "rb");
    if (file == NULL) {
        printf("Error opening file\n");
        return;
    }

    // Hash the file using MD5 and SHA-256 algorithms
    unsigned char md5_hash[16];
    unsigned char sha256_hash[32];
    MD5_CTX ctx_md5;
    SHA256_CTX ctx_sha256;
    MD5_Init(&ctx_md5);
    SHA256_Init(&ctx_sha256);

    // Read the file in chunks and hash each chunk
    while (1) {
        char buffer[1024];
        size_t bytes_read = fread(buffer, 1, sizeof(buffer), file);
        if (bytes_read == 0) break;
        MD5_Update(&ctx_md5, buffer, bytes_read);
        SHA256_Update(&ctx_sha256, buffer, bytes_read);

        // Check for errors
        if (ferror(file)) {
            printf("Error reading file\n");
            return;
        }
    }

    // Finish the hashing process and get the hashes
    MD5_Final(md5_hash, &ctx_md5);
    SHA256_Final(sha256_hash, &ctx_sha256);

    // Print or store the hashes as required
    printf("MD5 Hash: ");
    for (int i = 0; i < 16; i++) {
        printf("%02x", md5_hash[i]);
    }
    printf("\n");
    printf("SHA-256 Hash: ");
    for (int i = 0; i < 32; i++) {
        printf("%02x", sha256_hash[i]);
    }
    printf("\n");

    // Close the file
    fclose(file);
}

int main() {
    Record *record1 = add_record(NULL, 1, "Record 1");
    Record *record2 = add_record(NULL, 2, "Record 2");
    OffsetList *offset_list = NULL;

    add_offset_record(&offset_list, 1, record1);
    add_offset_record(&offset_list, 2, record2);

    Record *found_record = get_offset_record(offset_list, 2);
    if (found_record != NULL) {
        printf("Found record: %d - %s\n", found_record->key, found_record->value);
    } else {
        printf("Record not found\n");
    }

    free_records_and_offset_lists(&record1, &offset_list);

    return 0;
}
