void handleOAuthIntegration(std::forward_list<std::string>& list, const std::string& jsonStr, const std::string& target, const std::string& element,
                               std::shared_ptr<ServiceInterface> loggingService, std::shared_ptr<ServiceInterface> authService, std::shared_ptr<ServiceInterface> dbService) {
