// Caching Strategy Interface
class CacheStrategy {
public:
    virtual string get(const string& key) = 0;
    virtual void put(const string& key, const string& value) = 0;
    virtual bool invalidate(const string& key) = 0;
};

// In-Memory Cache Implementation
class MemoryCache : public CacheStrategy {
private:
    unordered_map<string, string> cache;

public:
    string get(const string& key) override {
        return cache.count(key) ? cache.at(key) : "";
    }

    void put(const string& key, const string& value) override {
        cache[key] = value;
    }

    bool invalidate(const string& key) override {
        if (cache.erase(key) != 0) {
            return true;
        }
        return false;
    }
};

