    CacheManager(CacheStrategy* strategy) : cache(strategy) {}

    void setUserAccount(const string& accessToken, const string& accountId) {
        // Check cache first
        if (string cachedAccount = cache->get(accessToken + "_" + accountId); !cachedAccount.empty()) {
            // Return cached result
            return;
        }

        // Make API call and store in cache
        vector<string> accounts;
        RestClient* client = apiClients[accessToken];
        client->getUserAccounts(accessToken, accounts);
        cache->put(accessToken + "_" + accountId, string.join(accounts, ","));
    }

    void updateUserAccount(const string& accessToken, const string& accountId, const string& updates) {
        // Check if account exists in cache
        if (string cachedAccount = cache->get(accessToken + "_" + accountId); !cachedAccount.empty()) {
            // Invalidate cache entry
            cache->invalidate(accessToken + "_" + accountId);
        }

        // Make API call and update cache
        RestClient* client = apiClients[accessToken];
        client->updateUserAccount(accessToken, accountId, updates);
    }
};

