// Define structure for connection pool
typedef struct {
    int size;
    int available;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} ConnectionPool;

// Function to initialize connection pool
ConnectionPool* init_connection_pool(int size) {
    ConnectionPool* pool = (ConnectionPool*)malloc(sizeof(ConnectionPool));
    pool->size = size;
    pool->available = 0;
    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->cond, NULL);
    return pool;
}

// Function to create a new connection
int create_connection(ConnectionPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->available > 0) {
        int idx = rand() % pool->size;
        pool->available--;
        printf("Created new connection at index %d\n", idx);
        pthread_cond_signal(&pool->cond);
        pthread_mutex_unlock(&pool->lock);
        return idx;
    } else {
        pthread_mutex_unlock(&pool->lock);
        return -1; // No available connections
    }
}

// Function to destroy a connection
void destroy_connection(ConnectionPool* pool, int idx) {
    pthread_mutex_lock(&pool->lock);
    if (idx < 0 || idx >= pool->size) {
        pthread_mutex_unlock(&pool->lock);
        return;
    }
    pool->available++;
    printf("Destroyed connection at index %d\n", idx);
    pthread_mutex_unlock(&pool->lock);
}

// Function to get available connections
int get_available_connections(ConnectionPool* pool) {
    int count = 0;
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->size; i++) {
        if (pool->available > 0) {
            count++;
            pool->available--;
        }
    }
    pthread_mutex_unlock(&pool->lock);
    return count;
}

