use std::{thread, time};
use rand::Rng;
use rayon::prelude::*;

struct RandomNumberGenerator {
    rng: Rng,
    seed: u64,
}

impl RandomNumberGenerator {
    pub fn new(seed: Option<u64>) -> Self {
        let mut rng = Rng::new();
        if let Some(s) = seed {
            rng.srand(s);
        }
        Self { rng, seed }
    }

    pub fn generate(&mut self) -> u32 {
        self.rng.gen::<u32>()
    }

    pub fn reseed(&mut self, new_seed: u64) {
        self.seed = new_seed;
        self.rng.srand(new_seed);
    }
}

pub struct DistributedRandomNumberGenerator {
    nodes: Vec<RandomNumberGenerator>,
}

impl DistributedRandomNumberGenerator {
    pub fn new(nodes_count: usize) -> Self {
        let mut nodes = Vec::new();
        for _ in 0..nodes_count {
            nodes.push(RandomNumberGenerator::new(None));
        }
        Self { nodes }
    }

    pub fn generate(&mut self) -> u32 {
        self.nodes.iter().map(|node| node.generate()).sum()
    }

    pub fn reseed(&mut self, new_seed: u64) {
        for node in &mut self.nodes {
            node.reseed(new_seed);
        }
    }
}

pub struct AsyncRng {
    rng: Rng,
}

impl AsyncRng {
    pub async fn generate(&self) -> u32 {
        self.rng.gen::<u32>()
    }

    pub async fn reseed(&mut self, new_seed: u64) {
        self.rng.srand(new_seed);
    }
}
