using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;

namespace WeatherAlertSystem
{
    public class Startup
    {
        public void ConfigureServices(IServiceCollection services)
        {
            services.AddControllers();

            // Third-party REST APIs
            services.AddSingleton<WeatherApi>();
            services.AddSingleton<TrafficApi>();
            services.AddSingleton<EnvironmentalApi>();

            // Cache layer
            services.AddSingleton<MemoryCache>();

            // Fallback mechanism
            services.AddScoped<FallbackService>();

            // Advanced logging and monitoring
            services.AddLogging();
            services.AddSerilog();

            // Thread-safe operations and concurrent request handling
            services.AddSingleton<ThreadPoolManager>();
        }

        public void Configure(IApplicationBuilder app, IWebHostEnvironment env)
        {
            app.UseRouting();
            app.UseEndpoints(endpoints =>
            {
                endpoints.MapControllers();
            });
        }
    }
}

// Weather API client
public class WeatherApi : IWeatherApi
{
    private readonly HttpClient _httpClient;

    public WeatherApi(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<WeatherData> GetWeatherAsync(string location, string apiKey)
    {
        // Make HTTP request to weather API
        var response = await _httpClient.GetAsync($"weather/{location}?apiKey={apiKey}");
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsJsonAsync<WeatherData>();
    }
}

// Traffic API client
public class TrafficApi : ITrafficApi
{
    private readonly HttpClient _httpClient;

    public TrafficApi(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<TrafficData> GetTrafficAsync(string location, string apiKey)
    {
        // Make HTTP request to traffic API
        var response = await _httpClient.GetAsync($"traffic/{location}?apiKey={apiKey}");
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsJsonAsync<TrafficData>();
    }
}

// Environmental API client
public class EnvironmentalApi : IEnvironmentalApi
{
    private readonly HttpClient _httpClient;

    public EnvironmentalApi(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    public async Task<EnvironmentalData> GetEnvironmentalAsync(string location, string apiKey)
    {
        // Make HTTP request to environmental API
        var response = await _httpClient.GetAsync($"environmental/{location}?apiKey={apiKey}");
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsJsonAsync<EnvironmentalData>();
    }
}

// Fallback service
public class FallbackService : IFallbackService
{
    private readonly MemoryCache _cache;

    public FallbackService(MemoryCache cache)
    {
        _cache = cache;
    }

    public async Task<T> FallBackAsync<T>(string key, Func<Task<T>> callback)
    {
        // Check if data is cached
        var cachedData = _cache.Get(key);
        if (cachedData != null)
        {
            return (T)cachedData;
        }

        try
        {
            // Make API request and cache response
            var data = await callback();
            _cache.Set(key, data);
            return data;
        }
        catch (Exception ex)
        {
            // Handle fallback logic here
            throw;
        }
    }
}

// Advanced logging and monitoring
public class LoggingMiddleware
{
    private readonly RequestDelegate _next;

    public LoggingMiddleware(RequestDelegate next)
    {
        _next = next;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        // Log request details
        var logger = Log.Logger;
        await logger.Information("Request {HttpRequest.Method} {HttpRequest.Path}");

        try
        {
            // Call the next middleware in the pipeline
            await _next(context);
        }
        catch (Exception ex)
        {
            // Log exception details
            await logger.Error(ex, "Error handling request");
            throw;
        }
    }
}

// Thread-safe operations and concurrent request handling
public class ThreadPoolManager : IThreadPoolManager
{
    private readonly ConcurrentQueue<Task> _taskQueue;

    public ThreadPoolManager()
    {
        _taskQueue = new ConcurrentQueue<Task>();
    }

    public async Task ExecuteAsync(Func<Task> callback)
    {
        // Enqueue task
        _taskQueue.Enqueue(callback);

        // Start processing tasks concurrently
        await Task.Run(() =>
        {
            while (_taskQueue.TryDequeue(out var task))
            {
                try
                {
                    // Run task
                    await task();
                }
                catch (Exception ex)
                {
                    // Handle exception
                    throw;
                }
            }
        });
    }
}
```

