#include <iostream>
#include <string>
#include <memory>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <octree/octree.h>

std::unique_ptr<octree::Octree> octreeStorage;

void loadAndUpdatePageSection(int pageSectionId, int elementId, const std::string& htmlContent) {
    // Acquire the octree lock for concurrent access
    std::mutex octreeLock;
    std::unique_lock<std::mutex> ul(octreeLock);

    // Retrieve the relevant data from the octree storage system
    auto data = octreeStorage->get(pageSectionId, elementId);

    if (data) {
        // Update the page section with new HTML content
        data->setHtmlContent(htmlContent);
    } else {
        // Create a new node in the octree for the page section
        auto newNode = std::make_unique<octree::Node>(pageSectionId, elementId, htmlContent);
        octreeStorage->insert(newNode.get());
    }

    // Release the octree lock
    ul.unlock();
}

int main() {
    // Initialize the octree storage system with a feature size and number of leaf nodes
    octreeStorage = std::make_unique<octree::Octree>(100, 1024);

    // Load and update page sections concurrently using multiple threads
    std::vector<std::thread> threads;
    for (int i = 0; i < 10; i++) {
        threads.emplace_back([i]() {
            loadAndUpdatePageSection(i, i * 2, "Hello World!");
        });
    }

    // Wait for all threads to finish
    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
