import java.io.*;
import java.net.URI;
import java.util.*;
import java.sql.*;

public class MoSTStateUtil {
    private Map<String, MoSTState> cache = new HashMap<>();
    private Map<String, Function<URI, MoSTState>> providers = new HashMap<>();
    private Connection conn;

    public MoSTStateUtil(String dbUrl, String dbUser, String dbPass) throws SQLException {
        conn = DriverManager.getConnection(dbUrl, dbUser, dbPass);
    }

    public void addProvider(String providerId, Function<URI, MoSTState> provider) {
        providers.put(providerId, provider);
    }

    public MoSTState loadMoSTState(String stateId) throws IOException, SQLException {
        MoSTState state = cache.get(stateId);
        if (state != null) return state;

        for (Map.Entry<String, Function<URI, MoSTState>> entry : providers.entrySet()) {
            state = entry.getValue().apply(new URI("file://path/to/state"));
            if (state != null) break;
        }

        // validate state
        if (!validateState(state)) {
            rollbackState(state);
            return null;
        }

        // cache the state
        cache.put(stateId, state);

        return state;
    }

    private boolean validateState(MoSTState state) throws SQLException {
        try (PreparedStatement ps = conn.prepareStatement("SELECT * FROM employee WHERE supervisor_id = ?")) {
            ps.setInt(1, state.getSupervisorId());
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    // verify employee info
                    if (!rs.getString("name").equals(state.getName())) return false;
                    if (!rs.getString("city").equals(state.getCity())) return false;
                    if (!rs.getString("address").equals(state.getAddress())) return false;
                }
            }
        } catch (SQLException e) {
            // log error and fallback
            System.out.println("Error validating state: " + e.getMessage());
            return true; // allow fallback
        }

        return true;
    }

    private void rollbackState(MoSTState state) throws SQLException {
        try (PreparedStatement ps = conn.prepareStatement("UPDATE employee SET supervisor_id = ? WHERE id = ?")) {
            ps.setInt(1, 0);
            ps.setInt(2, state.getId());
            ps.executeUpdate();
        }
    }

    public static void main(String[] args) throws Exception {
        MoSTStateUtil util = new MoSTStateUtil("jdbc:mysql://localhost:3306/mydb", "user", "pass");
        util.addProvider("file", (uri) -> {
            // load state from file
        });
        util.addProvider("api", (uri) -> {
            // load state from API
        });

        MoSTState state = util.loadMoSTState("state1");

        if (state == null) {
            System.out.println("Failed to load state");
        } else {
            System.out.println("Loaded state: " + state.getName());
        }
    }
}
