const { promisify } = require('util');
const { createReadStream } = require('fs');
const { parse } = require('csv-parser');
const { parseXml } = require('xml2js');
const { load } = require('json5');
const redis = require('ioredis');
const { KafkaClient } = require('@kafkalib/client');
const { getRateLimit, setRateLimit } = require('ratelimit');

class FileProcessor {
  constructor({ cache, concurrencyControl, externalApis, logger }) {
    this.cache = cache;
    this.concurrencyControl = concurrencyControl;
    this.externalApis = externalApis;
    this.logger = logger;
  }

  async processFiles(dir) {
    const files = await fs.readdir(dir);
    for (const file of files) {
      if (!file.includes('.')) continue;
      const [name, ext] = file.split('.');
      switch (ext) {
        case 'json':
          await this.processJsonFile(`${dir}/${file}`);
          break;
        case 'csv':
          await this.processCsvFile(`${dir}/${file}`);
          break;
        case 'xml':
          await this.processXmlFile(`${dir}/${file}`);
          break;
        default:
          continue; // unsupported format
      }
    }
  }

  async processJsonFile(file) {
    const json = load(await fs.readFile(file, 'utf8'));
    await this.cache.set('json:' + file, json);
    await this.externalApis.forEach((api) => api.fetchMetadata(json));
  }

  async processCsvFile(file) {
    const csv = parse(await fs.readFile(file, 'utf8'));
    await this.cache.set('csv:' + file, csv);
    await this.externalApis.forEach((api) => api.fetchMetadata(csv));
  }

  async processXmlFile(file) {
    const xml = parseXml(await fs.readFile(file, 'utf8'));
    await this.cache.set('xml:' + file, xml);
    await this.externalApis.forEach((api) => api.fetchMetadata(xml));
  }

  async fetchMetadata(data) {
    for (const api of this.externalApis) {
      try {
        const metadata = await api.getMetadata(data);
        if (metadata) return metadata;
      } catch (err) {
        this.logger.error(`Error fetching metadata from ${api.name}:`, err);
      }
    }
  }

  async run() {
    this.concurrencyControl.start();
    while (true) {
      const file = await this.cache.get('file');
      if (!file) break;
      await this.processFile(file);
      await this.cache.set('file', null);
    }
    this.concurrencyControl.stop();
  }
}

