// Define a struct to represent a configuration setting
typedef struct {
    char* key;
    char* value;
} ConfigSetting;

// Define a struct to represent the main data structure for managing configuration settings
typedef struct {
    int size; // number of config settings
    ConfigSetting** settings; // array of config settings
} Config;

// Initialize the configuration structure
Config* init_config(int size) {
    Config* config = (Config*)malloc(sizeof(Config));
    config->size = size;
    config->settings = (ConfigSetting**)malloc(size * sizeof(ConfigSetting*));
    return config;
}

// Add a new config setting to the existing settings
void add_setting(Config* config, char* key, char* value) {
    ConfigSetting* setting = (ConfigSetting*)malloc(sizeof(ConfigSetting));
    setting->key = key;
    setting->value = value;
    config->settings[config->size] = setting;
    config->size++;
}

// Print the configuration settings
void print_config(Config* config) {
    for(int i = 0; i < config->size; i++) {
        printf("%s: %s\n", config->settings[i]->key, config->settings[i]->value);
    }
}

// Free the memory allocated for the configuration structure and its settings
void free_config(Config* config) {
    for(int i = 0; i < config->size; i++) {
        free(config->settings[i]);
    }
    free(config->settings);
    free(config);
}

int main() {
    Config* config = init_config(10);

    add_setting(config, "setting1", "value1");
    add_setting(config, "setting2", "value2");
    add_setting(config, "setting3", "value3");

    print_config(config);

    free_config(config);

    return 0;
}
