import java.util.HashMap;
import java.util.Map;

public class UnionFind {
    private Map<String, String> parent = new HashMap<>();
    private Map<String, Integer> rank = new HashMap<>();

    public void makeSet(String item) {
        parent.put(item, item);
    }

    public boolean find(String a, String b) {
        if (!parent.containsKey(a)) {
            return false;
        }
        if (!parent.containsKey(b)) {
            return false;
        }
        if (findHelper(a, b)) {
            union(a, b);
            return true;
        }
        return false;
    }

    private boolean findHelper(String a, String b) {
        if (a.equals(parent.get(a))) {
            return a.equals(parent.get(b));
        }
        parent.put(a, findHelper(parent.get(a), b));
        return parent.get(a).equals(parent.get(b));
    }

    public void union(String a, String b) {
        if (!find(a, b)) {
            return;
        }
        if (rank.containsKey(a) && rank.containsKey(b)) {
            if (rank.get(a) < rank.get(b)) {
                parent.put(a, b);
            } else if (rank.get(a) > rank.get(b)) {
                parent.put(b, a);
            } else {
                parent.put(a, b);
                rank.put(b, rank.get(b) + 1);
            }
        } else {
            if (!rank.containsKey(a)) {
                rank.put(a, 0);
            }
            if (!rank.containsKey(b)) {
                rank.put(b, 0);
            }
            unionHelper(a, b);
        }
    }

    private void unionHelper(String a, String b) {
        parent.put(b, a);
        rank.put(a, rank.getOrDefault(a, 0) + 1);
    }
}
