// Logging Framework ( LF )

const { Kafka } = require('kafkajs');
const { Prometheus } = require('prom-client');

class LoggingFramework {
  constructor({
    kafkaBootstrapServers,
    prometheusHost,
    configFilePath,
    environmentVariables,
  }) {
    this.kafka = new Kafka({
      clientId: 'lf',
      brokers: [kafkaBootstrapServers],
    });

    this.prometheus = new Prometheus({
      registryPath: prometheusHost,
      timeout: 10000,
    });

    this.config = require(configFilePath);

    // validate environment variables against config
    Object.keys(environmentVariables).forEach((key) => {
      if (!this.config[key]) {
        throw new Error(`Invalid environment variable ${key}`);
      }
    });
  }

  async log(data, service) {
    try {
      await this.kafka.send({
        topic: 'logs',
        messages: [data],
      });
    } catch (err) {
      // retry on failure
      await setTimeout(() => {
        this.log(data, service);
      }, 1000);
    }
  }

  async getMetrics() {
    return this.prometheus.getMetricFamilyValues();
  }

  start() {
    // health checks and metrics aggregation using Prometheus or similar systems
  }
}

module.exports = LoggingFramework;
