// Define a struct to hold upload task details
struct UploadTask {
    std::string filePath;
    std::string bucketName;
    std::string authToken;
};

class CloudStorageUploader {
public:
    CloudStorageUploader() : retryCount(0), backoffTime(100) {}

    void startUploadQueue(std::queue<UploadTask> tasks, bool useS3) {
        while (!tasks.empty()) {
            UploadTask task = tasks.front();
            tasks.pop();

            if (useS3)
                uploadToS3(task.filePath, task.bucketName, task.authToken);
            else
                uploadToGCS(task.filePath, task.bucketName, task.authToken);

            std::this_thread::sleep_for(std::chrono::milliseconds(backoffTime));
        }
    }

    void uploadToS3(const std::string& filePath, const std::string& bucketName, const std::string& authToken) {
        // Implement S3 upload logic here
        std::cout << "Uploading file to S3: " << filePath << " to bucket: " << bucketName << std::endl;
    }

    void uploadToGCS(const std::string& filePath, const std::string& bucketName, const std::string& authToken) {
        // Implement GCS upload logic here
        std::cout << "Uploading file to GCS: " << filePath << " to bucket: " << bucketName << std::endl;
    }

private:
    int retryCount;
    int backoffTime;
};

// Define a function for adding a website and starting it using the Process class
