    try {
        var process = new Process();
        process.StartInfo.FileName = "iisreset.exe";
        process.StartInfo.Arguments = "/start site: " + siteName;
        process.StartInfo.WorkingDirectory = directoryPath;
        process.Start();
    }
    catch (Exception ex) {
        // Handle exceptions
    }
}
