import json
import requests
from threading import Lock
from collections import defaultdict

class DataSequenceManager:
    def __init__(self):
        self.sequence_handler = SequenceHandler()
        self.cache = {}
        self.lock = Lock()

    class SequenceHandler:
        def __init__(self):
            self.api_url = 'https://api.example.com/sequences'
            self.api_key = 'your_api_key_here'
            self.retry_delay = 10
            self.max_retries = 3

        def get_sequence(self, sequence_id):
            try:
                response = requests.get(f'{self.api_url}/{sequence_id}',
                                         headers={'Authorization': f'Bearer {self.api_key}'})
                if response.status_code == 200:
                    return json.loads(response.content)
                else:
                    raise Exception('API error')
            except (requests.exceptions.RequestException, json.JSONDecodeError) as e:
                self.retry_request(e)

        def post_sequence(self, sequence_id, data):
            try:
                response = requests.post(f'{self.api_url}/{sequence_id}',
                                          headers={'Authorization': f'Bearer {self.api_key}'},
                                          json=data)
                if response.status_code == 201:
                    return response.json()
                else:
                    raise Exception('API error')
            except (requests.exceptions.RequestException, json.JSONDecodeError) as e:
                self.retry_request(e)

        def put_sequence(self, sequence_id, data):
            try:
                response = requests.put(f'{self.api_url}/{sequence_id}',
                                         headers={'Authorization': f'Bearer {self.api_key}'},
                                         json=data)
                if response.status_code == 200:
                    return response.json()
                else:
                    raise Exception('API error')
            except (requests.exceptions.RequestException, json.JSONDecodeError) as e:
                self.retry_request(e)

        def delete_sequence(self, sequence_id):
            try:
                response = requests.delete(f'{self.api_url}/{sequence_id}',
                                           headers={'Authorization': f'Bearer {self.api_key}'})
                if response.status_code == 200:
                    return
                else:
                    raise Exception('API error')
            except (requests.exceptions.RequestException, json.JSONDecodeError) as e:
                self.retry_request(e)

        def retry_request(self, exception):
            if self.max_retries > 0 and isinstance(exception, requests.exceptions.RequestException):
                print(f'Error: {exception}. Retrying in {self.retry_delay} seconds.')
                time.sleep(self.retry_delay)
                self.retry_request(exception)
            else:
                raise Exception('API error')

        def serialize_sequence(self, sequence):
            return json.dumps(sequence)

        def deserialize_sequence(self, serialized_sequence):
            try:
                return json.loads(serialized_sequence)
            except json.JSONDecodeError as e:
                print(f'Error decoding JSON: {e}')
                return None

    @property
    def cache_key(self):
        return 'data_sequence_manager_cache'

    def get_cached_data(self, key):
        if not hasattr(self, self.cache_key):
            setattr(self, self.cache_key, defaultdict(dict))
        return getattr(self, self.cache_key)[key]

    def set_cached_data(self, key, value):
        if not hasattr(self, self.cache_key):
            setattr(self, self.cache_key, defaultdict(dict))
        getattr(self, self.cache_key)[key] = value

    def get_sequence_data(self, sequence_id):
        try:
            data = self.sequence_handler.get_sequence(sequence_id)
            return self.deserialize_sequence(data)
        except (KeyError, json.JSONDecodeError) as e:
            print(f'Error: {e}. Returning cached data.')
            return self.get_cached_data(sequence_id)

    def set_sequence_data(self, sequence_id, data):
        try:
            serialized_data = self.serialize_sequence(data)
            response = self.sequence_handler.post_sequence(sequence_id, serialized_data)
            self.set_cached_data(sequence_id, data)
            return response
        except (KeyError, json.JSONDecodeError) as e:
            print(f'Error: {e}. Returning cached data.')
            return self.get_cached_data(sequence_id)

    def update_sequence_data(self, sequence_id, data):
        try:
            serialized_data = self.serialize_sequence(data)
            response = self.sequence_handler.put_sequence(sequence_id, serialized_data)
            self.set_cached_data(sequence_id, data)
            return response
        except (KeyError, json.JSONDecodeError) as e:
            print(f'Error: {e}. Returning cached data.')
            return self.get_cached_data(sequence_id)

    def delete_sequence(self, sequence_id):
        try:
            response = self.sequence_handler.delete_sequence(sequence_id)
            del self.cache[sequence_id]
            return response
        except (KeyError, json.JSONDecodeError) as e:
            print(f'Error: {e}.')
            return None

if __name__ == '__main__':
