['Here is the C code block for the highly scalable and resilient connection pool manager:

```c
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

// Define the PDU object structure
typedef struct {
    int id;
    char* data;
} PDU;

// Define the connection pool structure
typedef struct {
    int capacity;
    int size;
    PDU** pdus;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} ConnectionPool;

// Function to create a new connection pool
ConnectionPool* create_connection_pool(int capacity) {
    ConnectionPool* pool = (ConnectionPool*) malloc(sizeof(ConnectionPool));
    pool->capacity = capacity;
    pool->size = 0;
    pool->pdus = (PDU**) malloc(capacity * sizeof(PDU*));
    pthread_mutex_init(&pool->lock, NULL);
    pthread_cond_init(&pool->cond, NULL);
    return pool;
}

// Function to add a new PDU object to the connection pool
void add_pdu(ConnectionPool* pool, int id, char* data) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size < pool->capacity) {
        PDU* pdu = (PDU*) malloc(sizeof(PDU));
        pdu->id = id;
        pdu->data = data;
        pool->pdus[pool->size] = pdu;
        pool->size++;
    } else {
        printf("Pool is full. Cannot add more PDUs.\n");
    }
    pthread_mutex_unlock(&pool->lock);
}

// Function to get a PDU object from the connection pool
PDU* get_pdu(ConnectionPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->size > 0) {
        PDU* pdu = pool->pdus[pool->size - 1];
        pool->size--;
        return pdu;
    } else {
        printf("No PDUs available in the pool.\n");
        return NULL;
    }
}

// Function to release a PDU object back into the connection pool
void release_pdu(ConnectionPool* pool, PDU* pdu) {
    pthread_mutex_lock(&pool->lock);
    pool->pdus[pool->size++] = pdu;
    pthread_mutex_unlock(&pool->lock);
}
