void insertAfter(const std::string& target, const std::string& insert, std::forward_list<std::string>& list) {
    auto it = list.begin();
    while (it != list.end()) {
        if (*it == target) {
            list.insert_after(it, insert);
            return;
        }
        ++it;
    }
    list.append(insert);
}
