#include <sys/stat.h>
#include <unistd.h>

// Configuration struct to control file traversal
typedef struct {
    int depthLimit;
    int followSymlinks;
} TraversalConfig;

// File metadata structure to store attributes and context
typedef struct {
    char* path;
    time_t modifiedTime;
    off_t fileSize;
} FileInfo;

// External metadata service interface
typedef void (*MetadataService)(const char*, FileInfo*);

// Main file traversal library function
void traverseDir(const char* dirPath, TraversalConfig config, MetadataService metadata) {
    DIR* dir = opendir(dirPath);
    if (dir == NULL) {
        perror("Failed to open directory");
        return;
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (!strcmp(entry->d_name, ".") || !strcmp(entry->d_name, ".."))
            continue;

        char filePath[256];
        sprintf(filePath, "%s/%s", dirPath, entry->d_name);

        struct stat fileStats;
        if (stat(filePath, &fileStats) < 0) {
            perror("Failed to retrieve file stats");
            continue;
        }

        FileInfo fileInfo = {filePath, fileStats.st_mtime, fileStats.st_size};

        // Validate file attributes using metadata service
        metadata(filePath, &fileInfo);

        // Recursively traverse subdirectories if depth limit not reached
        if (S_ISDIR(fileStats.st_mode) && config.depthLimit > 0) {
            int currentDepth = 1;
            while (currentDepth <= config.depthLimit && fileStats.st_mode == S_IFDIR) {
                char subdirPath[256];
                sprintf(subdirPath, "%s/%s", filePath, entry->d_name);
                traverseDir(subdirPath, config, metadata);

                // Decrement depth limit and break if reached max depth
                currentDepth++;
            }
        }

        free(filePath);
    }

    closedir(dir);
}

// Example usage of the file traversal library
int main() {
    TraversalConfig config = {3, 1}; // Traverse up to 3 levels deep, following symbolic links
    MetadataService metadata = myMetadataService; // Replace with your actual metadata service implementation

    traverseDir("/path/to/directory", &config, metadata);

    return 0;
}
