typedef struct {
    char path[256];
    struct stat sb;
} FileOrLink;

// Function to compare two directory paths
int comparePaths(const void* a, const void* b) {
    // Implement your comparison logic here
}

// Function to traverse a directory and its contents
void* traverseDirectory(void* dirp) {
    Directory* dir = (Directory*)dirp;
    pthread_mutex_lock(&dir->lock);

    // Traverse the directory using dirent.h API
    DIR* d = opendir(dir->path);
    if (!d) {
        // Handle errors in traversing the directory
    }

    struct dirent* de;
    while ((de = readdir(d)) != NULL) {
        char path[256];
        sprintf(path, "%s/%s", dir->path, de->d_name);

        // Check for symbolic links and traverse recursively if necessary
        if (S_ISLNK(de->d_type)) {
            FileOrLink* fileOrLink = malloc(sizeof(FileOrLink));
            fileOrLink->path = path;
            fileOrLink->sb.st_size = lstat(path, &fileOrLink->sb);

            pthread_t thread;
            pthread_create(&thread, NULL, traverseDirectory, (void*)fileOrLink);
            pthread_join(thread, NULL);
            free(fileOrLink);
        } else {
            // Process the directory or file contents here
        }
    }

    closedir(d);
    pthread_mutex_unlock(&dir->lock);

    return NULL;
}

// Function to start traversing a directory
void startTraversal(Directory* dir) {
    pthread_t thread;
    pthread_create(&thread, NULL, traverseDirectory, (void*)dir);
    pthread_join(thread, NULL);
}
