public class DataPipelineManager {
    private Map<String, DataPipeline> pipelines = new HashMap<>();

    public void startPipeline(String pipelineName) {
        if (!pipelines.containsKey(pipelineName)) {
            // Create a new pipeline instance and add it to the map
            DataPipeline pipeline = new DataPipeline();
            pipelines.put(pipelineName, pipeline);
            pipeline.start();
        }
    }

    public void stopPipeline(String pipelineName) {
        if (pipelines.containsKey(pipelineName)) {
            // Stop the specified pipeline
            DataPipeline pipeline = pipelines.get(pipelineName);
            pipeline.stop();
            pipelines.remove(pipelineName);
