function getElementsWithSelector(root, selector, callback) {
  const result = [];
  (function traverse(node) {
    if (!node) return;
    if (node.matches(selector)) {
      callback(node);
      result.push(node);
    }
    Array.from(node.children).forEach(traverse);
  })(root);
  return result;
}
