app.post('/config/update', async (req, res) => {
  try {
    const configFiles = await fs.promises.readdir('./configs');
    for (const file of configFiles) {
      if (!file.endsWith('.json')) continue;
      const configFile = path.join('./configs/', file);
      const configFileContent = await fs.promises.readFile(configFile, 'utf8');
      const encryptedKey = crypto.createCipher('aes-256-cbc', req.body.key).update(req.body.config, 'utf8', 'hex');
      const updatedConfig = configFileContent.replace(/{{placeholder}}/, encryptedKey.toString());
      await fs.promises.writeFile(configFile, updatedConfig);
    }
