  try {
    const docId = req.params.docId;
    const docPath = path.join('./docs/', `${docId}.json`);
    const docContent = await fs.promises.readFile(docPath, 'utf8');
    res.send(docContent);
  } catch (err) {
    console.error(err);
    if (err.code === 'ENOENT') {
      res.status(404).send({ message: `Document not found: ${docId}` });
    } else {
      res.status(500).send({ message: `Failed to retrieve document: ${docId}` });
    }
  }
});

// Queueing System for Request Volume
