#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int key;
    char value[256];
    struct record* next;
} record;

record* createRecord(int key, const char* value) {
    record* newRecord = (record*)malloc(sizeof(record));
    if (!newRecord) return NULL;
    newRecord->key = key;
    strcpy(newRecord->value, value);
    newRecord->next = NULL;
    return newRecord;
}

void freeRecords(record** records) {
    record* current = *records;
    record* next;
    while (current) {
        next = current->next;
        free(current);
        current = next;
    }
