typedef struct {
    char* hash;
    time_t timestamp;
    char prefix[PREFIX_MAX_LENGTH + 1];
} DocumentUUID;

DocumentUUID* generate_uuid(const char* content, size_t length) {
    // Compute SHA-256 hash of the input content
    unsigned char hash[HASH_SIZE];
    SHA256(content, length, hash);

    // Generate a timestamp using the current time
    time_t now = time(NULL);
    struct tm* timestamp_tm = localtime(&now);
    char timestamp_str[TIMESTAMP_SIZE + 1];
    strftime(timestamp_str, TIMESTAMP_SIZE + 1, "%Y%m%d%H%M%S", timestamp_tm);

    // Concatenate the hash and timestamp with a prefix
    DocumentUUID* uuid = malloc(sizeof(DocumentUUID));
    sprintf(uuid->hash, "%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x",
            hash[0], hash[1], hash[2], hash[3], hash[4], hash[5], hash[6], hash[7],
            hash[8], hash[9]);
    strcpy(uuid->prefix, "document:");
    uuid->timestamp = now;
    return uuid;
}

