            scores = cosine_similarity([product.features], [similar_user.products[i].features])
            similarity_scores.append((scores, similar_user.id))
        recommendation = max(similarity_scores)[1]
        recommendations.append(recommendation)
    return recommendations

def content_based_filtering(user_id):
    user_profile = User.query.get(user_id).profile
    product_features = Product.query.all()
    scores = []
    for product in product_features:
        score = pearsonr(user_profile, product.features)[0]
        scores.append((score, product.id))
    recommendations = [product[1] for product in sorted(scores, reverse=True)]
