LoadBalancerEntry* create_load_balancer_entry(char* ip_address, int port) {
    LoadBalancerEntry* entry = (LoadBalancerEntry*)malloc(sizeof(LoadBalancerEntry));
    entry->ip_address = ip_address;
    entry->port = port;
    entry->available_endpoints = 0;
    return entry;
}

// Function to perform a health check on a connection pool entry
int perform_health_check(ConnectionPoolEntry* entry) {
    // Send an HTTP request to the endpoint and wait for the response
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    connect(sock, (struct sockaddr*)inet_addr(entry->ip_address), htons(entry->port));
    send(sock, "GET /healthcheck HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n", strlen("GET /healthcheck HTTP/1.1\r\nHost: localhost\r\nConnection: close\r\n\r\n"), 0);
    char buffer[1024];
    recv(sock, buffer, sizeof(buffer), 0);
    close(sock);
    if (buffer[0] == '2') {
        return 1; // Endpoint is available
    } else {
        return 0; // Endpoint is unavailable
    }
}

