bool insertOrAppendWithLock(std::forward_list<std::string>& data, const std::string& targetString,
                             const std::string& insertString, bool lockableResourceFlag) {
    if (data.empty()) {
        // Handle edge case: empty list
        return true;
    }

    std::unique_lock<std::mutex> lock;

    if (lockableResourceFlag) {
        while (true) {
            try {
                // Attempt to acquire the distributed lock
                // ...
                break;  // Lock acquired successfully, proceed with operation
            } catch (const std::exception& e) {
                // Handle concurrent modification error and retry up to five times
                if (++lock.attempts < 5) {
                    std::this_thread::sleep_for(std::chrono::milliseconds(lock.backoff));
                } else {
                    // Lock cannot be acquired, fail gracefully
                    return false;
                }
            }
        }
    }

    bool found = false;
    for (auto& str : data) {
        if (str == targetString) {
            found = true;
            break;  // Found the target string, insert the new string atomically
        }
    }

    if (!found) {
        // Append the new string instead
        data.push_back(insertString);
    } else {
        auto it = std::find(data.begin(), data.end(), targetString);
        if (it != data.end()) {
            data.insert_after(it, insertString);
        }
    }

    return true;
}
