  private jwt: JWTService;

  constructor() {
    this.users = [];
    this.oAuth2 = new OAuth2Service();
    this.jwt = new JWTService();
  }

  async authenticate(username: string, password: string) {
    const userIndex = this.users.findIndex((user) => user.username === username);
    if (userIndex !== -1) {
      const user = this.users[userIndex];
      if (await user.checkPassword(password)) {
        return { token: await this.jwt.generateToken(user.id), user };
      }
    }
  }

  async authenticateOAuth2(code: string) {
    return await this.oAuth2.exchangeCodeForAccessToken(code);
  }

  async authenticateJWT(token: string) {
    return await this.jwt.validateToken(token);
  }
}

