// Command execution framework
void* execute_command(void* cmd) {
    // Get the command from the void pointer
    Command* c = (Command*)cmd;

    // Execute the command with given resources and priorities
    system(c->command);

    // Free allocated memory
    free(cmd);
}

// Create a new command with given details
Command* create_command(char* cmd, int priority, int max_cpu_time, int max_memory) {
    Command* c = (Command*)malloc(sizeof(Command));
    c->command = strdup(cmd);
    c->priority = priority;
    c->max_cpu_time = max_cpu_time;
    c->max_memory = max_memory;

    return c;
}

// Create and execute a command
int create_and_execute_command(char* cmd, int priority, int max_cpu_time, int max_memory) {
