    pthread_t thread;
    if(pthread_create(&thread, NULL, (void*)execute_command, c)) {
        return -1; // Failed to create the thread
    }

    pthread_join(thread, NULL);

    free(c->command);
    free(c);

    return 0; // Successful execution
