#include <iostream>
#include <string>
#include <hash_map>
#include <algorithm>

std::string md5(const std::string& input) {
    unsigned char result[16];
    SHA256_CTX shaContext;
    SHA256_Init(&shaContext);
    const char* input_str = input.c_str();
    size_t len = input.length();
    size_t i;
    for (i = 0; i < len; ++i) {
        SHA256_Update(&shaContext, &input_str[i], 1);
    }
    SHA256_Final(result, &shaContext);
    std::string output;
    for (size_t i = 0; i < 16; i++) {
        char buff[3];
        sprintf(buff, "%02x", result[i]);
        output += buff;
    }
    return output;
}

int main() {
    std::cout << md5("Hello World!") << std::endl;
    return 0;
}
```

This function uses the OpenSSL library to compute the MD5 hash of a given string.']

