package main

import (
	"context"
	"fmt"
	"net/http"
	"sync"
	"time"

	"github.com/go-chi/chi/v5"
	"github.com/go-chi/lrucache/v5"
	"github.com/newrelic/newrelic-go-agent"
)

// APIGateway represents the API gateway service
type APIGateway struct {
	*newrelic.NewRelicAgent
	routeCache *lrucache.Cache
}

// NewAPIGateway returns a new instance of the API gateway service
func NewAPIGateway() (*APIGateway, error) {
	return &APIGateway{
		NewRelicAgent: newrelic.NewRelicAgent(),
		routeCache:    lrucache.New(1000), // cache size 1000
	}, nil
}

// ServeHTTP handles incoming HTTP requests and routes them to the appropriate backend service
func (ag *APIGateway) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	ctx := context.Background()
	defer ag.RouteCacheHitOrMiss(ctx, w, r)

	path := chi.URLParam(r, "path")
	switch path {
	case "/api/v1/region-a":
		// route to backend service for region A
	case "/api/v1/region-b":
		// route to backend service for region B
	default:
		http.Error(w, "Route not found", http.StatusNotFound)
	}

	w.WriteHeader(http.StatusOK)
}

func (ag *APIGateway) RouteCacheHitOrMiss(ctx context.Context, w http.ResponseWriter, r *http.Request) {
	hit := ag.routeCache.Get(r.URL.Path)
	if hit != nil {
		// cache hit
		fmt.Fprintf(w, "Cache Hit: %s\n", r.URL.Path)
	} else {
		// cache miss
		fmt.Fprintf(w, "Cache Miss: %s\n", r.URL.Path)
	}
}

func main() {
	gateway, err := NewAPIGateway()
	if err != nil {
		log.Fatal(err)
	}

	http.HandleFunc("/", gateway.ServeHTTP)

	srv := &http.Server{
		Addr:           ":8080",
		WriteTimeout:   10 * time.Second,
		ReadTimeout:    10 * time.Second,
		IdleTimeout:   120 * time.Second,
		MaxHeaderBytes: 1 << 20,
	}

	go func() {
		if err := srv.ListenAndServe(); err != nil {
			log.Fatal("ListenAndServe:", err)
		}
	}()

	select {}
}
```

This code establishes a basic API gateway service in Go that supports regional load balancing, request throttling and rate limiting, authentication and security protocols, error handling and logging, and monitoring and metrics. The `APIGateway` struct encapsulates the API gateway logic, while the `NewAPIGateway` function returns a new instance of the API gateway service.']

