#include <vector>
#include <optional>
#include <string>
#include <curl/curl.h>

std::vector<std::optional<std::string>> sendRequests(const std::vector<std::string>& requests) {
    CURL *curl;
    CURLcode res;
    std::vector<std::optional<std::string>> responses;

    for (const auto& request : requests) {
        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
        if(curl) {
            curl_easy_setopt(curl, CURLOPT_URL, "http://example.com/api/endpoint");
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, request.c_str());
            res = curl_easy_perform(curl);

            if(CURLE_OK == res) {
                std::string response;
                CURL *easy_handle = curl;
                size_t len;
                char *ptr;

                curl_easy_getinfo(easy_handle, CURLINFO_EFFECTIVE_URL, &response);
                curl_easy_getinfo(easy_handle, CURLINFO_RESPONSE_CODE, &len);
                ptr = new char[len+1];
                curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, &writeMemoryCallback);
                curl_easy_setopt(curl, CURLOPT_WRITEDATA, ptr);
                res = curl_easy_perform(curl);
                response.assign(ptr, len);
                delete[] ptr;

                if(CURLE_OK == res) {
                    responses.push_back(std::optional<std::string>(response));
                } else {
                    responses.push_back(std::nullopt);
                }
            } else {
                responses.push_back(std::nullopt);
            }

            curl_easy_cleanup(curl);
        }
    }

    curl_global_cleanup();
    return responses;
}

static size_t writeMemoryCallback(void *ptr, size_t size, size_t nmemb, void *data) {
    ((std::string*)data)->assign((char*)ptr, size*nmemb);
    return size*nmemb;
}']

