#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define structure for LTE RRC NAS Message node
typedef struct {
    int ue_id;
    int message_id;
    void* payload; // dynamically allocated memory
} lte_rrc_nas_message_node;

// Define function to create new message node
lte_rrc_nas_message_node* lte_rrc_create_message_node(int ue_id, int message_id) {
    lte_rrc_nas_message_node* node = (lte_rrc_nas_message_node*)malloc(sizeof(lte_rrc_nas_message_node));
    if (!node) return NULL;

    node->ue_id = ue_id;
    node->message_id = message_id;
    node->payload = NULL; // initialize payload as null

    return node;
}

// Define function to add a new message node at the end of the list
void lte_rrc_add_message_node(lte_rrc_nas_message_node** head, int ue_id, int message_id) {
    lte_rrc_nas_message_node* new_node = lte_rrc_create_message_node(ue_id, message_id);
    if (!new_node) return;

    if (*head == NULL) {
        *head = new_node;
    } else {
        lte_rrc_nas_message_node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

// Define function to remove a message node from the list
void lte_rrc_remove_message_node(lte_rrc_nas_message_node** head, int ue_id, int message_id) {
    if (*head == NULL) return;

    if ((*head)->ue_id == ue_id && (*head)->message_id == message_id) {
        lte_rrc_nas_message_node* temp = *head;
        *head = (*head)->next;
        free(temp);
    } else {
        lte_rrc_nas_message_node* current = *head;
        while (current->next != NULL && current->next->ue_id != ue_id || current->next->message_id != message_id) {
            current = current->next;
        }
        if (current->next != NULL) {
            lte_rrc_nas_message_node* temp = current->next;
            current->next = current->next->next;
            free(temp);
        }
    }
}

// Define function to serialize the linked list into a compact binary format
void lte_rrc_serialize_message_list(lte_rrc_nas_message_node* head, FILE* output) {
    if (head == NULL) return;

    fwrite(&head->ue_id, sizeof(int), 1, output);
    fwrite(&head->message_id, sizeof(int), 1, output);

    lte_rrc_nas_message_node* current = head;
    while (current != NULL) {
        // serialize payload
        fwrite(&current->payload, sizeof(void*), 1, output);
        current = current->next;
    }
}

// Define function to deserialize the linked list from a compact binary format
lte_rrc_nas_message_node* lte_rrc_deserialize_message_list(FILE* input) {
    int ue_id;
    int message_id;

    // Read header information
    fread(&ue_id, sizeof(int), 1, input);
    fread(&message_id, sizeof(int), 1, input);

    // Create new node with the read UE ID and Message ID
    lte_rrc_nas_message_node* head = lte_rrc_create_message_node(ue_id, message_id);

    if (head == NULL) return NULL;

    // Read payload information for each node in the list
    while (!feof(input)) {
        // deserialize payload
        fread(&head->payload, sizeof(void*), 1, input);
        head = head->next;
    }

    return head;
}

// Define function to print the linked list in human-readable format
void lte_rrc_print_message_list(lte_rrc_nas_message_node* head) {
    if (head == NULL) return;

    printf("UE ID: %d, Message ID: %d\n", head->ue_id, head->message_id);

    lte_rrc_nas_message_node* current = head;
    while (current != NULL) {
        // print payload
        printf("%p\n", current->payload);
        current = current->next;
    }
}

int main() {
    // Create a sample linked list
    lte_rrc_nas_message_node* head = NULL;
    lte_rrc_add_message_node(&head, 1, 10);
    lte_rrc_add_message_node(&head, 2, 20);
    lte_rrc_add_message_node(&head, 3, 30);

    // Serialize the linked list
    FILE* output = fopen("message_list.bin", "wb");
    if (output) {
        lte_rrc_serialize_message_list(head, output);
        fclose(output);
    }

    // Deserialize and print the linked list
    FILE* input = fopen("message_list.bin", "rb");
    if (input) {
        lte_rrc_nas_message_node* deserialized_head = lte_rrc_deserialize_message_list(input);
        lte_rrc_print_message_list(deserialized_head);
        fclose(input);
    }

    return 0;
}

