using System;
using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using RabbitMQ.Client;

namespace TransactionFilterService
{
    public class TransactionFilterService : ITransactionFilterService
    {
        private readonly ILogger<TransactionFilterService> _logger;
        private readonly IConnection _rabbitMqConnection;
        private readonly ITimer _timer;
        private readonly IPaymentGateway _paymentGateway;
        private readonly ICachingLayer _cachingLayer;
        private readonly IFraudDetectionSystem _fraudDetectionSystem;

        public TransactionFilterService(ILogger<TransactionFilterService> logger, 
                                         IConnection rabbitMqConnection, 
                                         ITimer timer, 
                                         IPaymentGateway paymentGateway, 
                                         ICachingLayer cachingLayer, 
                                         IFraudDetectionSystem fraudDetectionSystem)
        {
            _logger = logger;
            _rabbitMqConnection = rabbitMqConnection;
            _timer = timer;
            _paymentGateway = paymentGateway;
            _cachingLayer = cachingLayer;
            _fraudDetectionSystem = fraudDetectionSystem;
        }

        public async Task FilterTransactionsAsync(Transaction[] transactions)
        {
            foreach (var transaction in transactions)
            {
                // Filter transactions based on age, frequency, and weighted sum threshold
                if (!IsTransactionValid(transaction))
                {
                    await _rabbitMqConnection.BasicPublish(exchange: "transaction_filter_exchange", routingKey: "invalid_transactions_queue", body: Encoding.UTF8.GetBytes(JsonConvert.SerializeObject(transaction)));
                }
                else
                {
                    // Perform fraud detection using machine learning model and external dependencies
                    var isFraudulent = await _fraudDetectionSystem.IsFraudulentAsync(transaction);
                    if (isFraudulent)
                    {
                        await _paymentGateway.CancelTransactionAsync(transaction);
                    }
                    else
                    {
                        // Process legitimate transaction
                        await _cachingLayer.PutTransactionAsync(transaction);
                    }
                }
            }
        }

        public async Task StartFilteringAsync()
        {
            while (true)
            {
                try
                {
                    var transactions = await _rabbitMqConnection.BasicConsume(queue: "transactions_queue", onMessage: (model, message) =>
                    {
                        // Process transaction messages from RabbitMQ
                        FilterTransactionsAsync(JsonConvert.DeserializeObject<Transaction[]>(message.Body));
                    });
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "Error processing transactions");
                }
            }
        }
    }
}
