// Structure representing an LTE RRC NAS Message node
typedef struct {
    int UE_ID;
    int Message_ID;
    void* payload; // dynamically allocated memory for the message payload
} Node;

// Structure representing a doubly-linked list of LTE RRC NAS Messages
typedef struct {
    Node* head;
    Node* tail;
} List;

// Create a new node with given UE ID, Message ID and payload
Node* create_node(int UE_ID, int Message_ID, void* payload) {
    // allocate memory for the node
    Node* node = (Node*)malloc(sizeof(Node));
    if(node == NULL) {
        return NULL;
    }
    node->UE_ID = UE_ID;
    node->Message_ID = Message_ID;
    node->payload = payload;
    return node;
}

// Create a new list and initialize it with given head and tail
List* create_list(Node* head, Node* tail) {
    // allocate memory for the list
    List* list = (List*)malloc(sizeof(List));
    if(list == NULL) {
        return NULL;
    }
    list->head = head;
    list->tail = tail;
    return list;
}

// Add a new node to the end of the list
void add_node(List* list, Node* node) {
    // check if list is empty or not
    if(list->tail != NULL) {
        list->tail->next = node; // update the next pointer for the last node in the list
    } else {
        list->head = node; // set the head to be this new node if the list was previously empty
    }
    list->tail = node;
}

