            } else {
                // Synchronous insertion with concurrent failure handling
                try {
                    lockableData.insert_after(it, insertString);
                } catch (const std::exception& e) {
                    LOG_ERROR("ConcurrencyError");
                    return ConcurrencyError;
                }
            }

            break;
        }
    }

    if (!lockableResourceFlag && lockableData.empty()) {
        // Append insertString to the end of the list
        lockableData.insert_after(lockableData.end(), insertString);
    } else if (targetString.empty() || insertString.empty()) {
        LOG_ERROR("Invalid input");
        return InvalidInput;
    }

    // Add cryptographic primitives using EVP_add_cipher and EVP_add_digest
    if (initCryptographicPrimitives) {
        // Initialize AES cipher with 128-bit key and 256-bit IV
        unsigned char aesKey[16] = {0x00, 0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77};
        unsigned char aesIV[32] = {0x88, 0x99, 0xaa, 0xbb, 0xcc, 0xdd, 0xee, 0xff, 0x00, 0x11, 0x22, 0x33};
        EVP_add_cipher(EVP_aes_128_cbc(), aesKey, sizeof(aesKey), aesIV, sizeof(aesIV));

        // Initialize Camellia cipher with 256-bit key and 256-bit IV
        unsigned char camelliaKey[32] = {0x00, 0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77, 0x88, 0x99, 0xaa, 0xbb};
        unsigned char camelliaIV[32] = {0xcc, 0xdd, 0xee, 0xff, 0x00, 0x11, 0x22, 0x33, 0x44, 0x55, 0x66, 0x77};
        EVP_add_cipher(EVP_camellia_256_cbc(), camelliaKey, sizeof(camelliaKey), camelliaIV, sizeof(camelliaIV));

        // Initialize MD5 digest
        EVP_add_digest(EVP_md5());

        // Initialize SHA-1 digest
        EVP_add_digest(EVP_sha1());
    }

    return Success;
}
