typedef struct {
    time_t timestamp;
    char *event_type;
    char *description;
} NetworkEventLogEntry;

// Create a dynamic list to store NetworkEventLogEntry structures
typedef struct {
    NetworkEventLogEntry **entries;
    int size;
    int capacity;
} LogList;

// Function to initialize the log list with the given initial capacity
void init_log_list(LogList *log_list, int initial_capacity) {
    log_list->size = 0;
    log_list->capacity = initial_capacity;
    log_list->entries = (NetworkEventLogEntry **)malloc(initial_capacity * sizeof(NetworkEventLogEntry *));
}

// Function to append a new NetworkEventLogEntry structure to the log list
void add_entry(LogList *log_list, NetworkEventLogEntry *entry) {
    if (log_list->size >= log_list->capacity) {
        // Dynamically resize the array when it's full
        log_list->capacity *= 2;
        log_list->entries = (NetworkEventLogEntry **)realloc(log_list->entries, log_list->capacity * sizeof(NetworkEventLogEntry *));
    }
    log_list->entries[log_list->size] = entry;
    log_list->size++;
}

// Function to free the memory allocated for the log list
void free_log_list(LogList *log_list) {
    if (log_list->entries != NULL) {
        for (int i = 0; i < log_list->size; i++) {
            if (log_list->entries[i] != NULL) {
                free(log_list->entries[i]->event_type);
                free(log_list->entries[i]->description);
                free(log_list->entries[i]);
            }
        }
        free(log_list->entries);
    }
}

