// Thread pool size configuration
const int THREAD_POOL_SIZE = 10;

// File processing chunk size (in bytes)
const int CHUNK_SIZE = 1024 * 1024; // 1MB

class DynamicFileProcessor {
public:
    DynamicFileProcessor(int threadPoolSize) : threadPoolSize_(threadPoolSize), threads_(), chunkQueue_() {}

    void startProcessing(const std::string& filePath, const std::string& tenantId) {
        // Create a new thread for processing
        auto t = std::thread([this, filePath, tenantId]() {
            processFile(filePath, tenantId);
        });
        threads_.push(t);

        // Start the file processing in the newly created thread
        while (threads_.size() > THREAD_POOL_SIZE) {
            // Wait until a thread finishes processing and returns to the pool
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
    }

    void stopProcessing() {
        // Stop all threads from processing
        for (auto& t : threads_) {
            t.join();
        }
        threads_.clear();

        // Clean up any remaining resources
        chunkQueue_.clear();
    }

private:
    int threadPoolSize_;
    std::vector<std::thread> threads_;
    std::queue<std::thread> chunkQueue_;

    void processFile(const std::string& filePath, const std::string& tenantId) {
