typedef struct {
    State* states;
    int num_states;
    pthread_mutex_t mutex;
} FSA;

// Function to create an FSA instance
FSA* create_fsa(int num_states) {
    FSA* fsa = (FSA*)malloc(sizeof(FSA));
    fsa->num_states = num_states;
    fsa->states = (State*)malloc(num_states * sizeof(State));
    pthread_mutex_init(&fsa->mutex, NULL);
    return fsa;
}

// Function to free an FSA instance
void free_fsa(FSA* fsa) {
    if (fsa != NULL) {
        pthread_mutex_destroy(&fsa->mutex);
        free(fsa->states);
        free(fsa);
    }
}

// Function to add a state to the FSA
int add_state(FSA* fsa, int id, char* name) {
    // Check if the state already exists
    for (int i = 0; i < fsa->num_states; i++) {
        if (fsa->states[i].id == id) return -1;
    }

    // Add the new state to the list
    State* state = (State*)malloc(sizeof(State));
    state->id = id;
    state->name = strdup(name);
    pthread_mutex_lock(&fsa->mutex);
    fsa->states[fsa->num_states++] = *state;
    pthread_mutex_unlock(&fsa->mutex);
