// Define the states of the FSA
typedef enum {
    STATE_A,
    STATE_B,
    STATE_C,
    // Add more states as needed
} State;

// Define a struct to represent a transition
typedef struct {
    State from;
    State to;
    void (*callback)(void *);
} Transition;

// Define a struct to represent the FSA state machine
typedef struct {
    State current_state;
    Transition* transitions;
    int num_transitions;
    pthread_mutex_t lock;
    pthread_cond_t condition;
} FsaMachine;

// Function to handle state transition
void transition(FsaMachine* fsa, State new_state) {
    // Check if the transition is valid
    for (int i = 0; i < fsa->num_transitions; i++) {
        if (fsa->transitions[i].from == fsa->current_state && fsa->transitions[i].to == new_state) {
            // Perform the callback associated with the transition
            fsa->transitions[i].callback(fsa);
            return;
        }
    }

    // If no valid transition found, roll back to previous state
    printf("Invalid transition! Rolling back to previous state...\n");
}

// Function to handle a new state update from an external API
void update_state(FsaMachine* fsa, State new_state) {
    pthread_mutex_lock(&fsa->lock);
    fsa->current_state = new_state;
    pthread_cond_signal(&fsa->condition);
    pthread_mutex_unlock(&fsa->lock);
}

// Function to handle a request for the current state
void get_current_state(FsaMachine* fsa, void (*callback)(State)) {
    pthread_mutex_lock(&fsa->lock);
    callback(fsa->current_state);
    pthread_mutex_unlock(&fsa->lock);
}

