            : eventID(eventID), timestamp(timestamp), source(source), priority(priority) {}
    };

    PriorityEventQueue() : stopped(false), queue(), mutex(), notEmptyCondition(),
                            notFullCondition() {}

    void enqueue(const CustomNetworkEvent& event) {
        std::unique_lock<std::mutex> lock(mutex);
        while (queue.size() >= maxCapacity && !stopped) {
            notFullCondition.wait(lock, [this] { return queue.size() < maxCapacity || stopped; });
        }
        queue.push(event);
        lock.unlock();
        notEmptyCondition.notify_one();
    }

    void dequeue(CustomNetworkEvent& event) {
        std::unique_lock<std::mutex> lock(mutex);
        while (queue.empty() && !stopped) {
            notEmptyCondition.wait(lock, [this] { return !queue.empty() || stopped; });
        }
        if (!queue.empty()) {
            event = queue.front();
            queue.pop();
            lock.unlock();
            notFullCondition.notify_one();
        } else {
            lock.unlock();
            // handle empty queue
        }
    }

    void stop() {
        std::unique_lock<std::mutex> lock(mutex);
        stopped = true;
        lock.unlock();
        notEmptyCondition.notify_all();
        notFullCondition.notify_all();
    }

private:
    const int maxCapacity = 1000; // adjust as needed
    bool stopped;
    std::queue<CustomNetworkEvent> queue;
    mutable std::mutex mutex;
    std::condition_variable notEmptyCondition;
    std::condition_variable notFullCondition;
};
