        public async Task<(int, int)> GetRandomFloatRange(string configurationId)
        {
            while (true)
            {
                try
                {
                    var config = await _distributedCache.GetConfigurationAsync(configurationId);
                    if (config.HasValue)
                        return config.Value;
                }
                catch (TransientFailureException)
                {
                    // Retry with exponential backoff
                    await Task.Delay(500);
                }
                catch (PermanentFailureException)
                {
                    // Fallback mechanism for configuration updates when the primary API is unavailable
                    var fallbackConfig = _machineLearningModel.PredictConfiguration();
                    if (fallbackConfig.HasValue)
                        return fallbackConfig.Value;
                }
