          field.value = response.result;
        }
      });
    }
  });
}

function sendRequestToParentWindow(resourceId, url) {
  return new Promise(function(resolve, reject) {
    window.parent.postMessage({
      resourceId: resourceId,
      url: url
    }, '*');
    setTimeout(function() {
      if (window.parent.postMessageResult === undefined) {
        reject(new Error('Message not received'));
      } else {
        resolve(window.parent.postMessageResult);
      }
    }, 1000);
  });
}
