#include <stdio.h>
#include <stdlib.h>

// Structure to represent a state in a finite state automaton (FSA)
typedef struct State {
    char* name;
    struct State* transitions[256];  // 8 bits for ASCII characters
} State;

// Function to create a new state list by finding a list of states in an FSA
State* findStatesInFSAPtr(State* start, char* end, int* length) {
    State* currentState = start;
    State* newStateList = NULL;
    int newStateLength = 0;

    while (currentState != NULL && strcmp(currentState->name, end) != 0) {
        if (strcmp(currentState->name, "start") == 0 || strcmp(currentState->name, "end") == 0) {
            // Skip start and end states
            currentState = currentState->transitions[0];
        } else {
            newStateList = realloc(newStateList, (newStateLength + 1) * sizeof(State*));
            newStateList[newStateLength] = currentState;
            newStateLength++;
            currentState = currentState->transitions[0];
        }
    }

    *length = newStateLength;
    return newStateList;
}
