        : threadPoolSize_(threadPoolSize), chunkSize_(chunkSize) {}

    void processFiles(const std::vector<std::string>& fileNames) {
        // Concurrently segment and process files using thread pool
        std::vector<std::thread> threads;
        for (size_t i = 0; i < threadPoolSize_; ++i) {
