// Function to dynamically load a shared library
void load_shared_library(char* name) {
    // Load the library using dlopen and dlsym
    void* lib = dlopen(name, RTLD_LAZY);
    if (!lib) {
        fprintf(stderr, "Error loading %s: %s\n", name, dlerror());
        return;
    }

    // Get the load function from the library
    void (*load_fn)(void) = (void (*)(void))dlsym(lib, "load");
    if (!load_fn) {
        fprintf(stderr, "Error getting 'load' symbol from %s: %s\n", name, dlerror());
