    // Load the library using dlopen and dlsym
    void* lib = dlopen(name, RTLD_LAZY);
    if (!lib) {
        fprintf(stderr, "Error loading %s: %s\n", name, dlerror());
        return;
    }

    // Get the dependencies from the library
    char** dependencies = (char**)dlsym(lib, "dependencies");
    int count = 0;
    for (int i = 0; dependencies[i]; i++) {
        count++;
    }

    // Resolve the dependencies
    for (int i = 0; i < count; i++) {
        char* dependency = dependencies[i];
        void* lib_dependency = dlopen(dependency, RTLD_LAZY);
        if (!lib_dependency) {
            fprintf(stderr, "Error loading %s: %s\n", dependency, dlerror());
            continue;
