    private readonly Random _random = new Random();
    private int _minValue, _maxValue;
    private float _stepSize;
    private bool _initialized;
    private readonly DistributedCache _cache;
    private readonly MachineLearningModel _mlm;

    public DynamicAdaptiveValueGenerator(DistributedCache cache, MachineLearningModel mlm)
    {
        _cache = cache;
        _mlm = mlm;
    }

    public void Initialize(int minValue, int maxValue, float stepSize)
    {
        lock (_syncLock)
        {
            if (!_initialized)
            {
                _minValue = minValue;
                _maxValue = maxValue;
                _stepSize = stepSize;
                _initialized = true;
            }
        }
    }

    public float GenerateRandomFloat()
    {
        return (float)_random.NextDouble() * (_maxValue - _minValue) + _minValue;
    }

    public int GenerateRandomInt()
    {
        return _random.Next(_minValue, _maxValue);
    }

    public async Task<int> GenerateRandomAsync(int count)
    {
        await Task.Run(() =>
        {
            List<int> results = new List<int>();
            for (int i = 0; i < count; i++)
            {
                results.Add(_random.Next(_minValue, _maxValue));
            }
            return results;
        });
    }

    public async Task<float[]> GenerateRandomFloatsAsync(int count)
    {
        await Task.Run(() =>
        {
            List<float> results = new List<float>();
            for (int i = 0; i < count; i++)
            {
                results.Add((float)_random.NextDouble() * (_maxValue - _minValue) + _minValue);
            }
            return results.ToArray();
        });
    }

    public async Task<string[]> ResolveHostnamesAsync(string[] hostnames)
    {
        List<string> results = new List<string>();
        foreach (string hostname in hostnames)
        {
            try
            {
                IPHostEntry ipEntry = await Dns.GetHostEntryAsync(hostname);
                results.Add(ipEntry.AddressList[0].ToString());
            }
            catch (Exception ex)
            {
                results.Add("Error: " + ex.Message);
            }
        }
        return results.ToArray();
    }

    public void ValidateInput(int minValue, int maxValue, float stepSize)
    {
        if (minValue > maxValue || stepSize <= 0)
        {
            throw new ArgumentException("Invalid input");
        }
    }

    public async Task LogOperationAsync(string operation, string distributionType, object[] parameters)
    {
        await _mlm.LogAsync(operation, distributionType, parameters);
    }
