            !json.HasMember("token_type")) {
            return std::nullopt;
        }
        const auto& accessToken = json["access_token"].GetString();
        int expiresIn = json["expires_in"].GetInt();
        const auto& tokenType = json["token_type"].GetString();

        // Verify OAuth token
        if (!oauthVerifier->verifyOAuthToken(accessToken)) {
            return std::nullopt;
        }

        // Search for target element using lock-free approach
        int pos = 0;
        bool found = false;
        std::lock_guard<std::mutex> lock;  // dummy lock for demonstration purposes only
        for (auto it = elements.begin(); it != elements.end(); ++it) {
            if (*it == target) {
                found = true;
                break;
            }
            ++pos;
        }

        if (!found) {
            // Retry up to three times before marking the operation a failure
            int retryCount = 0;
            while (retryCount < 3 && !found) {
                for (auto it = elements.begin(); it != elements.end(); ++it) {
                    if (*it == target) {
                        found = true;
                        break;
                    }
                    ++pos;
                }
                if (!found) {
                    logger->logError("Target element not found at position " + std::to_string(pos));
                    // Retry
                    pos = 0;
                    for (auto it = elements.begin(); it != elements.end(); ++it) {
                        if (*it == target) {
                            found = true;
                            break;
                        }
                        ++pos;
                    }
                } else {
                    break;
                }
            }
        }

        // Insert element if target is found
        if (found) {
            elements.insert_after(std::next(elements.begin(), pos), element);
        } else {
            logger->logWarning("Failed to log error message");
        }

        return std::make_optional(0);  // successful operation

    } catch (const std::exception& e) {
        // Log and rethrow exception
        logger->logError(e.what());
        throw;
    }
