// Connection pool structure
typedef struct {
    int size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    void **connections;
} connection_pool;

// Create a new connection pool with the given size
connection_pool* create_connection_pool(int size) {
    connection_pool* pool = (connection_pool*)malloc(sizeof(connection_pool));
    pool->size = size;
    pthread_mutex_init(&pool->mutex, NULL);
    pthread_cond_init(&pool->cond, NULL);
    pool->connections = (void**)malloc(size * sizeof(void*));
    return pool;
}

// Acquire a connection from the pool
void* acquire_connection(connection_pool* pool) {
    void* conn = NULL;
    pthread_mutex_lock(&pool->mutex);
    for (int i = 0; i < pool->size; i++) {
        if (pool->connections[i] == NULL) {
            conn = pool->connections[i];
            break;
        }
    }
    if (conn == NULL) {
        // Create a new connection
        conn = malloc(sizeof(void*));
        pthread_cond_wait(&pool->cond, &pool->mutex);
        pthread_mutex_unlock(&pool->mutex);
        return conn;
    } else {
        pthread_mutex_unlock(&pool->mutex);
        return conn;
    }
}

// Release a connection back to the pool
void release_connection(connection_pool* pool, void* conn) {
    pthread_mutex_lock(&pool->mutex);
    for (int i = 0; i < pool->size; i++) {
        if (pool->connections[i] == NULL) {
            pool->connections[i] = conn;
            break;
        }
    }
    pthread_cond_signal(&pool->cond);
    pthread_mutex_unlock(&pool->mutex);
}

// Priority-based allocation strategy
int allocate_connection(connection_pool* pool, int priority) {
    for (int i = 0; i < pool->size; i++) {
        if (pool->connections[i] == NULL && priority > i) {
            return i;
        }
    }
    return -1;
}

