void processTransactionBatch(const std::vector<JSONLog>& logs, const std::string& connection_string,
                                std::shared_ptr<ServiceInterface> logging_service,
                                std::shared_ptr<ServiceInterface> auditing_service,
                                std::shared_ptr<ServiceInterface> notification_service) {
    // Create a map to store transaction states
    std::unordered_map<std::string, TransactionState> transaction_states;

    // Initialize the shared mutex
    std::shared_mutex lock;
    std::atomic<bool> is_processing(false);

    for (const auto& log : logs) {
        Transaction transaction;
        transaction.transaction_id = log["transaction_id"];
        transaction.amount = log["amount"];
        transaction.currency = log["currency"];
        transaction.timestamp = log["timestamp"];
        transaction.status = log["status"];

        // Validate transaction fields
        if (!validateTransaction(transaction)) {
            continue;  // Skip invalid transactions
        }

        try {
            // Process the transaction
            processTransaction(transaction);

            // Update the transaction state
            updateTransactionState(transaction_states, transaction.transaction_id);
        } catch (const std::exception& e) {
            // Log and audit the error
            logging_service->logError(e.what());
            auditing_service->auditError(e.what());
        }
    }

    // Defer notification to ensure all transactions are processed
    if (!is_processing.load()) {
        is_processing.store(true);
        try {
            // Send notifications for completed transactions
            notifyService(notification_service, transaction_states);
        } catch (const std::exception& e) {
            // Log and audit the error
            logging_service->logError(e.what());
            auditing_service->auditError(e.what());
        }
    }

    is_processing.store(false);  // Release the notification lock
}

