int persistRecords(int numRecords, int maxKey, int maxLength) {
    // Initialize database connection
    Database *db = db_connect();

    if (db == NULL) {
        return -1;  // Connection failed
    }

    // Create an array of Record structures
    Record **records = (Record **)malloc(numRecords * sizeof(Record *));
    for (int i = 0; i < numRecords; i++) {
        records[i] = (Record *)malloc(sizeof(Record));
        // Initialize key and offset values randomly
        records[i]->key = rand() % maxKey;
        records[i]->offset = (long)rand();
    }

    // Validate all records
    for (int i = 0; i < numRecords; i++) {
        if (!record_validate(records[i], maxLength)) {
            // Record validation failed, free and return error
            freeRecord(records[i]);
            free(records);
            db_disconnect(db);
            return -1;
        }
    }

    // Insert all records into the database
    for (int i = 0; i < numRecords; i++) {
        if (!db_insert_record(db, records[i])) {
            // Database insertion failed, roll back and free resources
            int j;
            for (j = i; j >= 0; j--) {
                db_delete_record(db, records[j]);
                freeRecord(records[j]);
            }
            free(records);
            db_disconnect(db);
            return -1;
        }
    }

    // Log the result and clean up
    printf("persistRecords: %d records persisted successfully\n", numRecords);

    // Clean up allocated resources
    for (int i = 0; i < numRecords; i++) {
        freeRecord(records[i]);
    }
    free(records);
    db_disconnect(db);

    return 0;
}
