class BatchProcessor {
public:
    BatchProcessor(size_t numThreads) : threads_(numThreads), queue_() {}

    void startProcessing(std::vector<std::string> imagePaths) {
        // Start processing threads
        for (size_t i = 0; i < numThreads_; ++i) {
            threads_.push([this, imagePaths]() {
                processImages(imagePaths);
            });
        }
    }

    void stopProcessing() {
        // Stop all threads
        for (auto& thread : threads_) {
            thread.join();
        }
    }

private:
    void processImages(const std::vector<std::string>& imagePaths) {
        for (const auto& imagePath : imagePaths) {
            try {
                // Ingest image from cloud storage
                cloudStorageLib::IngestImage(imagePath);

                // Extract metadata
                metadataExtractionLib::ExtractMetadata(imagePath);

                // Transform and store image
                cloudStorageLib::TransformAndStoreImage(imagePath);
            } catch (const std::exception& e) {
                // Handle errors
                LOG_ERROR("Error processing image: " << e.what());
            }
        }
    }

    std::vector<std::thread> threads_;
    std::queue<std::function<void()>> queue_;
};

