}

NasPdu* create_nas_pdu(int ue_index, Credentials* creds) {
    NasPdu* pdu = (NasPdu*)malloc(sizeof(NasPdu));
    // Generate random NAS UE info tag
    srand(ue_index);
    int i;
    for (i = 0; i < 16; i++) {
        pdu->nas_ue_info_tag[i] = (char)(rand() % 256);
    }
    pdu->rnti = ue_index;
    // Generate random NAS indication tag
    for (i = 0; i < 16; i++) {
        pdu->nas_indication_tag[i] = (char)(rand() % 256);
    }
    pdu->indication_flag = (rand() % 2) ? 1 : 0;
    return pdu;
}

void nas_pdu_free(NasPdu* pdu) {
    free(pdu);
}

int main() {
    Credentials creds;
    int ue_count = 5;

    // Initialize SSL context
    nas_pdu_init(&creds);

    for (int i = 0; i < ue_count; i++) {
        NasPdu* pdu = create_nas_pdu(i, &creds);
        // Use the NAS PDU structure as needed
        nas_pdu_free(pdu);
