#include <iostream>
#include <vector>
#include <string>
#include <random>
#include <fstream>

struct Record {
    int value;
    int* key;
    long* offset;
};

void processPipeline(int dataSize) {
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(1, 100);

    // Dynamic memory allocation for arrays
    auto* keys = new int[dataSize];
    auto* offsets = new long[dataSize];

    // Initialize arrays with random numbers
    for (int i = 0; i < dataSize; ++i) {
        keys[i] = dis(gen);
        offsets[i] = static_cast<long>(dis(gen));
    }

    // Allocate and initialize array of 'record' structures
    auto* records = new Record[dataSize];

    for (int i = 0; i < dataSize; ++i) {
        records[i].value = dis(gen);
        records[i].key = &keys[i];
        records[i].offset = &offsets[i];
    }

    // Serialize and persist data to file
    std::ofstream file("data.bin", std::ios::binary);
    if (!file) {
        std::cerr << "Error opening file for writing." << std::endl;
        return;
    }

    file.write((char*)records, dataSize * sizeof(Record));
    file.close();

    // Release dynamically allocated memory
    delete[] keys;
    delete[] offsets;
    delete[] records;
}

int main() {
    int dataSize = 1000; // Adjust this value based on your requirements
    processPipeline(dataSize);
    return 0;
}
