#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_PDU_SIZE 1024
#define TRANSMISSION_INTERVAL 100 // in milliseconds
#define RETRY_LIMIT 5

typedef struct {
    uint8_t rx_ue_info_tag;
    uint32_t rnti;
    uint16_t crc_indication_rel8_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t pdu_queue_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t pdu_queue_cond = PTHREAD_COND_INITIALIZER;
struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu_array;
    int array_size;
    pthread_mutex_t queue_lock;
    pthread_cond_t queue_cond;
} pdu_queue;

void init_and_transmit_pdus(NFAPI_CRC_INDICATION_PDU_T **pdus, int num_pdus) {
    // Initialize PDU structures
    for (int i = 0; i < num_pdus; i++) {
        pdus[i]->rx_ue_info_tag = rand() % 256;
        pdus[i]->rnti = rand();
        pdus[i]->crc_indication_rel8_tag = rand() % 65535;
        pdus[i]->crcflag = (rand() & 1) ? 0 : 1;
    }

    // Create a thread-safe queue for PDUs
    pthread_mutex_init(&pdu_queue.queue_lock, NULL);
    pthread_cond_init(&pdu_queue.queue_cond, NULL);
    pdu_queue.pdu_array = pdus;
    pdu_queue.array_size = num_pdus;

    // Initialize transmission variables
    int transmission_count = 0;
    struct timespec last_transmission_time = {0};
    pthread_mutex_init(&transmission_lock, NULL);

    while (1) {
        // Check if the API is healthy and ready for transmission
        if (!api_health_check()) {
            // Reconfigure or retry transmission attempts if API becomes unreliable
            reconfigure_or_retry();
        }

        // Monitor transmission metrics and log information
        transmission_count++;
        struct timespec current_time = {0};
        clock_gettime(CLOCK_REALTIME, &current_time);
        printf("Transmission %d: Timestamp=%ld, Status=%s\n", transmission_count, current_time.tv_sec, (transmission_count > 1) ? "success" : "failure");

        // Asynchronously transmit PDUs using the external API
        pthread_mutex_lock(&pdu_queue.queue_lock);
        NFAPI_CRC_INDICATION_PDU_T *pdu = pdu_queue.pdu_array;
        for (int i = 0; i < pdu_queue.array_size; i++) {
            if (transmit_pdu(pdu[i])) {
                break; // Transmission successful
            }
            pdu++;
        }
        pthread_mutex_unlock(&pdu_queue.queue_lock);

        // Sleep until the next transmission interval
        struct timespec sleep_time = {TRANSMISSION_INTERVAL / 1000, (TRANSMISSION_INTERVAL % 1000) * 1000000};
        nanosleep(&sleep_time, NULL);
    }
}

int transmit_pdu(NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Asynchronous transmission using the external API
    int status = api_transmit_pdu(&pdu);
    if (status == -1) {
        // Handle API errors and retries
        int retry_count = 0;
        while (retry_count < RETRY_LIMIT && status == -1) {
            sleep(TRANSMISSION_INTERVAL / 1000); // wait for transmission interval
            status = api_transmit_pdu(&pdu);
            retry_count++;
        }
    }
    return status;
}

int api_health_check() {
    // Check API health and availability
    int status = api_query_status();
    if (status == -1) {
        // Reconfigure or retry transmission attempts if API becomes unreliable
        reconfigure_or_retry();
    }
    return status;
}

void reconfigure_or_retry() {
    // Reconfigure transmission settings or retry transmission attempts
    pthread_mutex_lock(&transmission_lock);
    transmission_count = 0; // reset transmission count
    pthread_mutex_unlock(&transmission_lock);
}
