    NFAPI_CRC_INDICATION_PDU_T* pdus[CACHED_RECORDS];
    int size;
};

void init_and_transmit_pdus(int num_pdas, NFAPI_CRC_INDICATION_PDU_T* pdas) {
    pthread_t transmitter_thread;
    pthread_create(&transmitter_thread, NULL, transmit_pdus_async, (void*)pdas);
}

void* transmit_pdus_async(void* data) {
    NFAPI_CRC_INDICATION_PDU_T* pdas = (NFAPI_CRC_INDICATION_PDU_T*)data;
    int i, retry_count = 0;

    while(i < num_pdas && retry_count <= RETRY_LIMIT) {
        pthread_mutex_lock(&queue_lock);
        for(int j = 0; j < MAX_PACKET_SIZE && i < num_pdas; j++) {
            pdus_transmitted++;
            // transmit pdu here
        }
        pthread_mutex_unlock(&queue_lock);

        if(pdus_transmitted < num_pdas) {
            usleep(TRANSMISSION_INTERVAL);
            retry_count++;
        } else {
            break;
        }
    }

    return NULL;
}

void* async_transmission_handler(void* data) {
