    size_t capacity;               // Capacity of the array
    size_t size;                   // Current size of the array
} CellMeasurements;

// Function to initialize and manage the dynamic collection of cell measurements
void init_cell_measurements(CellMeasurements* cm, int capacity) {
    cm->measurements = (CellMeasurement*)malloc(capacity * sizeof(CellMeasurement));
    cm->capacity = capacity;
    cm->size = 0;
}

// Function to add a new cell measurement to the dynamic collection
int add_measurement(CellMeasurements* cm, int cell_id, float signal_strength) {
    if (cm->size >= cm->capacity) {
        // Double the capacity if the array is full
        cm->measurements = (CellMeasurement*)realloc(cm->measurements, 2 * cm->capacity * sizeof(CellMeasurement));
        cm->capacity *= 2;
    }
    cm->measurements[cm->size].cell_id = cell_id;
    cm->measurements[cm->size].signal_strength = signal_strength;
    cm->measurements[cm->size].timestamp = time(NULL);
    return ++(cm->size);
}

// Function to filter out measurements below a user-defined confidence threshold
void filter_measurements(CellMeasurements* cm, float threshold) {
    for (int i = 0; i < cm->size; i++) {
        if (cm->measurements[i].signal_strength < threshold) {
            // Shift the remaining elements and reset size
            memmove(&cm->measurements[i], &cm->measurements[i + 1], (cm->size - i - 1) * sizeof(CellMeasurement));
            cm->size--;
            i--; // Decrement i to re-check the current element
