#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_CELL_MEASUREMENTS 10000
#define MAX_SIGNAL_STRENGTH 127
#define MAX_LOCATION_COORDINATES 4
#define MAX_METADATA 256

typedef struct {
    int id;
    int signal_strength;
    time_t timestamp;
    double location_coordinates[MAX_LOCATION_COORDINATES];
    char metadata[MAX_METADATA];
} CellMeasurement;

// Library data structure to manage cell measurements
typedef struct {
    CellMeasurement *measurements;
    size_t num_measurements;
    pthread_mutex_t lock;
} MeasurementCollection;

// Initialize measurement collection
void init_measurement_collection(MeasurementCollection *collection) {
    collection->measurements = (CellMeasurement *)malloc(MAX_CELL_MEASUREMENTS * sizeof(CellMeasurement));
    collection->num_measurements = 0;
    pthread_mutex_init(&collection->lock, NULL);
}

// Add cell measurement to the collection
void add_cell_measurement(MeasurementCollection *collection, CellMeasurement measurement) {
    pthread_mutex_lock(&collection->lock);
    if (collection->num_measurements < MAX_CELL_MEASUREMENTS) {
        memcpy(&collection->measurements[collection->num_measurements], &measurement, sizeof(CellMeasurement));
        collection->num_measurements++;
    }
    pthread_mutex_unlock(&collection->lock);
}

// Filter measurements based on signal strength
void filter_signal_strength(MeasurementCollection *collection, int threshold) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->num_measurements; i++) {
        if (collection->measurements[i].signal_strength < threshold) {
            // Remove measurement from the collection
            memmove(&collection->measurements[i], &collection->measurements[i + 1], sizeof(CellMeasurement) * (collection->num_measurements - i - 1));
            collection->num_measurements--;
        }
    }
    pthread_mutex_unlock(&collection->lock);
}

// Range query based on time and location
void range_query(MeasurementCollection *collection, time_t start_time, double min_location, double max_location) {
    pthread_mutex_lock(&collection->lock);
    for (size_t i = 0; i < collection->num_measurements; i++) {
        if (collection->measurements[i].timestamp >= start_time && 
            collection->measurements[i].location_coordinates[0] >= min_location &&
            collection->measurements[i].location_coordinates[0] <= max_location) {
            // Return the measurement
            printf("Timestamp: %ld, Location Coordinates: %f, Signal Strength: %d\n",
                   (long int)collection->measurements[i].timestamp,
                   collection->measurements[i].location_coordinates[0],
                   collection->measurements[i].signal_strength);
        }
    }
    pthread_mutex_unlock(&collection->lock);
}

int main() {
    MeasurementCollection measurement_collection;
    init_measurement_collection(&measurement_collection);

    // Add cell measurements to the collection
    CellMeasurement measurement1 = {1, 90, time(NULL), {40.7128, -74.0060}, "Metadata"};
    add_cell_measurement(&measurement_collection, measurement1);
    CellMeasurement measurement2 = {2, 80, time(NULL) + 10, {40.7129, -74.0059}, "Metadata"};
    add_cell_measurement(&measurement_collection, measurement2);

    // Filter measurements based on signal strength
    int threshold = 85;
    filter_signal_strength(&measurement_collection, threshold);

    // Range query based on time and location
    time_t start_time = time(NULL) - 30;
    double min_location = 40.7125;
    double max_location = 40.7130;
    range_query(&measurement_collection, start_time, min_location, max_location);

    return 0;
}

