        match pair.as_rule() {
            // Handle different grammar rules
            "start" => {
                let func = builder.create_function("main", ctx.get_type_void());
                println!("Generated LLVM IR code: {}", func);
            }
            _ => println!("Not implemented yet"),
        }
    }

    format!("{:?}", module)
}
