#define MAX_ARRAY_SIZE 10000
#define NFAPI_CRC_INDICATION_PDU_T_COUNT 5

typedef struct {
    uint32_t rnti;
    uint8_t flags[4];
} NFAPI_CRC_INDICATION_PDU_T;

void* generateNfarcrcIndications(void* arg) {
    int array_size = *(int*)arg;
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(array_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    for(int i = 0; i < array_size; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &array[i];

        pthread_mutex_lock(&lock);
        pdu->rnti = (uint32_t)rand();
        for(int j = 0; j < NFAPI_CRC_INDICATION_PDU_T_COUNT; j++) {
            pdu->flags[j] = (uint8_t)rand() % 2;
        }
        pthread_mutex_unlock(&lock);
    }

    free(array);

    return NULL;
}

int generateNfarcrcIndicationsThreaded(int array_size, NFAPI_CRC_INDICATION_PDU_T* result_array[]) {
    pthread_t threads[MAX_ARRAY_SIZE / PTHREAD_SCOPE_PROCESS];
    int thread_count = array_size / PTHREAD_SCOPE_PROCESS + 1;

    for(int i = 0; i < thread_count; i++) {
        pthread_create(&threads[i], NULL, generateNfarcrcIndications, &array_size);
    }

    for(int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    *result_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(array_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    return 0;
}

int main() {
    srand(time(NULL));

    int array_size = 10000;
    NFAPI_CRC_INDICATION_PDU_T* result_array;

