package com.example.resourcemanagement;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import javax.persistence.EntityManager;
import javax.persistence.PersistenceContext;
import java.util.List;
import java.util.Optional;

@RestController
@RequestMapping("/resources")
public class ResourceController {

    @PersistenceContext
    private EntityManager entityManager;

    private final ObjectMapper mapper = new ObjectMapper();

    @GetMapping
    public ResponseEntity<List<Resource>> getResources() {
        List<Resource> resources = entityManager.createQuery("SELECT r FROM Resource r", Resource.class).getResultList();
        return new ResponseEntity<>(resources, HttpStatus.OK);
    }

    @GetMapping("/{id}")
    public ResponseEntity<Optional<Resource>> getResource(@PathVariable Long id) {
        Optional<Resource> resource = entityManager.createQuery("SELECT r FROM Resource r WHERE r.id = :id", Resource.class)
                .setParameter("id", id).getResultList().stream().findFirst();
        return new ResponseEntity<>(resource, HttpStatus.OK);
    }

    @PostMapping
    public ResponseEntity<HttpStatus> createResource(@RequestBody Resource resource) {
        entityManager.persist(resource);
        return new ResponseEntity<>(HttpStatus.CREATED);
    }

    @PutMapping("/{id}")
    public ResponseEntity<HttpStatus> updateResource(@PathVariable Long id, @RequestBody Resource updatedResource) {
        Optional<Resource> existingResource = entityManager.createQuery("SELECT r FROM Resource r WHERE r.id = :id", Resource.class)
                .setParameter("id", id).getResultList().stream().findFirst();
        if (existingResource.isPresent()) {
            Resource resourceToUpdate = existingResource.get();
            // Compute MD5 hash of updated resource
            String md5Hash = computeMD5Hash(updatedResource);
            // Update database record with new data and MD5 hash
            entityManager.createQuery("UPDATE Resource r SET r.data = :data, r.md5Hash = :md5 WHERE r.id = :id")
                    .setParameter("data", updatedResource.getData())
                    .setParameter("md5", md5Hash)
                    .setParameter("id", id).executeUpdate();
            return new ResponseEntity<>(HttpStatus.NO_CONTENT);
        } else {
            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
        }
    }

    @DeleteMapping("/{id}")
    public ResponseEntity<HttpStatus> deleteResource(@PathVariable Long id) {
        entityManager.createQuery("DELETE FROM Resource r WHERE r.id = :id")
                .setParameter("id", id).executeUpdate();
        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
