public class CommandExecutor {
    private final File deletionTargetFile;
    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final Gson gson = new Gson();

    public CommandExecutor(String deletionTargetFilePath) throws IOException {
        this.deletionTargetFile = new File(deletionTargetFilePath);
    }

    public void executeCommand(Command command, Logger logger) {
        // 1. Automatically detect and delete the file if it exists
        if (deletionTargetFile.exists() && !deletionTargetFile.delete()) {
            logger.error("Failed to delete target file: " + deletionTargetFile.getName());
        }

        // 2. Execute the command asynchronously, capturing both standard output and error streams for logging
        executor.submit(() -> {
            try (Process process = Runtime.getRuntime().exec(command.getCommand())) {
                BufferedReader stdInput = new BufferedReader(new InputStreamReader(process.getInputStream()));
                StringBuilder outputBuilder = new StringBuilder();
                String line;
                while ((line = stdInput.readLine()) != null) {
                    outputBuilder.append(line).append("\n");
                }
                logger.info("Command output: " + outputBuilder.toString());

                BufferedReader stdError = new BufferedReader(new InputStreamReader(process.getErrorStream()));
                StringBuilder errorBuilder = new StringBuilder();
                while ((line = stdError.readLine()) != null) {
                    errorBuilder.append(line).append("\n");
                }
                logger.error("Command error: " + errorBuilder.toString());
            } catch (IOException e) {
                logger.error("Failed to execute command: " + command.getCommand(), e);
            }
        });
    }

    public void logExecution(Command command, int exitStatus, long executionTime) {
        // 3. Handle potential security vulnerabilities by sanitizing inputs and validating command parameters
        String sanitizedCommand = sanitizeCommand(command.getCommand());
        logger.info("Executed command: " + sanitizedCommand);

        // 4. Integrate with an external API or database to persist execution logs for future analysis and auditing
        Map<String, Object> logEntry = new HashMap<>();
        logEntry.put("command", sanitizedCommand);
        logEntry.put("exitStatus", exitStatus);
        logEntry.put("executionTime", executionTime);
        logger.info(gson.toJson(logEntry));
    }

    public void shutdown() {
        // 5. Optimize for performance, ensuring efficient handling of large data volumes and long-running processes
        executor.shutdown();
    }

    private String sanitizeCommand(String command) {
        // Implement your sanitization logic here
        return command;
    }
}

class Command {
    private final String command;

    public Command(String command) {
        this.command = command;
    }

    public String getCommand() {
        return command;
    }
}

interface Logger {
    void error(String message);

    void info(String message);
}
