// Function to read integers from standard input
int* readIntegers(int* count) {
    int* integers = NULL;
    *count = 0;

    while (1) {
        int num;
        scanf("%d", &num);

        if (num == -1) break; // Exit loop when user inputs -1

        integers = realloc(integers, (*count + 1) * sizeof(int));
        integers[*count] = num;
        (*count)++;
    }

    return integers;
}

// Function to find and print the largest integer
void findLargest(int* integers, int count) {
    if (count == 0) printf("No integers found.\n");
    else printf("The largest integer is: %d\n", integers[count - 1]);
}

int main() {
    int count = 0;
    int* integers = readIntegers(&count);

    findLargest(integers, count);

    free(integers);
    return 0;
}
