        producer_thread_ = std::thread([this] { this->produce(); });
    }

    void stop() {
        running_ = false;
        producer_thread_.join();
    }

private:
    void produce() {
        while (running_) {
            int value = fetch_value();
            if (!queue_->empty()) {
                int old_value = queue_->front();
                queue_->pop();
                std::cout << "Produced value: " << value << ", Consumed value: " << old_value << "\n";
            }
            else {
                std::cout << "Queue is empty. No values consumed.\n";
            }
            if (value != -1) {
                enqueue(value);
            }
            else {
                break;
            }
        }
    }

    int fetch_value() {
