import asyncio
import json
from typing import Dict, List

class MessageBroker:
    def __init__(self):
        self.messages: List[Dict] = []
        self.consumers: Dict[str, List[asyncio.coroutine]] = {}
        self.producers: Dict[str, asyncio.Queue] = {}
        self.config: Dict[str, str] = {'queue_size': '1000', 'max_concurrent_consumers': '5'}

    async def produce(self, message: Dict):
        producer_name = message['producer']
        if producer_name not in self.producers:
            self.producers[producer_name] = asyncio.Queue(maxsize=int(self.config['queue_size']))
        await self.producers[producer_name].put(message)

    async def consume(self, consumer_name: str):
        if consumer_name not in self.consumers:
            self.consumers[consumer_name] = []
        while True:
            try:
                message = await self.producers[consumer_name].get()
                await self.handle_message(consumer_name, message)
            except asyncio.QueueEmpty:
                pass

    async def handle_message(self, consumer_name: str, message: Dict):
        # Implement the business logic to process the message
        print(f'Consumed message from {consumer_name}: {message}')

    def run(self):
        for producer in self.producers:
            asyncio.create_task(self.consume(producer))
        while True:
            await asyncio.sleep(1)

if __name__ == '__main__':
    broker = MessageBroker()
    asyncio.run(broker.run())
