```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <semaphore.h>
#include <time.h>

#define BUFFER_SIZE 1000
#define MAX_RETRIES 5

// Message structure
typedef struct {
    int id;
    char* data;
} Message;

// Semaphore for buffer access
sem_t buffer_sem;
//Semaphore for message operations (enqueuing/dequeuing)
sem_t operation_sem;

// Buffer for storing messages
Message* buffer[BUFFER_SIZE];
int buffer_head = 0;
int buffer_tail = 0;

// Retry counter for failed message operations
int retries = 0;

// Function to enqueue a message in the buffer
void enqueue_message(Message* msg) {
    sem_wait(&buffer_sem);
    // Check if buffer is full before enqueuing
    if ((buffer_head + 1) % BUFFER_SIZE == buffer_tail) {
        // If buffer is full, wait until an item is dequeued or the buffer is resized
        while (buffer_head + 1 == buffer_tail) {
            sem_wait(&operation_sem);
        }
    }
    buffer[buffer_head] = msg;
    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    sem_post(&buffer_sem);
}

// Function to dequeue a message from the buffer
Message* dequeue_message() {
    Message* msg = NULL;
    sem_wait(&buffer_sem);
    // Check if the buffer is empty before dequeuing
    if (buffer_head == buffer_tail) {
        // If buffer is empty, wait until an item is enqueued or the buffer is resized
        while (buffer_head == buffer_tail) {
            sem_wait(&operation_sem);
        }
    } else {
        msg = buffer[buffer_tail];
        buffer_tail = (buffer_tail + 1) % BUFFER_SIZE;
    }
    sem_post(&buffer_sem);
    return msg;
}

// Function to retry failed message operations
void retry_operation(int retries) {
    // Implement your retry logic here
    printf("Message operation failed. Retrying...\n");
    if (retries < MAX_RETRIES) {
        // Perform the operation again after a delay
        sleep(1);
        retry_operation(retries + 1);
    } else {
        // Log a warning and give up after max retries
        printf("Failed to perform message operation after %d retries. Logging a warning.\n", retries);
    }
}

int main() {
    // Initialize semaphores and buffer
    sem_init(&buffer_sem, 0, BUFFER_SIZE);
    sem_init(&operation_sem, 0, 1);

    while (1) {
        Message* msg = dequeue_message();
        if (msg != NULL) {
            // Process the dequeued message here
            printf("Message received: %d\n", msg->id);
            free(msg->data);
            free(msg);
        } else {
            // Handle buffer empty or error
            printf("Error receiving message.\n");
            retry_operation(retries);
            retries = 0;
        }
    }

    return 0;
}
```

This code provides a basic framework for implementing a thread-safe, high-performance message handling system in C. It includes mechanisms for buffering messages, managing concurrency with semaphores, and retrying failed message operations. The code also provides logging for debugging and monitoring purposes.']

