extern crate rand;
use rand::Rng;
use std::sync::{Arc, Mutex};
use std::thread;

struct RandomNumberGenerator {
    seed: Arc<Mutex<u32>>,
}

impl RandomNumberGenerator {
    fn new(seed: Option<u32>) -> Self {
        let mut rng = Self {
            seed: Arc::new(Mutex::new(0)),
        };

        if let Some(s) = seed {
            *rng.seed.lock() = s;
        }

        rng
    }

    fn generate(&self, num: u32) -> Vec<u32> {
        let mut rng = rand::thread_rng();
        let mut result = Vec::with_capacity(num as usize);

        for _ in 0..num {
            *result.last_mut().unwrap() = rng.gen::<u32>();
        }

        result
    }
}

fn main() {
    let seed = 42;
    let mut generator = RandomNumberGenerator::new(Some(seed));
    let random_numbers = generator.generate(10);
}
