#include <iostream>
#include <map>
#include <memory>
#include <set>
#include <queue>
#include <functional>

namespace StateMachine {
    class Transition {
    public:
        enum class EventType { ENTER, EXIT };
        using EventCallback = std::function<void(EventType)>;

        Transition(const std::string& from, const std::string& to, 
                   const EventCallback& onEnter, const EventCallback& onExit)
            : from_(from), to_(to), onEnter_(onEnter), onExit_(onExit) {}

        const std::string& from() const { return from_; }
        const std::string& to() const { return to_; }

    private:
        std::string from_;
        std::string to_;
        EventCallback onEnter_;
        EventCallback onExit_;
    };

    class State {
    public:
        using Id = std::size_t;
        using TransitionMap = std::map<Id, Transition>;

        State(Id id) : id_(id), transitions_() {}

        void addTransition(Transition transition) {
            transitions_.emplace(transition.from(), transition);
        }

        void onEnter(Id stateId) const {
            if (!transitions_.empty()) {
                for (const auto& t : transitions_) {
                    if (t.first == stateId) {
                        t.second.onEnter_(Transition::EventType::ENTER);
                        return;
                    }
                }
            }
        }

        void onExit(Id stateId) const {
            if (!transitions_.empty()) {
                for (const auto& t : transitions_) {
                    if (t.first == stateId) {
                        t.second.onExit_(Transition::EventType::EXIT);
                        return;
                    }
                }
            }
        }

    private:
        Id id_;
        TransitionMap transitions_;
    };

    class Machine {
    public:
        using StatePtr = std::shared_ptr<State>;
        using TransitionQueue = std::queue<Transition>;

        Machine() : state_(nullptr), queue_() {}

        void addState(StatePtr state) { states_.emplace(state->id(), state); }
        void addTransition(Transition transition) {
            for (auto& s : states_) {
                if (s.second->addTransition(transition)) {
                    queue_.push(transition);
                    return;
                }
            }
        }

        void run() {
            while (!queue_.empty()) {
                Transition t = queue_.front();
                queue_.pop();
                state_->onExit(t.from());
                state_ = states_[t.to()];
                state_->onEnter(t.to());
            }
        }

    private:
        std::map<Id, StatePtr> states_;
        StatePtr state_;
        TransitionQueue queue_;
    };
}
```']

