const fs = require('fs');
const path = require('path');
const xml2js = require('xml2js');
const csvtojson = require('csvtojson');
const jsonfile = require('jsonfile');

// Define the root directory to monitor and process files from
const rootDir = '/path/to/monitor';

// Function to process a single file based on its type
async function processFile(filePath) {
  const fileExt = path.extname(filePath);

  if (fileExt === '.json') {
    try {
      const jsonData = jsonfile.readFileSync(filePath, 'utf8');
      // Process JSON data here
    } catch (err) {
      console.error(err);
    }
  } else if (fileExt === '.csv') {
    try {
      const csvData = await csvtojson().fromFile(filePath);
      // Process CSV data here
    } catch (err) {
      console.error(err);
    }
  } else if (fileExt === '.xml') {
    try {
      const xmlData = await xml2js.parseString(fs.readFileSync(filePath, 'utf8'));
      // Process XML data here
    } catch (err) {
      console.error(err);
    }
  }
}

// Function to monitor the directory for changes and process new files
async function monitorDirectory() {
  fs.watch(rootDir, (eventType, filename) => {
    if (filename) {
      const filePath = path.join(rootDir, filename);

      // Process the file asynchronously to avoid blocking
      processFile(filePath).catch((err) => console.error(err));
    }
  });
}

// Start monitoring the directory for changes
monitorDirectory();
