// Define the structure for dynamic UID generation
typedef struct {
    char prefix[16]; // customizable prefix
    int timestamp;   // current timestamp
    uint64_t content_hash; // content hash of the data
} DynamicUID;

// Function to generate a unique document identifier (UID)
DynamicUID* generate_UID(char* data, size_t length) {
    DynamicUID* uid = malloc(sizeof(DynamicUID));

    // Set the prefix
    strcpy(uid->prefix, "dynamic-uid-");

    // Get the current timestamp
    uid->timestamp = time(NULL);

    // Calculate the content hash
    uint64_t hash = 0;
    for (size_t i = 0; i < length; i++) {
        hash += data[i];
    }
    uid->content_hash = hash;

    return uid;
}

// Function to resolve DNS and get IP address
