// Thread-safe, scalable function to initialize and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu_array(size_t n) {
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!array) {
        // Handle memory allocation failure
        return NULL;
    }

    uint8_t tag_counter = 0;
    for (size_t i = 0; i < n; ++i) {
        array[i].RX_UE_INFORMATION_TAG = tag_counter++;
        array[i].RNTI = rand() % 65535 + 1; // Randomly generated RNTI
        array[i].CRC_INDICATION_REL8_TAG.crc_flag = (rand() & 0x01); // Randomly generated CRC flag

        if (i > 0) {
            // Check for duplicate RX_UE_INFORMATION_TAG or RNTI
            bool found_duplicate = false;
            for (size_t j = 0; j < i; ++j) {
                if ((array[i].RX_UE_INFORMATION_TAG == array[j].RX_UE_INFORMATION_TAG || 
                     array[i].RNTI == array[j].RNTI)) {
                    found_duplicate = true;
                    break;
                }
            }

            if (found_duplicate) {
                // Handle duplicate identifier
                i--;
                continue; // Retry allocation
            }
        }
    }

    return array;
}
