  let attemptCount = 0;
  return () => {
    try {
      return fn();
    } catch (error) {
      if (attemptCount < maxAttempts) {
        attemptCount++;
        setTimeout(() => {
          retryOnFailure(fn, maxAttempts)(());
        }, 500);
      } else {
        console.error('Max attempts reached. Giving up.');
      }
    }
  };
}

