        self.file_lock = Lock()
        self.condition = Condition()

    def add_datacenter(self, datacenter_id: str) -> None:
        if datacenter_id not in self.datacenters:
            self.datacenters[datacenter_id] = {
                'files': {},
                'replication_factor': 3,
                'replicas': {}
            }
        else:
            print("Data center already exists")

    def put_file(self, file_name: str, file_contents: bytes) -> None:
        datacenter_id = random.choice(list(self.datacenters.keys()))
        with self.file_lock:
            if file_name not in self.datacenters[datacenter_id]['files']:
                self.datacenters[datacenter_id]['files'][file_name] = {'contents': file_contents}
                for i in range(self.datacenters[datacenter_id]['replication_factor']):
                    replica_datacenter_id = random.choice(list(self.datacenters.keys()))
                    while replica_datacenter_id == datacenter_id:
                        replica_datacenter_id = random.choice(list(self.datacenters.keys()))
                    self.datacenters[replica_datacenter_id]['replicas'][file_name] = file_contents
            else:
                print("File already exists")

    def get_file(self, file_name: str) -> bytes:
        with self.condition:
            datacenter_id = random.choice(list(self.datacenters.keys()))
            if file_name in self.datacenters[datacenter_id]['files']:
                return self.datacenters[datacenter_id]['files'][file_name]['contents']
            for replica_datacenter_id in self.datacenters.values():
                if file_name in replica_datacenter_id['replicas']:
                    return replica_datacenter_id['replicas'][file_name]
        return None

    def list_files(self) -> List[str]:
        with self.condition:
            files = []
            for datacenter_id in self.datacenters:
                for file_name in self.datacenters[datacenter_id]['files'].keys():
                    if file_name not in files:
                        files.append(file_name)
            return files

if __name__ == '__main__':
    dfs = DistributedFileStorage()
    dfs.add_datacenter('dc1')
    dfs.put_file('file1.txt', b'Hello, world!')
    dfs.put_file('file2.txt', b'Goodbye, world!')
    print(dfs.list_files())
    print(dfs.get_file('file1.txt'))
```']

