using System;
using System.Security.Cryptography;

public static string DecryptMessage(string encryptedMessage, string key, string iv)
{
    byte[] encryptedBytes = Convert.FromBase64String(encryptedMessage);
    TripleDESCryptoServiceProvider cryptoServiceProvider = new TripleDESCryptoServiceProvider();
    cryptoServiceProvider.Key = Convert.FromBase64String(key);
    cryptoServiceProvider.IV = Convert.FromBase64String(iv);

    MemoryStream memoryStream = new MemoryStream(encryptedBytes);
    CryptoStream cryptoStream = new CryptoStream(memoryStream, cryptoServiceProvider.CreateDecryptor(), CryptoStreamMode.Read);

    byte[] decryptedBytes = new byte[cryptoStream.Length];
    cryptoStream.Read(decryptedBytes, 0, decryptedBytes.Length);

    return Encoding.UTF8.GetString(decryptedBytes);
}
