    this.client = new CloudWatch({
      region: config.region,
      accessKeyId: config.accessKeyId,
      secretAccessKey: config.secretAccessKey
    });

    for (const metric of this.metrics) {
      this.client.register(metric.metric, metric.namespace);
    }
  }
}
