use log::{info, error};
use std::collections::HashMap;
use std::fs::File;
use std::io::{BufReader, BufRead};
use std::path::Path;
use std::process::{exit, Command};

// Define a struct to store compilation information
struct CompilationResult {
    time: f64,
    memory_usage: usize,
    errors: Vec<String>,
}

// Create a new instance of the compiler
fn compile(crate_path: &str) -> CompilationResult {
    // Initialize variables for compilation results
    let mut time = 0.0;
    let mut memory_usage = 0;
    let mut errors = vec![];

    // Compile the crate using rustc
    match Command::new("rustc")
        .arg("-Ztime-passes=1")
        .arg("--emit=llvm-ir")
        .arg(crate_path)
        .output()
    {
        Ok(result) => {
            time = result.duration.as_secs() as f64;
            memory_usage = result.memory_used;
        }
        Err(err) => error!("Error compiling crate: {}", err),
    }

    // Parse the compilation output to get errors
    match File::open(crate_path)
    .and_then(|file| BufReader::new(file).lines())
    .flatten()
    {
        Some(line) => {
            if line.contains("error") {
                errors.push(line.to_string());
            }
        }
        None => {}
    }

    CompilationResult { time, memory_usage, errors }
}

// Main function for compiling and configuring crates
fn main() {
    // Initialize a hashmap to store compilation results
    let mut compilation_results = HashMap::new();

    // Compile each crate in the directory
    std::fs::read_dir(".")
        .unwrap()
        .flatten()
        .filter_map(|e| e.ok())
        .filter(|p| p.file_name().unwrap().to_string_lossy().ends_with("rs"))
        .for_each(|crate_path| {
            let result = compile(crate_path.path().to_str().unwrap());
            compilation_results.insert(crate_path.path().to_str().unwrap().to_string(), result);
        });

    // Print the compilation results
    for (crate_path, result) in &compilation_results {
        info!("Compilation results for {}: {:?}", crate_path, result);
    }
}
