```cpp
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <atomic>
#include <map>
#include <queue>
#include <algorithm>

class Node {
public:
    int key;
    std::vector<int> children;
};

class KDTree {
private:
    Node* root;
    std::mutex mtx;
    std::atomic<bool> is_root_deleted(false);

public:
    KDTree() : root(nullptr) {}

    ~KDTree() {
        deleteRecursive(root);
    }

    void insert(int key) {
        root = insertRecursive(root, key, 0);
    }

    void erase(int key) {
        root = eraseRecursive(root, key, 0);
    }

    int queryRange(int minX, int minY, int maxX, int maxY) {
        return queryRecursive(root, minX, minY, maxX, maxY, 0).size();
    }

private:
    Node* insertRecursive(Node* node, int key, int axis) {
        if (node == nullptr) {
            node = new Node;
            node->key = key;
            return node;
        }

        int compareResult = compare(key, node->key, axis);

        if (compareResult > 0) {
            if (node->children.empty()) {
                node->children.push_back(new Node);
            }
            return insertRecursive(node->children.back(), key, (axis + 1) % 2);
        } else {
            if (node->children.empty()) {
                node->children.push_back(new Node);
            }
            return insertRecursive(node->children.front(), key, (axis + 1) % 2);
        }
    }

    Node* eraseRecursive(Node* node, int key, int axis) {
        if (node == nullptr) {
            return node;
        }

        int compareResult = compare(key, node->key, axis);

        if (compareResult > 0) {
            node->children.erase(node->children.begin());
            return eraseRecursive(node->children.empty() ? nullptr : node->children.front(), key, (axis + 1) % 2);
        } else if (compareResult < 0) {
            node->children.pop_back();
            return eraseRecursive(node->children.empty() ? nullptr : node->children.back(), key, (axis + 1) % 2);
        } else {
            delete node;
            return nullptr;
        }
    }

    std::vector<int> queryRecursive(Node* node, int minX, int minY, int maxX, int maxY, int axis) {
        if (node == nullptr) {
            return {};
        }

        int compareResult = compare(minX, node->key, axis);

        if (compareResult > 0 || (compareResult == 0 && (axis % 2) != (node->children.empty() ? 0 : 1))) {
            return queryRecursive(node->children.empty() ? nullptr : node->children.front(), minX, minY, maxX, maxY, (axis + 1) % 2);
        } else if (compareResult < 0 || (compareResult == 0 && (axis % 2) != (node->children.size() - 1))) {
            return queryRecursive(node->children.empty() ? nullptr : node->children.back(), minX, minY, maxX, maxY, (axis + 1) % 2);
        } else {
            int result = 0;
            for (auto child : node->children) {
                if (compare(minX, child->key, axis) > 0 || compare(minY, child->key, axis) > 0) {
                    result += queryRecursive(child, minX, minY, maxX, maxY, (axis + 1) % 2).size();
                } else if (compare(minX, child->key, axis) < 0 || compare(minY, child->key, axis) < 0) {
                    result += queryRecursive(child, minX, minY, maxX, maxY, (axis + 1) % 2).size();
                } else {
                    for (auto& children : child->children) {
                        if (compare(minX, children->key, axis) > 0 || compare(minY, children->key, axis) > 0) {
                            result += queryRecursive(children, minX, minY, maxX, maxY, (axis + 1) % 2).size();
                        } else if (compare(minX, children->key, axis) < 0 || compare(minY, children->key, axis) < 0) {
                            result += queryRecursive(children, minX, minY, maxX, maxY, (axis + 1) % 2).size();
                        }
                    }
                }
            }
            return {result};
        }
    }

private:
    int compare(int a, int b, int axis) {
        if (axis == 0) {
            return a - b;
        } else {
            return a - b;
        }
    }

    void deleteRecursive(Node* node) {
        if (node == nullptr) {
            return;
        }

        for (auto child : node->children) {
            deleteRecursive(child);
        }
        delete node;
    }
};

int main() {
    KDTree tree;

    // Insert nodes
    tree.insert(5);
    tree.insert(10);
    tree.insert(15);

    // Query range
    int result = tree.queryRange(0, 0, 10, 10);

    return 0;
}
```

