class networkDataFetcher {
public:
    networkDataFetcher(std::shared_ptr<WebSocket> ws) : _ws(ws), _cache() {}

    void fetch(const std::string& url, const std::function<void(std::vector<char>)>& callback) {
        _ws->send(url);
        _ws->receive([this, &callback](std::vector<char> data) {
            _cache[url] = data;
            callback(data);
        });
    }

    void fetchAndCache(const std::string& url) {
        _ws->send(url);
        _ws->receive([this](std::vector<char> data) {
            _cache[url] = data;
        });
    }

    void get(const std::string& url, const std::function<void(std::vector<char>)>& callback) {
        if (_cache.count(url)) {
            callback(_cache[url]);
        } else {
            _ws->send(url);
            _ws->receive([this, &callback](std::vector<char> data) {
                _cache[url] = data;
                callback(data);
            });
        }
    }

private:
    std::shared_ptr<WebSocket> _ws;
    std::unordered_map<std::string, std::vector<char>> _cache;

    std::mutex _lock;
    std::condition_variable _cond;

    void updateCache(const std::string& url, const std::vector<char>& data) {
        std::unique_lock<std::mutex> lock(_lock);
        _cache[url] = data;
        lock.unlock();
        _cond.notify_all();
    }
};

class WebSocket {
public:
    virtual ~WebSocket() {}
    virtual void send(const std::string& message) = 0;
    virtual void receive(std::function<void(std::vector<char>)>& callback) = 0;
};

