function recycleUnusedBitmaps(themeDir) {
  const bitmapFiles = fs.readdirSync(themeDir);
  for (const file of bitmapFiles) {
    if (!file.endsWith('.png')) continue;
    const filePath = path.join(themeDir, file);
    const bitmapData = fs.readFileSync(filePath);
    if (bitmapData.length < 1000) { // Threshold for unused bitmaps
      fs.writeFileSync(filePath, null); // Set to null and free memory
    }
  }
}

function setDefaultThemeDirectory() {
  const userConfig = getConfig();
  if (!userConfig.themeDir) {
    userConfig.themeDir = 'default-theme';
    saveConfig(userConfig);
  }
}

function parseAndCachePNG(themeDir, file) {
  const filePath = path.join(themeDir, file);
  const bitmapData = fs.readFileSync(filePath);
  caching.setBitmapCache(bitmapData);
}
