char* generate_guid(const char* document_content, const char* user_prefix) {
    // Calculate content hash using SHA-256
    uint8_t content_hash[SHA256_DIGEST_LENGTH];
    SHA256((uint8_t*)document_content, strlen(document_content), content_hash);

    // Get current timestamp
    time_t now = time(NULL);

    // Create GUID format string
    char guid_format_string[64];
    sprintf(guid_format_string, "%s%08x%lld%d", user_prefix, (uint32_t)content_hash[0], (long long)now, (int)os_getpid());

