    uint8_t guid[SHA256_DIGEST_LENGTH];
    SHA256((uint8_t*)guid_format_string, strlen(guid_format_string), guid);

    char* guid_str = malloc(GUID_LENGTH + 1);
    sprintf(guid_str, "%02x%02x%02x%02x%02x%02x%02x%02x", guid[0], guid[1], guid[2], guid[3], guid[4], guid[5], guid[6], guid[7]);

    return guid_str;
}

