import boto3
from kafka import KafkaProducer
from logstash import *
from elasticsearch import Elasticsearch
from flask import Flask, request, jsonify
from celery import Celery

app = Flask(__name__)
app.config['ES_INDEX'] = 'logs'

# Configure ES connection
es = Elasticsearch(hosts=['localhost:9200'])

# Define a simple logging function that sends logs to ELK stack
def log_event(event):
    try:
        es.index(index='logs', body=event)
    except Exception as e:
        print(f"Error indexing log event: {e}")

# Configure Kafka producer for off-peak log processing
kafka_producer = KafkaProducer(bootstrap_servers=['localhost:9092'])

# Define a Celery task for processing non-critical logs asynchronously
@Celery.task()
def process_non_critical_logs(logs):
    # Process logs in batches to avoid overwhelming the system
    batch_size = 1000
    log_batches = [logs[i:i+batch_size] for i in range(0, len(logs), batch_size)]

    for batch in log_batches:
        try:
            kafka_producer.send('non_critical_logs', value=batch)
        except Exception as e:
            print(f"Error processing non-critical logs: {e}")

# Define a simple API endpoint for accepting log events
@app.route('/logs', methods=['POST'])
def accept_log_event():
    event = request.get_json()
    if 'log_level' in event and event['log_level'] == 'CRITICAL':
        # Process critical logs in real-time
        log_event(event)
    else:
        # Queue non-critical logs for asynchronous processing
        process_non_critical_logs([event]).delay()

    return jsonify({'message': 'Log event accepted'})

# Start the Flask app and Celery worker
if __name__ == '__main__':
    app.run(debug=True)

celery = Celery('logs', broker='amqp://guest:guest@localhost')
celery.conf.update({
    'result_backend': 'rpc://',
})
celery.start()
