    broker->numTenants = 0;
    broker->tenants = NULL;
    pthread_mutex_init(&broker->lock, NULL);
    pthread_cond_init(&broker->cond, NULL);
}

// Add a new tenant to the messaging broker
void addTenant(MessagingBroker* broker, Tenant* tenant) {
    // Lock the messaging broker for thread safety
    pthread_mutex_lock(&broker->lock);

    // Allocate memory for the new tenant if necessary
    if (broker->numTenants >= 1024) {
        broker->tenants = realloc(broker->tenants, (broker->numTenants + 1) * sizeof(Tenant*));
    }

    // Add the new tenant to the messaging broker
    broker->tenants[broker->numTenants] = tenant;
    broker->numTenants++;

    // Unlock the messaging broker for thread safety
    pthread_mutex_unlock(&broker->lock);
}

