// Define structure for message
typedef struct {
    char* topic;
    char* payload;
} Message;

// Define structure for broker node
typedef struct {
    int id;
    Message messages[10];
    int num_messages;
} BrokerNode;

// Function to create a new broker node
BrokerNode* create_node(int id) {
    BrokerNode* node = (BrokerNode*)malloc(sizeof(BrokerNode));
    node->id = id;
    node->num_messages = 0;
    return node;
}

// Function to add message to a broker node
void add_message(BrokerNode* node, char* topic, char* payload) {
    Message* new_msg = (Message*)malloc(sizeof(Message));
    new_msg->topic = topic;
    new_msg->payload = payload;
    node->messages[node->num_messages] = *new_msg;
    node->num_messages++;
}

// Function to remove a message from a broker node
void remove_message(BrokerNode* node, int index) {
    if (index < node->num_messages) {
        free(node->messages[index]);
        for (int i = index; i < node->num_messages - 1; i++) {
            node->messages[i] = node->messages[i + 1];
        }
        node->num_messages--;
    }
}

// Function to handle message delivery
void deliver_message(BrokerNode* node, char* topic) {
    for (int i = 0; i < node->num_messages; i++) {
        if (strcmp(node->messages[i].topic, topic) == 0) {
            // Handle message delivery here
            printf("Message delivered: %s\n", node->messages[i].payload);
            return;
        }
    }
    printf("No messages found for topic '%s'\n", topic);
}

// Function to handle broker node failure
void handle_node_failure(BrokerNode* node) {
    // Handle node failure here
    printf("Broker node %d failed\n", node->id);
    free(node);
}

int main() {
    BrokerNode* node = create_node(1);

    add_message(node, "topic1", "payload1");
    add_message(node, "topic2", "payload2");
    add_message(node, "topic3", "payload3");

    deliver_message(node, "topic1");

    remove_message(node, 0);

    handle_node_failure(node);

    return 0;
}
