// Architecture
package com.example.ecommerce.logging;

import java.util.concurrent.BlockingQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ThreadPoolExecutor;
import java.util.concurrent.TimeUnit;

public class LoggingSystem {
    private static final int CORE_POOL_SIZE = 10;
    private static final int MAX_POOL_SIZE = 50;
    private static final long KEEP_ALIVE_TIME = 30000; // 30 seconds

    private BlockingQueue<LogEvent> logBuffer = new LinkedBlockingQueue<>();
    private ThreadPoolExecutor threadPool;

    public LoggingSystem() {
        threadPool = new ThreadPoolExecutor(CORE_POOL_SIZE, MAX_POOL_SIZE, KEEP_ALIVE_TIME, TimeUnit.MILLISECONDS);
    }

    public void ingest(LogEvent logEvent) throws InterruptedException {
        logBuffer.put(logEvent);

        if (logBuffer.size() >= 1000000) { // 1 million logs per second
            threadPool.submit(() -> processLogs());
        }
    }

    private void processLogs() {
        try {
            while (!logBuffer.isEmpty()) {
                LogEvent logEvent = logBuffer.take();
                // Process log event here
                logEvent.close();
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    public void shutdown() {
        threadPool.shutdown();
    }
}

