import json
from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from flask_caching import Cache
from flask_login import LoginManager, UserMixin, login_user, logout_user, current_user
from werkzeug.security import generate_password_hash, check_password_hash
from functools import wraps
from datetime import datetime

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///users.db'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False
app.config['CACHE_TYPE'] = 'SimpleCache'
app.config['CACHE_CONTROL'] = 'public, max-age=3600'

db = SQLAlchemy(app)
cache = Cache(app)

class User(UserMixin):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    password_hash = db.Column(db.String(128))
    email = db.Column(db.String(120), unique=True, nullable=False)
    roles = db.relationship('Role', secondary='user_roles')

class Role:
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(80), nullable=False)

@app.route('/login', methods=['POST'])
def login():
    user_data = request.get_json()
    username = user_data['username']
    password = user_data['password']

    user = User.query.filter_by(username=username).first()
    if user and check_password_hash(user.password_hash, password):
        login_user(user)
        return jsonify({'message': 'Login successful'}), 200
    else:
        return jsonify({'message': 'Invalid credentials'}), 401

@app.route('/logout', methods=['POST'])
def logout():
    logout_user()
    return jsonify({'message': 'Logout successful'}), 200

@app.route('/register', methods=['POST'])
def register():
    user_data = request.get_json()
    username = user_data['username']
    password = generate_password_hash(user_data['password'])
    email = user_data['email']

    new_user = User(username=username, password_hash=password, email=email)
    db.session.add(new_user)
    db.session.commit()

    return jsonify({'message': 'User created successfully'}), 201

@app.route('/user', methods=['GET'])
def get_user():
    if current_user.is_authenticated:
        user_data = {'username': current_user.username, 'email': current_user.email}
        return jsonify(user_data), 200
    else:
        return jsonify({'message': 'User not authenticated'}), 401

@app.route('/user', methods=['PUT'])
def update_user():
    if current_user.is_authenticated:
        user_data = request.get_json()
        current_user.username = user_data['username']
        current_user.email = user_data['email']

        db.session.commit()

        return jsonify({'message': 'User updated successfully'}), 200
    else:
        return jsonify({'message': 'User not authenticated'}), 401

@app.route('/role', methods=['POST'])
def assign_role():
    if current_user.is_authenticated:
        role_name = request.get_json()['role']

        role = Role.query.filter_by(name=role_name).first()
        if role:
            current_user.roles.append(role)
            db.session.commit()

            return jsonify({'message': 'Role assigned successfully'}), 200
        else:
            return jsonify({'message': 'Role not found'}), 404
    else:
        return jsonify({'message': 'User not authenticated'}), 401

@app.route('/role', methods=['DELETE'])
def revoke_role():
    if current_user.is_authenticated:
        role_name = request.get_json()['role']

        role = Role.query.filter_by(name=role_name).first()
        if role and role in current_user.roles:
            current_user.roles.remove(role)
            db.session.commit()

            return jsonify({'message': 'Role revoked successfully'}), 200
        else:
            return jsonify({'message': 'Role not found or already revoked'}), 404
    else:
        return jsonify({'message': 'User not authenticated'}), 401

if __name__ == '__main__':
    app.run(debug=True)
