// Define the structure for a record with unique integer key and offset
typedef struct Record {
    int key;
    long offset;
} Record;

// Define the structure to manage the collection of records
typedef struct RecordCollection {
    Record* records;
    size_t capacity;
    size_t count;
} RecordCollection;

// Create a new record collection with initial capacity
RecordCollection* createRecordCollection(size_t initialCapacity) {
    RecordCollection* rc = (RecordCollection*)malloc(sizeof(RecordCollection));
    rc->records = (Record*)calloc(initialCapacity, sizeof(Record));
    rc->capacity = initialCapacity;
    rc->count = 0;
    return rc;
}

// Add a new record or update the existing one with unique key and offset
void addRecord(int key, long offset, RecordCollection* collection) {
    // Check if the key is already present in the collection
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            collection->records[i].offset = offset;
            return;
        }
    }

    // Add a new record with unique key and offset
    if (collection->count >= collection->capacity) {
        // Increase the capacity of the collection by doubling it
        size_t newCapacity = collection->capacity * 2;
        Record* newRecords = (Record*)realloc(collection->records, newCapacity * sizeof(Record));
        collection->records = newRecords;
        collection->capacity = newCapacity;
    }

    collection->records[collection->count].key = key;
    collection->records[collection->count].offset = offset;
    ++collection->count;
}

// Update the existing record with unique key
void updateRecord(int key, long offset, RecordCollection* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->records[i].key == key) {
            collection->records[i].offset = offset;
            return;
        }
