// Define NetworkEventLogEntry structure
typedef struct {
    int timestamp;
    char event_type[16];
    char description[64];
} NetworkEventLogEntry;

// Define log_entry_t type for dynamic array
typedef struct {
    NetworkEventLogEntry* entries;
    size_t capacity;
    size_t size;
} log_entry_t;

// Initialize log_entry_t with default capacity and size
log_entry_t* log_init(size_t initial_capacity) {
    log_entry_t* log = (log_entry_t*)malloc(sizeof(log_entry_t));
    log->entries = (NetworkEventLogEntry*)malloc(initial_capacity * sizeof(NetworkEventLogEntry));
    log->capacity = initial_capacity;
    log->size = 0;
    return log;
}

// Add event to the log
void log_add(log_entry_t* log, NetworkEventLogEntry entry) {
    if (log->size == log->capacity) {
        // Resize array when full
        log->entries = realloc(log->entries, (log->capacity * 2) * sizeof(NetworkEventLogEntry));
        log->capacity *= 2;
    }
    log->entries[log->size] = entry;
    log->size++;
}

// Print log entries
void log_print(log_entry_t* log) {
    for (int i = 0; i < log->size; i++) {
        printf("Timestamp: %d, Event Type: %s, Description: %s\n", 
               log->entries[i].timestamp, log->entries[i].event_type, log->entries[i].description);
    }
}

// Free allocated memory
void log_free(log_entry_t* log) {
    free(log->entries);
    free(log);
}
