#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure for packet data
typedef struct {
    int seq_num;
    char* data;
} Packet;

// Define a callback function type
typedef void (*PacketCallback)(int seq_num, char* data);

// Define the packet manager data structure
struct PacketManager {
    pthread_mutex_t mutex; // Mutex for thread safety
    pthread_cond_t cond; // Condition variable for concurrency
    int max_packets;
    Packet* packets;
    int current_packet;
    PacketCallback callback;
};

// Initialize the packet manager
void init_packet_manager(PacketManager* pm, int max_packets) {
    pm->max_packets = max_packets;
    pm->packets = (Packet*)malloc(max_packets * sizeof(Packet));
    pm->current_packet = 0;
}

// Insert a new packet into the manager
void insert_packet(PacketManager* pm, int seq_num, char* data) {
    Packet packet;
    packet.seq_num = seq_num;
    packet.data = data;

    pthread_mutex_lock(&pm->mutex);
    pm->packets[pm->current_packet] = packet;
    pm->current_packet++;

    if (pm->current_packet == pm->max_packets) {
        pm->current_packet = 0; // Wrap around to the beginning
    }

    pthread_cond_signal(&pm->cond);
    pthread_mutex_unlock(&pm->mutex);

    if (pm->callback) {
        pm->callback(seq_num, data);
    }
}

// Remove a packet from the manager based on sequence number
void remove_packet(PacketManager* pm, int seq_num) {
    for (int i = 0; i < pm->max_packets; i++) {
        if (pm->packets[i].seq_num == seq_num) {
            pm->packets[i] = pm->packets[pm->current_packet - 1];
            pm->current_packet--;
            break;
        }
    }
}

// Check if a packet is present in the manager
int has_packet(PacketManager* pm, int seq_num) {
    for (int i = 0; i < pm->max_packets; i++) {
        if (pm->packets[i].seq_num == seq_num) {
            return 1;
        }
    }
    return 0;
}

// Main function to test the packet manager
