package com.example.api_gateway;

import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.ArrayList;
import java.util.List;
import java.util.HashMap;
import java.util.Map;

public class ApiGateway {
    private ConcurrentLinkedQueue<NFAPI_CRC_INDICATION_PDU_T> pduQueue = new ConcurrentLinkedQueue<>();
    private Map<String, ExternalAPI> externalApis = new HashMap<>();

    public void initAndTransmitPdus(NFAPI_CRC_INDICATION_PDU_T[] pdus) {
        // Initialize transmission parameters
        int maxPacketSize = 1024;
        int transmissionInterval = 1000; // in milliseconds
        int retryLimits = 3;

        // Create a thread-safe queue to manage PDUs
        pduQueue = new ConcurrentLinkedQueue<>();

        // Add pdus to the queue
        for (NFAPI_CRC_INDICATION_PDU_T pdu : pdus) {
            pduQueue.add(pdu);
        }

        // Initialize external API connections
        ExternalAPI api1 = new ExternalAPI("api1", "https://api1.com");
        ExternalAPI api2 = new ExternalAPI("api2", "https://api2.com");
        externalApis.put(api1.getName(), api1);
        externalApis.put(api2.getName(), api2);

        // Start transmission threads
        Thread thread1 = new TransmissionThread(externalApis.get("api1"), pduQueue, maxPacketSize, transmissionInterval, retryLimits);
        thread1.start();

        Thread thread2 = new TransmissionThread(externalApis.get("api2"), pduQueue, maxPacketSize, transmissionInterval, retryLimits);
        thread2.start();
    }

    private class ExternalAPI {
        private String name;
        private String url;

        public ExternalAPI(String name, String url) {
            this.name = name;
            this.url = url;
        }

        public String getName() {
            return name;
        }
    }

    private class TransmissionThread extends Thread {
        private ExternalAPI api;
        private ConcurrentLinkedQueue<NFAPI_CRC_INDICATION_PDU_T> pduQueue;
        private int maxPacketSize;
        private int transmissionInterval;
        private int retryLimits;

        public TransmissionThread(ExternalAPI api, ConcurrentLinkedQueue<NFAPI_CRC_INDICATION_PDU_T> pduQueue, int maxPacketSize, int transmissionInterval, int retryLimits) {
            this.api = api;
            this.pduQueue = pduQueue;
            this.maxPacketSize = maxPacketSize;
            this.transmissionInterval = transmissionInterval;
            this.retryLimits = retryLimits;
        }

        public void run() {
            while (true) {
                NFAPI_CRC_INDICATION_PDU_T pdu = pduQueue.poll();
                if (pdu == null) {
                    break;
                }

                try {
                    // Transmit PDU to external API
                    api.transmitPdu(pdu);

                    // Log transmission success
                    System.out.println("Transmission successful: " + pdu);
                } catch (Exception e) {
                    // Handle transmission failure
                    System.out.println("Transmission failed: " + pdu);
                }
            }

            // Log thread exit
            System.out.println("Thread exited");
        }
    }
