    // Dynamic list of packets
    TX_PACKET** packets;
    int num_packets;
    // Sequence number generator for new packets
    int seq_gen;
} PACKET_MANAGER;

// Initialize a new packet manager
PACKET_MANAGER* init_packet_manager() {
    PACKET_MANAGER* pm = (PACKET_MANAGER*) malloc(sizeof(PACKET_MANAGER));
    pm->num_packets = 0;
    pm->seq_gen = 0;
    return pm;
}

// Insert a new packet into the dynamic list
int insert_packet(PACKET_MANAGER* pm, TX_PACKET* packet) {
    // Check if the sequence number is unique
    for (int i = 0; i < pm->num_packets; i++) {
        if (pm->packets[i]->sequence_number == packet->sequence_number) {
            return -1; // Duplicate sequence number
        }
    }

    // Insert the new packet into the list
    TX_PACKET** new_packets = (TX_PACKET**) realloc(pm->packets, (pm->num_packets + 1) * sizeof(TX_PACKET*));
    if (!new_packets) {
        return -2; // Memory allocation failure
    }
    new_packets[pm->num_packets] = packet;
    pm->packets = new_packets;
    pm->num_packets++;

    return 0; // Successful insertion
}

// Remove a packet from the dynamic list by sequence number
int remove_packet(PACKET_MANAGER* pm, int seq_number) {
    for (int i = 0; i < pm->num_packets; i++) {
        if (pm->packets[i]->sequence_number == seq_number) {
            // Shift remaining packets to fill the gap
            for (int j = i + 1; j < pm->num_packets; j++) {
                pm->packets[j - 1] = pm->packets[j];
            }
            free(pm->packets[pm->num_packets - 1]);
            pm->num_packets--;
            return 0; // Successful removal
        }
    }
    return -1; // Packet not found
}

// Get the number of packets in the dynamic list
int get_num_packets(PACKET_MANAGER* pm) {
    return pm->num_packets;
}

// Free the packet manager resources
void free_packet_manager(PACKET_MANAGER* pm) {
    for (int i = 0; i < pm->num_packets; i++) {
        free(pm->packets[i]);
    }
    free(pm->packets);
    free(pm);
}
