    private void initializeService() {
        // Initialize the edge servers and their corresponding metadata payloads
        edgeServers = new HashMap<>();
        for (int i = 0; i < MAX_CONCURRENT_PDU_OBJECTS; i++) {
            EdgeServer edgeServer = new EdgeServer();
            edgeServers.put(i, edgeServer);
        }
    }

    private void startSynchronization() {
        // Start the synchronization threads
        Thread[] threads = new Thread[MAX_CONCURRENT_PDU_OBJECTS];
        for (int i = 0; i < MAX_CONCURRENT_PDU_OBJECTS; i++) {
            threads[i] = new Thread(() -> synchronize(i));
            threads[i].start();
        }
    }

    private void synchronize(int edgeServerIndex) {
        // Synchronize the metadata payload with the corresponding edge server
        EdgeServer edgeServer = edgeServers.get(edgeServerIndex);
        MetadataPayload metadataPayload = new MetadataPayload();

        // Perform the synchronization operation
        try {
            edgeServer.synchronize(metadataPayload);
        } catch (Exception e) {
            // Handle the exception
            handleException(e);
        }
    }

    private void handleException(Exception e) {
        // Log the error and re-synchronize
        logError(e.getMessage());
        synchronize(edgeServerIndex);
    }

    private void logError(String errorMessage) {
