```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define SessionState structure
typedef struct {
    char* sessionId;
    char* userId;
    int qosThreshold;
    int connectionStatus;
    long lastHeartbeatTimestamp;
} SessionState;

// Define Linked List Node structure
typedef struct {
    SessionState sessionState;
    struct linkedListNode* next;
} LinkedListNode;

// Define Linked List structure
typedef struct {
    LinkedListNode* head;
    pthread_mutex_t mutex;
} LinkedList;

// Function to create a new SessionState
SessionState* createSessionState(char* sessionId, char* userId) {
    SessionState* sessionState = (SessionState*)malloc(sizeof(SessionState));
    sessionState->sessionId = strdup(sessionId);
    sessionState->userId = strdup(userId);
    sessionState->qosThreshold = 0;
    sessionState->connectionStatus = 1;
    sessionState->lastHeartbeatTimestamp = time(NULL);
    return sessionState;
}

// Function to add a new node to the linked list
void addNode(LinkedList* linkedList, SessionState* sessionState) {
    LinkedListNode* newNode = (LinkedListNode*)malloc(sizeof(LinkedListNode));
    newNode->sessionState = sessionState;
    newNode->next = linkedList->head;
    linkedList->head = newNode;
}

// Function to remove a node from the linked list
void removeNode(LinkedList* linkedList, SessionState* sessionState) {
    LinkedListNode* current = linkedList->head;
    LinkedListNode* previous = NULL;

    while (current != NULL) {
        if (strcmp(current->sessionState.sessionId, sessionState->sessionId) == 0) {
            if (previous == NULL) {
                linkedList->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            return;
        }

        previous = current;
        current = current->next;
    }
}

// Function to print the linked list
void printLinkedList(LinkedList* linkedList) {
    LinkedListNode* current = linkedList->head;

    while (current != NULL) {
        printf("%s - %s\n", current->sessionState.sessionId, current->sessionState.userId);
        current = current->next;
    }
}

int main() {
    // Initialize the linked list
    LinkedList linkedList;
    linkedList.head = NULL;
    pthread_mutex_init(&linkedList.mutex, NULL);

    // Create some session states
    SessionState* session1 = createSessionState("s1", "u1");
    SessionState* session2 = createSessionState("s2", "u2");

    // Add the session states to the linked list
    addNode(&linkedList, session1);
    addNode(&linkedList, session2);

    // Print the linked list
    printLinkedList(&linkedList);

    return 0;
}
```

This code provides a basic implementation of the distributed session state management service. It includes functions to create, add, and remove `SessionState` structures from a linked list, as well as a function to print the linked list.']

