    while(pm->is_running) {
        // Process packets based on current throughput, latency, and packet loss rate

        // Signal updates to other threads
        pthread_cond_signal(&pm->cond);

        // Sleep for a short duration to avoid busy-waiting
        usleep(10000);  // adjust this value based on your system's requirements
    }

    return NULL;
}

// Start the packet manager
void start_packet_manager(PACKET_MANAGER* pm) {
    pthread_t thread;

    // Create a new thread for processing packets
    pthread_create(&thread, NULL, process_packets, pm);
}

// Stop the packet manager
void stop_packet_manager(PACKET_MANAGER* pm) {
    pm->is_running = false;
    // Wake up the processing thread to ensure shutdown
    pthread_cond_broadcast(&pm->cond);

    // Wait for the processing thread to complete
    pthread_join(thread, NULL);
}

