using System;
using System.IO;
using System.Threading;
using System.Threading.Tasks;

namespace LargeBinaryDataProcessor
{
    public class LargeBinaryDataProcessor : IDisposable
    {
        private readonly ILogger _logger;
        private readonly IMetadataApi _metadataApi;
        private readonly IThirdPartyService _thirdPartyService;

        public LargeBinaryDataProcessor(ILogger logger, IMetadataApi metadataApi, IThirdPartyService thirdPartyService)
        {
            _logger = logger;
            _metadataApi = metadataApi;
            _thirdPartyService = thirdPartyService;
        }

        public async Task ProcessLargeBinaryDataAsync(string filePath)
        {
            using var fileStream = File.OpenRead(filePath);
            await ProcessFileStreamAsync(fileStream);
        }

        private async Task ProcessFileStreamAsync(Stream fileStream)
        {
            const int chunkSize = 1024 * 1024; // 1 MB chunks
            byte[] buffer = new byte[chunkSize];

            while (await ReadChunkFileAsync(fileStream, buffer))
            {
                await ValidateDataAsync(buffer);
            }
        }

        private async Task<bool> ReadChunkFileAsync(Stream fileStream, byte[] buffer)
        {
            int bytesRead;
            try
            {
                bytesRead = fileStream.Read(buffer, 0, chunkSize);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error reading file stream");
                return false;
            }

            if (bytesRead == 0) return false;

            await Task.Yield(); // Allow other threads to run
            return bytesRead < chunkSize; // Not end of file yet?
        }

        private async Task ValidateDataAsync(byte[] buffer)
        {
            // Call external metadata API and validate data
            try
            {
                await _metadataApi.ValidateDataAsync(buffer);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error validating data");
            }
        }

        public void Dispose()
        {
            _logger?.Dispose();
        }
    }
}
