import pandas as pd
from datetime import datetime, timedelta
import pyarrow as pa
import awsglue as glue
import boto3
import logging
import os
import re
from io import BytesIO
from typing import Dict, List

class DataPipeline:
    def __init__(self):
        self.data_sources = {}
        self.transformations = []
        self.enrichments = []
        self.error_handlers = []
        self.config = {}

    def add_data_source(self, name: str, source: dict):
        self.data_sources[name] = source

    def add_transformation(self, transformation: dict):
        self.transformations.append(transformation)

    def add_enrichment(self, enrichment: dict):
        self.enrichments.append(enrichment)

    def add_error_handler(self, error_handler: dict):
        self.error_handlers.append(error_handler)

    def configure(self, config: Dict):
        self.config = config

    def process_data(self, data: pd.DataFrame) -> pa.Table:
        for transformation in self.transformations:
            data = transformation(data)

        for enrichment in self.enrichments:
            data = enrichment(data)

        return pa.Table.from_pandas(data)

    def handle_error(self, error: Exception):
        if len(self.error_handlers) > 0:
            handler = self.error_handlers[0]
            data = handler(error)
            return data
        else:
            raise error

    def execute_pipeline(self):
        for data_source_name in self.data_sources:
            source = self.data_sources[data_source_name]
            try:
                data = source.read()
                transformed_data = self.process_data(data)
                # serialize and store data
                with BytesIO() as buffer:
                    pa.Table.to_csv(transformed_data, buffer).seek(0)
                    s3 = boto3.client('s3')
                    bucket_name = 'my-bucket'
                    s3.put_object(Body=buffer.getvalue(), Bucket=bucket_name, Key='data.csv')
            except Exception as e:
                data = self.handle_error(e)
        logging.info("Data pipeline executed successfully")

    def start_pipeline(self):
        while True:
            try:
                self.execute_pipeline()
            except Exception as e:
                if len(self.error_handlers) > 0:
                    handler = self.error_handlers[0]
                    data = handler(e)
                    time.sleep(10)
                else:
                    raise e

# Example usage:

data_pipeline = DataPipeline()

aws_glue_job = glue.Job(name="my-glue-job", script='myscript.py')
aws_glue_job.run()

data_pipeline.add_data_source("iot-data-source", {"read": lambda: pd.read_csv('iot-data.csv')})
data_pipeline.add_transformation({"function": lambda x: x['column1'] * 2})
data_pipeline.add_enrichment({"function": lambda x: x.dropna()})
data_pipeline.add_error_handler({"handler": lambda e: e})

data_pipeline.configure({"data-retention-policy": "7 days", "processing-interval": "5 minutes"})

data_pipeline.start_pipeline()
```']

