from retrying import retry

app = Flask(__name__)
CORS(app)

LOGGING_FORMAT = '%(asctime)s - %(levelname)s - %(message)s'
logging.basicConfig(filename='file_hashes.log', level=logging.INFO,
                    format=LOGGING_FORMAT)
logger = logging.getLogger()

kms_api_url = 'https://kms.example.com/v1/encryption-keys'

@retry(wait_exponential_max=30, stop_max_attempt_number=6)
def get_encryption_key(file_name):
    try:
        response = requests.get(f'{kms_api_url}/{file_name}.key')
        response.raise_for_status()
        return response.json()['key']
    except Exception as e:
        logger.error(f'Failed to retrieve encryption key: {e}')
        raise

@app.route('/hash_file', methods=['POST'])
def hash_file():
    try:
        file_data = request.get_json()
        file_path = file_data['file_path']
        encrypted_key = get_encryption_key(file_path)
        with open(file_path, 'rb') as f:
            file_hash = hashlib.sha256(f.read()).hexdigest()
        return jsonify({'hash': file_hash, 'key': encrypted_key})
    except Exception as e:
        logger.error(f'Failed to hash file: {e}')
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(debug=True)
