import os
import re
import logging
from datetime import datetime
from functools import lru_cache
from cryptography.fernet import Fernet
from flask import Flask, request, jsonify
from flask_api import status
from redis import StrictRedis
from rq import Queue, Job

app = Flask(__name__)
log_level = 'INFO'
logging.basicConfig(level=logging.getLevelName(log_level))
logger = logging.getLogger(__name__)

# Redis connection for job queue and caching
redis_client = StrictRedis(host='localhost', port=6379, db=0)
queue = Queue(connection=redis_client)

# Load rules for log enrichment and transformation
rules = {}

# Initialize the Fernet key for encryption
fernet_key = Fernet.generate_key()

# Set up the Flask API with CORS support
@app.after_request
def after_request(response):
    response.headers.add('Access-Control-Allow-Origin', '*')
    return response

@app.route('/logs', methods=['POST'])
def process_logs():
    if request.method == 'POST':
        logs = request.get_json()
        # Enrich and transform logs using the rules
        enriched_logs = []
        for log in logs:
            # Apply log enrichment and transformation rules
            transformed_log = apply_rules(log)
            enriched_logs.append(transformed_log)
        return jsonify(enriched_logs)

@app.route('/files', methods=['GET'])
def traverse_files():
    path = request.args.get('path')
    depth = int(request.args.get('depth'))
    # Recursively traverse the directory hierarchy
    files = []
    for root, dirs, filenames in os.walk(path):
        for filename in filenames:
            file_path = os.path.join(root, filename)
            if os.lstat(file_path).st_size > 0:
                files.append(file_path)
    return jsonify(files)

@lru_cache(maxsize=None)
def apply_rules(log):
    # Apply the log enrichment and transformation rules
    enriched_log = {}
    for rule in rules.values():
        if re.match(rule['pattern'], log['message']):
            enriched_log.update(rule['transformations'])
    return enriched_log

@app.route('/jobs', methods=['POST'])
def schedule_job():
    job_name = request.get_json()['job_name']
    queue.enqueue(job=Job.create(job_name, args=('job_args',)))

if __name__ == '__main__':
    app.run(debug=True)
```

