// Define the packet structure
typedef struct {
    int transmission_tag;
    int sequence_number;
    int data_size;
} TX_PACKET;

// Define the packet manager function
void generateNfarcrcIndications(int num_packets, NFAPI_CRC_INDICATION_PDU_T *indications) {
    // Initialize a counter for sequence numbers
    int seq_num = 0;

    // Loop through the number of packets
    for (int i = 0; i < num_packets; i++) {
        // Create a new TX_PACKET structure
        TX_PACKET* packet = (TX_PACKET*)malloc(sizeof(TX_PACKET));

        // Set the transmission tag, sequence number, and data size
        packet->transmission_tag = i;
        packet->sequence_number = seq_num++;
        packet->data_size = 1024;  // Default data size

        // Add the packet to the array of indications
        indications[i] = (NFAPI_CRC_INDICATION_PDU_T){.packet = packet};
    }
}

int main() {
    int num_packets = 10000;
    NFAPI_CRC_INDICATION_PDU_T* indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_packets * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Call the packet manager function
    generateNfarcrcIndications(num_packets, indications);

    // Free the memory allocated for the packets
    for (int i = 0; i < num_packets; i++) {
        free(indications[i].packet);
    }

    free(indications);

    return 0;
}
