import java.util.*;
import java.io.*;

public class MessageBroker {

    private Map<String, List<Message>> topicMessages;
    private Map<String, Integer> publisherCounts;

    public MessageBroker() {
        this.topicMessages = new HashMap<>();
        this.publisherCounts = new HashMap<>();
    }

    // Dynamic message management

    public void publishMessage(String topic, String message) {
        if (!topicMessages.containsKey(topic)) {
            topicMessages.put(topic, new ArrayList<>());
        }
        topicMessages.get(topic).add(new Message(message));
        publisherCounts.computeIfAbsent(topic, k -> 0);
        publisherCounts.put(topic, publisherCounts.getOrDefault(topic, 0) + 1);
    }

    public void deleteMessage(String topic, String message) {
        if (topicMessages.containsKey(topic)) {
