void* manageUEList(void* arg) {
    // Define a lock-free queue for UE event enqueuing and dequeuing
    struct node {
        LTE_UERadioResourceManagementMessage msg;
        struct node* next;
    };
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    struct node* head = NULL;
    struct node* tail = NULL;

    // Define an LRU eviction policy
    struct lru_entry {
        int ue_id;
        struct lru_entry* prev;
        struct lru_entry* next;
    };
    struct lru_entry* head_lru = NULL;
    int lru_size = 1000; // adjust as needed

    while (1) {
        // Handle UE association events
        pthread_mutex_lock(&lock);
        struct node* current = head;
        while (current != NULL) {
            LTE_UERadioResourceManagementMessage msg = current->msg;
            // Process the UE event...
            current = current->next;
        }
        pthread_mutex_unlock(&lock);

        // Manage memory usage
        int heap_usage = get_heap_usage();
        if (heap_usage > MAX_HEAP_USAGE) {
            // Proactively reclaim memory
            lru_eviction(head_lru, lru_size);
            head_lru = NULL; // reset LRU list
        }

        // Concurrency handling
        pthread_mutex_lock(&lock);
        struct node* new_node = malloc(sizeof(struct node));
        if (new_node == NULL) {
            // Handle memory allocation failure
            error_log("Memory allocation failed");
        } else {
            // Enqueue the new UE event
            new_node->next = head;
            head = new_node;
            if (tail == NULL) tail = head;
            pthread_mutex_unlock(&lock);
        }
    }

    return NULL;
}
