```cpp
#include <iostream>
#include <map>
#include <queue>
#include <string>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <unordered_map>

using namespace std;

// Define the cache object structure
struct CACHE_OBJECT {
    string KEY;
    int EXPIRATION_TIMESTAMP;
    int DATA_SIZE;
    int ACCESS_COUNT;
};

class CacheLayer {
public:
    // Constructor to initialize the cache layer
    CacheLayer(int capacity) : capacity(capacity), cacheSize(0), lock{}, cond{} {}

    // Insert a new cache object into the cache layer
    void insert(CACHE_OBJECT obj) {
        unique_lock<mutex> lock(this->lock);
        if (cacheSize + obj.DATA_SIZE > this->capacity) {
            // Evict an old entry to make room for the new one
            evict();
        }
        cache[obj.KEY] = obj;
        cacheSize += obj.DATA_SIZE;
    }

    // Retrieve a cache object from the cache layer
    CACHE_OBJECT* get(string key) {
        unique_lock<mutex> lock(this->lock);
        auto it = cache.find(key);
        if (it != cache.end()) {
            return &it->second;
        }
        return nullptr;
    }

    // Evict an old entry to free up space in the cache layer
    void evict() {
        unique_lock<mutex> lock(this->lock);
        priority_queue<pair<int, string>, vector<pair<int, string>>, greater<pair<int, string>>> queue;

        for (auto& entry : cache) {
            queue.push({entry.second.ACCESS_COUNT, entry.first});
        }

        // Evict the oldest entry
        while (!queue.empty() && cacheSize > this->capacity) {
            auto pair = queue.top();
            queue.pop();
            cache.erase(pair.second);
            cacheSize -= CACHE_OBJECT{pair.second, 0, 0, 0}.DATA_SIZE;
        }
    }

private:
    int capacity;
    int cacheSize;
    mutex lock;
    condition_variable cond;

};

int main() {
    // Initialize the cache layer with a capacity of 100MB
    CacheLayer cache(102400000);

    // Insert some sample cache objects
    CACHE_OBJECT obj1 = {"key1", 1643723400, 1024, 10};
    cache.insert(obj1);
    CACHE_OBJECT obj2 = {"key2", 1643723500, 2048, 20};
    cache.insert(obj2);

    // Retrieve a cache object
    CACHE_OBJECT* retrievedObj = cache.get("key1");
    if (retrievedObj) {
        cout << "Retrieved Object: " << retrievedObj->KEY << endl;
    }

    return 0;
}

```

