import json
import asyncio
from concurrent.futures import ThreadPoolExecutor

class LoggerConfigManager:
    def __init__(self):
        self.configs = {}
        self.lock = asyncio.Lock()

    async def update_config(self, logger_name, config):
        async with self.lock:
            if logger_name not in self.configs:
                self.configs[logger_name] = config
            else:
                raise ValueError(f"Logger {logger_name} already configured")

    async def get_config(self, logger_name):
        async with self.lock:
            return self.configs.get(logger_name)

    async def delete_config(self, logger_name):
        async with self.lock:
            if logger_name in self.configs:
                del self.configs[logger_name]

    async def request_update(self, logger_name, config):
        loop = asyncio.get_event_loop()
        await loop.run_in_executor(
            ThreadPoolExecutor(max_workers=5),
            lambda: self.update_config(logger_name, config)
        )

    async def check_config(self, logger_name):
        try:
            config = await self.get_config(logger_name)
            if not config or not isinstance(config, dict):
                raise ValueError(f"Logger {logger_name} has no valid configuration")
            logging_level = config.get("logging_level", "INFO")
            destination = config.get("destination", "console")
            return logging_level, destination
        except Exception as e:
            raise e

    def run(self):
        try:
            loop = asyncio.get_event_loop()
            while True:
                task = await loop.next_task()
                if task == "stop":
                    break
                logger_name, config = task
                await self.update_config(logger_name, config)
            loop.stop()
        except Exception as e:
            print(f"Error: {e}")

    def start(self):
        try:
            asyncio.run_coroutine_threadsafe(self.run(), executor=ThreadPoolExecutor(max_workers=1))
        except Exception as e:
            print(f"Error: {e}")

# Example usage
config_manager = LoggerConfigManager()
asyncio.run(config_manager.start())

# Request updates from external sources (cloud-based logging services)
async def update_configs():
    while True:
        config_updates = await get_config_updates_from_cloud()
        for logger_name, config in config_updates.items():
            await config_manager.request_update(logger_name, config)

asyncio.create_task(update_configs())
