NFAPI_CRC_INDICATION_PDU_T* populateNFAPICRCIndications(int N) {
    // Predefined list of RX_UE_INFORMATION_TAG
    const char* tags[] = {"TAG1", "TAG2", ..., "TAGn"};

    // Dynamic memory allocation for array of structures
    NFAPI_CRC_INDICATION_PDU_T* ndi_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!ndi_array) {
        return NULL;
    }

    // Initialize each structure with a valid RX_UE_INFORMATION_TAG
    for (int i = 0; i < N; i++) {
        strcpy(ndi_array[i].RX_UE_INFORMATION_TAG, tags[rand() % sizeof(tags)/sizeof(tags[0])]);

        // Unique RNTI generation within specified range
        ndi_array[i].RNTI = rand() % (MAX_RNTI - MIN_RNTI + 1) + MIN_RNTI;

        // Randomly set CRCFLAG, enforcing no more than three consecutive repeats
        int last_flag = ndi_array[0].CRCFLAG;
        for (int j = 1; j < N; j++) {
            ndi_array[j].CRCFLAG = rand() % 2 ? CRCFLAG_ON : CRCFLAG_OFF;

            if (ndi_array[j].CRCFLAG == last_flag) {
                // Enforce constraint: change CRCFLAG every three consecutive repeats
                if (++last_flag >= 3) last_flag = 0;
                j--;
            }
        }
    }

    return ndi_array;
}
