    if (node->next) node->next->prev = node->prev;
    else dll->tail = node->prev;
    free(node);
    dll->size--;
}

// Function to print the doubly-linked list
void printList(DoublyLinkedList* dll) {
    Node* current = dll->head;
    while (current) {
        printf("%d %s %d\n", current->data.RX_UE_INFORMATION_TAG, current->data.RNTI, current->data.CRC_INDICATION_REL8_TAG);
        current = current->next;
    }
}

// Define the library
void* lib_nfa_crc_indication_pdu_t_list_create() {
    DoublyLinkedList* dll = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!dll) return NULL;
    dll->head = NULL;
    dll->tail = NULL;
    dll->size = 0;
    return dll;
}

void lib_nfa_crc_indication_pdu_t_list_insert(void* dll, void* data) {
    DoublyLinkedList* dll_ptr = (DoublyLinkedList*)dll;
    Node* node = (Node*)data;
    insert(dll_ptr, node);
}

void lib_nfa_crc_indication_pdu_t_list_remove(void* dll, void* node) {
    DoublyLinkedList* dll_ptr = (DoublyLinkedList*)dll;
    removeNode(dll_ptr, (Node*)node);
}

void lib_nfa_crc_indication_pdu_t_list_print(void* dll) {
    DoublyLinkedList* dll_ptr = (DoublyLinkedList*)dll;
    printList(dll_ptr);
}
