	err := dna.storageProcessor.AddDataPoint(r.Body)
	if err != nil {
		http.Error(w, "Error adding data point", 500)
		return
	}
	w.WriteHeader(201)
}

func (dna *DynamicNetworkAnalyzer) GetChartData(w http.ResponseWriter, r *http.Request) {
	// Handle GET requests for chart data
	data, err := dna.storageProcessor.GetChartData()
	if err != nil {
		http.Error(w, "Error retrieving chart data", 500)
		return
	}
	json.NewEncoder(w).Encode(data)
}

func (dna *DynamicNetworkAnalyzer) UpdateModel(w http.ResponseWriter, r *http.Request) {
	// Handle PUT requests for updating the machine learning model
	err := dna.machineLearning.UpdateModel(r.Body)
	if err != nil {
		http.Error(w, "Error updating model", 500)
		return
	}
	w.WriteHeader(200)
}

func (dna *DynamicNetworkAnalyzer) main() {
