// Define a structure for the doubly-linked list node
typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct Node* prev;
    struct Node* next;
} Node;

// Define the doubly-linked list itself
typedef struct {
    Node* head;
    Node* tail;
} DoublyLinkedList;

// Function to create a new node with given data
Node* create_node(NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* new_node = (Node*) malloc(sizeof(Node));
    new_node->data = data;
    new_node->prev = NULL;
    new_node->next = NULL;
    return new_node;
}

// Function to add a node at the beginning of the list
void add_at_beginning(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* new_node = create_node(data);
    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        new_node->next = list->head;
        list->head->prev = new_node;
        list->head = new_node;
    }
}

// Function to add a node at the end of the list
void add_at_end(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* new_node = create_node(data);
    if (list->tail == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        new_node->prev = list->tail;
        list->tail->next = new_node;
        list->tail = new_node;
    }
}

// Function to remove a node from the list
void remove_node(DoublyLinkedList* list, Node* node) {
    if (node == NULL) return;

    if (node->prev != NULL) {
        node->prev->next = node->next;
    } else {
        list->head = node->next;
    }

    if (node->next != NULL) {
        node->next->prev = node->prev;
    } else {
        list->tail = node->prev;
    }

    free(node);
}

// Function to print the contents of the doubly-linked list
void print_list(DoublyLinkedList* list) {
    Node* current = list->head;
    while (current != NULL) {
        printf("%d ", current->data); // Add your data printing logic here...
        current = current->next;
    }
    printf("\n");
}

