import logging.config
from flask import Flask, request, jsonify
from flasgger import Swagger
import redis
import rq
import os
import json
from datetime import datetime

# Define the configuration manager's settings
REDIS_HOST = 'localhost'
REDIS_PORT = 6379
REDIS_DB = 0
MAX_WORKERS = 10

app = Flask(__name__)
app.config["SWAGGER"] = {"title": "Distributed Logging System Configuration Manager", "description": "Configuration Manager for Distributed Logging System"}
Swagger(app)

# Initialize the Redis connection pool and worker queue
redis_client = redis.ConnectionPool(host=REDIS_HOST, port=REDIS_PORT, db=REDIS_DB)
worker_queue = rq.Queue(connection=redis_client)

@app.route('/config', methods=['GET'])
def get_config():
    # Retrieve configuration from Redis
    config = {}
    try:
        for key in ["LOG_LEVEL", "DESTINATION"]:
            value = redis_client.get(key).decode('utf-8')
            if value is None:
                continue
            config[key] = json.loads(value)
    except Exception as e:
        logging.error(f"Failed to retrieve configuration: {e}")
        return jsonify({'error': 'Configuration retrieval failed'}), 500

    # Return the configuration in JSON format
    return jsonify(config)

@app.route('/config', methods=['POST'])
def update_config():
    try:
        data = request.get_json()
        if not isinstance(data, dict):
            return jsonify({'error': 'Invalid request body'}), 400

        config_key = "LOG_CONFIG"
        redis_client.set(config_key, json.dumps(data))
        worker_queue.enqueue('update_config', data)

        # Return a success response
        return jsonify({'message': f"Configuration updated successfully"}), 200

    except Exception as e:
        logging.error(f"Failed to update configuration: {e}")
        return jsonify({'error': 'Configuration update failed'}), 500

@app.route('/config/rollback', methods=['POST'])
def rollback_config():
    try:
        data = request.get_json()
        if not isinstance(data, dict):
            return jsonify({'error': 'Invalid request body'}), 400

        config_key = "LOG_CONFIG"
        redis_client.delete(config_key)

        # Return a success response
        return jsonify({'message': f"Configuration rolled back successfully"}), 200

    except Exception as e:
        logging.error(f"Failed to roll back configuration: {e}")
        return jsonify({'error': 'Configuration rollback failed'}), 500

if __name__ == '__main__':
    app.run(debug=True)
