// Custom data structure to hold record information
typedef struct {
    int key;
    long offset;
    void* context;
} Record;

// Hash table implementation using a custom hash function and chaining for collision resolution
typedef struct {
    size_t bucket_count;
    Record** buckets;
} HashTable;

HashTable* init_hash_table(size_t bucket_count);
void free_hash_table(HashTable* ht);
int hash_function(int key, size_t bucket_count);
Record* lookup_record(HashTable* ht, int key);
int insert_record(HashTable* ht, Record* record);
int remove_record(HashTable* ht, int key);

// Data persistence layer using a custom binary file format
typedef struct {
    FILE* file;
    HashTable* records;
} PersistenceLayer;

PersistenceLayer* init_persistence_layer(const char* filename);
void free_persistence_layer(PersistenceLayer* pl);
int serialize_records(PersistenceLayer* pl, const char* filename);
int deserialize_records(PersistenceLayer* pl, const char* filename);

// Concurrency management using pthreads
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

// Thread-safe data access and manipulation functions
Record* get_record(HashTable* ht, int key);
void update_record(HashTable* ht, Record* record);
void remove_record_thread_safe(HashTable* ht, int key);

// Error handling and logging mechanisms
#define LOG_ERROR(fmt, ...) printf("[ERROR] " fmt "\n", ##__VA_ARGS__)
#define LOG_INFO(fmt, ...) printf("[INFO] " fmt "\n", ##__VA_ARGS__)

int main() {
    // Initialize persistence layer and hash table
    PersistenceLayer* pl = init_persistence_layer("data.bin");
    HashTable* ht = init_hash_table(1024);

    // Perform record operations concurrently
    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, worker_thread, (void*)ht);
    }

    // Wait for all threads to finish
    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up resources
    free_hash_table(ht);
    free_persistence_layer(pl);

    return 0;
}

// Worker thread function
void* worker_thread(void* arg) {
    HashTable* ht = (HashTable*)arg;

    // Perform record operations concurrently and safely
    for (int i = 0; i < 10000; i++) {
        int key = rand() % 1000;
        Record* record = get_record(ht, key);
        if (record != NULL) {
            update_record(ht, record);
        } else {
            // Handle record not found
            LOG_ERROR("Record not found: %d", key);
        }
    }

    return NULL;
}

// Example usage: insert and retrieve records concurrently
void test_concurrency() {
    PersistenceLayer* pl = init_persistence_layer("data.bin");
    HashTable* ht = init_hash_table(1024);

    // Insert records concurrently
    pthread_t threads[5];
    for (int i = 0; i < 5; i++) {
        pthread_create(&threads[i], NULL, worker_thread_insert, (void*)ht);
    }

    // Wait for all threads to finish
    for (int i = 0; i < 5; i++) {
        pthread_join(threads[i], NULL);
    }

    // Retrieve and update records concurrently
