// Define a GUI class to handle graphical user interface operations
class GUI {
public:
    // Constructor to initialize the GUI
    GUI() : running_(true), thread_() {}

    // Start the GUI thread
    void start() {
        if (!running_) {
            std::thread t([this]() { run(); });
            thread_ = t;
        }
    }

    // Stop the GUI thread
    void stop() {
        running_ = false;
        if (thread_.joinable()) {
            thread_.join();
        }
    }

private:
    bool running_;
    std::thread thread_;

    // Run the GUI thread
    void run() {
        while (running_) {
            // Perform GUI operations here
            std::cout << "GUI is running..." << std::endl;
            // Simulate concurrency and resource management by sleeping for a few seconds
            std::this_thread::sleep_for(std::chrono::seconds(5));
        }
    }
};

int main() {
    // Create a GUI object and start the thread
    GUI gui;
    gui.start();

    // Perform some operations outside the GUI thread
    std::cout << "Performing operations outside the GUI thread..." << std::endl;

    // Stop the GUI thread after 10 seconds
    std::this_thread::sleep_for(std::chrono::seconds(10));
    gui.stop();

    return 0;
}
