    int RNTI;
    char CRC_INDICATION_REL8_TAG[20];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to initialize and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* init_crc_indication_pdu_array(int n, float crc_error_rate) {
    // Initialize error handling variables
    int err = 0;
    char log_str[1024] = {0};

    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* arr = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if(arr == NULL) {
        err = 1;
        sprintf(log_str, "Memory allocation failed. Returning null.\n");
        // Log the error
        printf("%s", log_str);
    }

    for(int i = 0; i < n; i++) {
        arr[i].RX_UE_INFORMATION_TAG = i;
        arr[i].RNTI = i;

        // Simulate CRC error rate based on crc_error_rate
        if(rand() % 100 <= (int)(crc_error_rate * 100)) {
            strcpy(arr[i].CRC_INDICATION_REL8_TAG, "ERROR");
            arr[i].CRCFLAG = 1; // Set CRC flag to indicate error
        } else {
            sprintf(arr[i].CRC_INDICATION_REL8_TAG, "NO_ERROR_%d", i);
            arr[i].CRCFLAG = 0; // Clear CRC flag if no error
        }
    }

    return arr;
}

// Function to free the array of NFAPI_CRC_INDICATION_PDU_T structures
void free_crc_indication_pdu_array(NFAPI_CRC_INDICATION_PDU_T* arr, int n) {
    for(int i = 0; i < n; i++) {
        // Automatic deallocation during library shutdown
        free(arr[i].CRC_INDICATION_REL8_TAG);
    }
    free(arr);
}

int main() {
    int n = 10;
    float crc_error_rate = 0.1f;

    NFAPI_CRC_INDICATION_PDU_T* arr = init_crc_indication_pdu_array(n, crc_error_rate);

    if(arr == NULL) {
        printf("Error initializing array.\n");
        return 1; // Exit with error
    }

    for(int i = 0; i < n; i++) {
        printf("RX_UE_INFORMATION_TAG: %d\nRNTI: %d\nCRC_INDICATION_REL8_TAG: %s\nCRCFLAG: %d\n", arr[i].RX_UE_INFORMATION_TAG, arr[i].RNTI, arr[i].CRC_INDICATION_REL8_TAG, arr[i].CRCFLAG);
    }

    free_crc_indication_pdu_array(arr, n);

    return 0;
}

