    private Map<String, Cipher> ciphers = new HashMap<>();
    private Cache cache = new Cache();
    private Logger logger = Logger.getLogger(CryptographicServiceLayer.class);

    public CryptographicServiceLayer() {
        loadKeyManagers();
        loadCiphers();
    }

    public void addKeyManager(String keyManagerName) {
        try {
            KeyManager keyManager = (KeyManager) Class.forName("com.example." + keyManagerName).newInstance();
            keyManagers.put(keyManagerName, keyManager);
        } catch (ClassNotFoundException e) {
            logger.error("Failed to load key manager: " + e.getMessage());
        }
    }

    public void addCipher(String cipherName) {
        try {
            Cipher cipher = (Cipher) Class.forName("com.example." + cipherName).newInstance();
            ciphers.put(cipherName, cipher);
        } catch (ClassNotFoundException e) {
            logger.error("Failed to load cipher: " + e.getMessage());
        }
    }

    public byte[] encrypt(String keyManagerName, String cipherName, byte[] data) {
        try {
            KeyManager keyManager = keyManagers.get(keyManagerName);
            Cipher cipher = ciphers.get(cipherName);

            if (keyManager == null || cipher == null) {
                return null;
            }

            Key key = keyManager.getKey();
            return cipher.encrypt(data, key);
        } catch (Exception e) {
            logger.error("Encryption failed: " + e.getMessage());
            return null;
        }
    }

    public byte[] decrypt(String keyManagerName, String cipherName, byte[] data) {
        try {
            KeyManager keyManager = keyManagers.get(keyManagerName);
            Cipher cipher = ciphers.get(cipherName);

            if (keyManager == null || cipher == null) {
                return null;
            }

            Key key = keyManager.getKey();
            return cipher.decrypt(data, key);
        } catch (Exception e) {
            logger.error("Decryption failed: " + e.getMessage());
            return null;
        }
