// Function to generate and store CRC indications
void* generate_and_store_crc_indications(int N, int& allocated) {
    void* result = nullptr;
    try {
        // Initialize the vector of structures
        std::vector<NFAPI_CRC_INDICATION_PDU_T> crcIndications(N);

        // Generate random RNTI and set CRCFLAG randomly
        for (int i = 0; i < N; ++i) {
            crcIndications[i].RX_UE_INFORMATION_TAG = i;
            crcIndications[i].RNTI = "RNTI_" + std::to_string(i);
            crcIndications[i].CRCFLAG = rand() % 2 == 1;
        }

        // Store the generated structures
        result = &crcIndications[0];
    } catch (const std::exception& e) {
        // Log error and retry after exponential backoff
        std::this_thread::sleep_for(std::chrono::milliseconds(500));
        generate_and_store_crc_indications(N, allocated);
    }

    return result;
}

int main() {
    int N = 1000; // Number of structures to generate

    // Initialize the random number generator
    srand(time(nullptr));

    int allocated = 0;

    void* result = generate_and_store_crc_indications(N, allocated);

    if (result) {
        std::cout << "Generated and stored " << N << " CRC indications successfully.\n";
    } else {
        std::cerr << "Failed to generate and store CRC indications.\n";
    }

    return 0;
}
