// Function to initialize the queue and thread pool
void init_process_crc_indications() {
    // Initialize the queue
    queue = (struct Queue*)malloc(sizeof(struct Queue));
    queue->size = 0;
    queue->max_size = MAX_QUEUE_SIZE;

    // Create a semaphore for synchronization
    sem_init(&queue_sem, 1, 1);

    // Create thread pool with max threads
