typedef struct {
    int RX_UE_INFORMATION_TAG;
    char RNTI[10];
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int generateAndPersistNfarpcPDUs(int N, int maxExecutionTimeMs, float memoryThresholdKB) {
    // Initialize database connection
    MYSQL *conn = mysql_init(NULL);
    if (!mysql_real_connect(conn, "localhost", "username", "password", "database_name", 0, NULL, 0)) {
        fprintf(stderr, "%s\n", mysql_error(conn));
        return -1;
    }

    // Start timer to track execution time
    clock_t start = clock();

    // Initialize memory allocation for PDUs
    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdus) {
        return -1;
    }

    int i;
    for (i = 0; i < N; i++) {
        // Generate unique RX_UE_INFORMATION_TAG, RNTI and CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
        pdus[i].RX_UE_INFORMATION_TAG = i;
        strcpy(pdus[i].RNTI, "RNTI_");
        pdus[i].CRC_INDICATION_REL8_TAG = (i % 10) + 1;
        pdus[i].CRCFLAG = rand() % 2;

        // Insert PDU into database
        char query[1024];
        sprintf(query, "INSERT INTO pdus (RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, CRCFLAG) VALUES (%d, '%s', %d, %d)", 
            pdus[i].RX_UE_INFORMATION_TAG, pdus[i].RNTI, pdus[i].CRC_INDICATION_REL8_TAG, pdus[i].CRCFLAG);
        mysql_query(conn, query);

        if (mysql_errno(conn)) {
            fprintf(stderr, "%s\n", mysql_error(conn));
            return -1;
        }
    }

    // Commit transaction and free memory
    if (!mysql_commit(conn)) {
        fprintf(stderr, "%s\n", mysql_error(conn));
        return -1;
    }
    free(pdus);

    // Check execution time against threshold
    clock_t end = clock();
    float executionTimeMs = (float)(end - start) / CLOCKS_PER_SEC * 1000.0;
    if (executionTimeMs > maxExecutionTimeMs) {
        return -1;
    }

    // Close database connection and return success status
    mysql_close(conn);
    return 0;
}
