    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_PDU;

// Define the database connection pool manager structure
typedef struct {
    sqlite3* db;
    int connections;
    int max_connections;
    int idle_timeout;
} DB_POOL_MANAGER;

// Initialize the database connection pool manager
void init_db_pool_manager(DB_POOL_MANAGER* pool) {
    // Initialize the database connection
    pool->db = NULL;
    pool->connections = 0;
    pool->max_connections = 5; // adjust this value based on your needs
    pool->idle_timeout = 60 * 1000; // 1 minute
}

// Create a new database connection and add it to the pool
int create_db_connection(DB_POOL_MANAGER* pool) {
    int rc;
    sqlite3* db;
    rc = sqlite3_open_v2("db_name.db", &db);
    if (rc != SQLITE_OK) {
        // Handle the error
        return 1;
    }
    pool->connections++;
    pool->db = db;
    return 0;
}

// Release a database connection from the pool
int release_db_connection(DB_POOL_MANAGER* pool) {
    int rc;
    sqlite3_close(pool->db);
    pool->connections--;
    pool->db = NULL;
    return 0;
}

// Generate an NFAPI PDU with unique RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
NFAPI_PDU* generate_nfapi_pdu() {
    // Generate a random PDU with distinct values
    int i;
    NFAPI_PDU* pdu = (NFAPI_PDU*)malloc(sizeof(NFAPI_PDU));
    for (i = 0; i < N; i++) {
        pdu->RX_UE_INFORMATION_TAG = rand();
        pdu->RNTI = rand();
        pdu->CRC_INDICATION_REL8_TAG = rand();
        pdu->CRCFLAG = rand() % 2;
    }
    return pdu;
}

// Persist the generated PDUs to the database
int persist_pdu(NFAPI_PDU* pdu, DB_POOL_MANAGER* pool) {
    int rc;
    sqlite3_stmt* stmt;
    char* query = "INSERT INTO nfapi_pdu (RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, CRCFLAG) VALUES (?, ?, ?, ?)";
    // Prepare the statement
    rc = sqlite3_prepare_v2(pool->db, query, strlen(query), &stmt, NULL);
    if (rc != SQLITE_OK) {
        // Handle the error
        return 1;
    }
    // Bind the PDU values to the statement
    sqlite3_bind_int(stmt, 1, pdu->RX_UE_INFORMATION_TAG);
    sqlite3_bind_int(stmt, 2, pdu->RNTI);
    sqlite3_bind_int(stmt, 3, pdu->CRC_INDICATION_REL8_TAG);
    sqlite3_bind_int(stmt, 4, pdu->CRCFLAG);
    // Execute the statement
    rc = sqlite3_step(stmt);
    if (rc != SQLITE_DONE) {
        // Handle the error
        return 1;
    }
    // Release the statement
    sqlite3_finalize(stmt);
    return 0;
}

// Read PDUs from the database and store them in a memory cache
int read_pdu_from_cache(DB_POOL_MANAGER* pool, NFAPI_PDU** pdu_cache) {
    int rc;
