class PacketManager {
public:
    void addPacket(TX_PACKET packet) {
        // handle duplicate sequence numbers
        if (packets_.count(packet.sequenceNumber)) {
            handleDuplicateSequenceNumber(packet);
            return;
        }
        packets_.emplace(packet.sequenceNumber, packet);

        // notify the queue to update the packet list
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.notify_one();
    }

    void removePacket(int sequenceNumber) {
        auto it = packets_.find(sequenceNumber);
        if (it != packets_.end()) {
            packets_.erase(it);
        }
    }

    TX_PACKET getPacket(int sequenceNumber) {
        return packets_.at(sequenceNumber);
    }

private:
    std::map<int, TX_PACKET> packets_;
    std::list<TX_PACKET> queue_;

    std::mutex mutex_;
    std::condition_variable cv_;

    void handleDuplicateSequenceNumber(TX_PACKET packet) {
        // conflict resolution strategy
        // for now, just log the issue
        LOG_WARNING("Duplicate sequence number: " << packet.sequenceNumber);
