    private readonly HashSet<string> _configuredApis = new HashSet<string>();

    public async Task<List<Dictionary<string, string>>> GetConfigurationsAsync(string xmlFilePath)
    {
        try
        {
            XDocument xmlDoc = await LoadXmlFileAsync(xmlFilePath);
            if (xmlDoc == null) return new List<Dictionary<string, string>>();

            var configurations = new List<Dictionary<string, string>>();
            foreach (XElement node in xmlDoc.Descendants())
            {
                if (!FilterNode(node)) continue;

                Dictionary<string, string> config = new Dictionary<string, string>();
                foreach (XAttribute attribute in node.Attributes())
                {
                    config.Add(attribute.Name.LocalName, attribute.Value);
                }

                configurations.Add(config);
            }

            return configurations;
        }
        catch (Exception ex)
        {
            // Log the error
            Console.WriteLine($"Error processing configuration: {ex.Message}");
            throw;
        }
    }

    private async Task<XDocument> LoadXmlFileAsync(string filePath)
    {
        try
        {
            XDocument xmlDoc = XDocument.Load(filePath);
            return xmlDoc;
        }
        catch (Exception ex)
        {
            // Log the error and return null if malformation or IO error occurs
            Console.WriteLine($"Error loading XML file: {ex.Message}");
            return null;
        }
