class UserAccount {
    private $db;
    private $api;

    public function __construct($db, $api) {
        $this->db = $db;
        $this->api = $api;
    }

    public function createOrUpdateUserAccount($_REQUEST) {
        if (isset($_REQUEST['id'])) {
            // Update user account
            $this->updateUserAccount($_REQUEST);
        } else {
            // Create new user account
            $this->createNewUserAccount($_REQUEST);
        }
    }

    private function updateUserAccount($_REQUEST) {
        $user_id = $_REQUEST['id'];
        $name = $_REQUEST['name'];
        $email = $_REQUEST['email'];
        $password = $_REQUEST['password'];

        // Validate input parameters
        if (!isset($user_id) || !isset($name) || !isset($email) || !isset($password)) {
            throw new Exception('Invalid request');
        }

        // Update user account in database and API
        $this->db->updateUserAccount($user_id, $name, $email);
        $this->api->updateUserAccount($user_id, $name, $email);

        return true;
    }

    private function createNewUserAccount($_REQUEST) {
        $name = $_REQUEST['name'];
        $email = $_REQUEST['email'];
        $password = $_REQUEST['password'];

        // Validate input parameters
        if (!isset($name) || !isset($email) || !isset($password)) {
            throw new Exception('Invalid request');
        }

        // Create new user account in database and API
        $user_id = $this->db->createNewUserAccount($name, $email);
        $this->api->createNewUserAccount($user_id, $name, $email);

        return true;
    }
}
