// Define the structure for TX_PACKET
typedef struct {
    char transmission_tag[16];
    int sequence_number;
    int data_size;
} TX_PACKET;

// Define a linked list node for packet management
typedef struct Node {
    TX_PACKET packet;
    struct Node* next;
} Node;

// Create a new linked list node
Node* create_node(TX_PACKET packet) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->packet = packet;
    new_node->next = NULL;
    return new_node;
}

// Insert a new packet into the linked list based on sequence number
void insert_packet(Node** head, TX_PACKET* new_packet) {
    Node* current = *head;
    Node* previous = NULL;
    while (current && current->packet.sequence_number < new_packet->sequence_number) {
        previous = current;
        current = current->next;
    }
    if (!previous) {
        *head = create_node(*new_packet);
    } else {
        Node* new_node = create_node(*new_packet);
        new_node->next = current;
        previous->next = new_node;
    }
}

// Delete a packet from the linked list based on sequence number
void delete_packet(Node** head, int sequence_number) {
    Node* current = *head;
    Node* previous = NULL;
    while (current && current->packet.sequence_number != sequence_number) {
        previous = current;
        current = current->next;
    }
    if (previous) previous->next = current->next;
    else *head = current->next;
    free(current);
}

// Search for a packet in the linked list based on sequence number
TX_PACKET* find_packet(Node* head, int sequence_number) {
    Node* current = head;
    while (current && current->packet.sequence_number != sequence_number)
        current = current->next;
    return &current->packet;
}

// Define a hash table for packet management
typedef struct {
    int size;
    Node** buckets;
} PacketHashTable;

// Create a new packet hash table
PacketHashTable* create_packet_hash_table(int size) {
    PacketHashTable* new_hash_table = (PacketHashTable*)malloc(sizeof(PacketHashTable));
    if (!new_hash_table) return NULL;
    new_hash_table->size = size;
    new_hash_table->buckets = (Node**)calloc(size, sizeof(Node*));
    for (int i = 0; i < size; i++) {
        new_hash_table->buckets[i] = NULL;
    }
    return new_hash_table;
}

// Insert a new packet into the hash table based on sequence number
void insert_packet_hash(PacketHashTable* hash_table, TX_PACKET* new_packet) {
    int index = new_packet->sequence_number % hash_table->size;
    Node* current = hash_table->buckets[index];
    while (current && current->packet.sequence_number <= new_packet->sequence_number)
        current = current->next;
    if (!current) {
        hash_table->buckets[index] = create_node(*new_packet);
    } else {
        Node* new_node = create_node(*new_packet);
        new_node->next = current;
        current->next = new_node;
    }
}

// Delete a packet from the hash table based on sequence number
void delete_packet_hash(PacketHashTable* hash_table, int sequence_number) {
