    public DistributedCacheManager() {
        // Initialize thread pool
        ExecutorService executor = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
        // Start thread pool
        for (int i = 0; i < THREAD_POOL_SIZE; i++) {
