    bool status;
    std::vector<std::string> connectionHistory;

    // Constructor
    Device(const std::string& _id, const std::string& _location, bool _status) 
        : id(_id), location(_location), status(_status), connectionHistory() {}

    // Method to update device status
    void setStatus(bool _status) {
        this->status = _status;
    }

    // Method to add connection history entry
    void addConnectionHistory(const std::string& _entry) {
        this->connectionHistory.push_back(_entry);
    }
};

class RegistryService {
private:
    std::map<std::string, Device> devices; // Map of IoT devices
    std::mutex mtx; // Mutex for thread safety
    std::condition_variable cv; // Condition variable for synchronization

public:
    // Method to add a new device
    void addDevice(const std::string& deviceId, const std::string& location, bool status) {
        std::unique_lock<std::mutex> lock(mtx);
        Device device(deviceId, location, status);
        devices[deviceId] = device;
        cv.notify_all();
    }

    // Method to update a device's status
    void updateDeviceStatus(const std::string& deviceId, bool status) {
        std::unique_lock<std::mutex> lock(mtx);
