            device.setStatus(status);
        }
    }

    // Method to get a device's connection history
    std::vector<std::string> getDeviceConnectionHistory(const std::string& deviceId) {
        std::unique_lock<std::mutex> lock(mtx);
        if (devices.find(deviceId) != devices.end()) {
            Device& device = devices[deviceId];
            return device.connectionHistory;
        }
        return {};
    }

