    LTE_PHY_RX_FRAME_LIB() : stop(false) {}

    void addFrame(LTE_PHY_RX_FRAME_T frame) {
        std::unique_lock<std::mutex> lock(mutex);
        frames.push_back(frame);
    }

    void startProcessing() {
        threadPool.reserve(4); // adjust the number of threads based on available resources
        for (int i = 0; i < 4; ++i) {
            threadPool.emplace_back([this]() {
                processFrames();
            });
        }
    }

    void stopProcessing() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        cv.notify_all();
        for (auto& t : threadPool) {
            t.join();
        }
        threadPool.clear();
    }

private:
    void processFrames() {
        while (!stop) {
            LTE_PHY_RX_FRAME_T frame;
            std::unique_lock<std::mutex> lock(mutex);
            if (!frames.empty()) {
                frame = frames.back();
                frames.pop_back();
