public:
    LTE_UERadioResourceManager(size_t capacityLimit)
        : _ueSessions(), _capacityLimit(capacityLimit), _mutex(), _condVar() {}

    void addUESession(const std::string& ueId) {
        if (_ueSessions.size() >= _capacityLimit) {
            throw std::runtime_error("Maximum UE session capacity exceeded");
        }
        _ueSessions[ueId] = UE_Session();
    }

    void removeUESession(const std::string& ueId) {
        if (!_ueSessions.erase(ueId)) {
            throw std::runtime_error("UE session not found");
        }
    }

    void updateULCCCHMessages(const std::string& ueId, const std::queue<LTE_UL_CCCH_MESSAGE>& messages) {
        auto it = _ueSessions.find(ueId);
        if (it == _ueSessions.end()) {
            throw std::runtime_error("UE session not found");
        }
        it->second.messages = messages;
    }

    size_t getTotalActiveUESessions() const {
        return _ueSessions.size();
    }

private:
    struct UE_Session {
        std::queue<LTE_UL_CCCH_MESSAGE> messages;
    };

    std::map<std::string, UE_Session> _ueSessions;
    size_t _capacityLimit;
    std::mutex _mutex;
    std::condition_variable _condVar;

public: // For testing purposes
