#include <curl/curl.h>

typedef struct {
    int rnti;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* processNFAPIData(int numEntries, char* key, char* iv) {
    // Initialize result array
    NFAPI_CRC_INDICATION_PDU_T* result = malloc(numEntries * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Populate RX_UE_INFORMATION_TAG structures
    for (int i = 0; i < numEntries; i++) {
        // Fetch additional UE information from external REST API
        CURL* curl;
        CURLcode res;
        char json[1024];
        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
        if(curl) {
            curl_easy_setopt(curl, CURLOPT_URL, "https://example.com/ue_info");
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_memory);
            curl_easy_setopt(curl, CURLOPT_WRITEDATA, json);
            res = curl_easy_perform(curl);
            if(res != CURLE_OK) {
                printf("cURL error: %s\n", curl_easy_strerror(res));
                // Retry with exponential backoff
                for (int j = 0; j < 5; j++) {
                    sleep pow(2, j);
                    res = curl_easy_perform(curl);
                    if(res == CURLE_OK) break;
                }
            }
            curl_easy_cleanup(curl);
        }

        // Populate RX_UE_INFORMATION_TAG structure
        result[i].rnti = ...; // populate RNTI field
        result[i].crcflag = rand() % 2; // set CRCFLAG randomly

        // Decrypt Base64-encoded message using Triple DES encryption
        char* encrypted_msg = base64_decode(json);
        if (encrypted_msg) {
            unsigned char decrypted_msg[1024];
            int len = des_decrypt(key, iv, encrypted_msg, strlen(encrypted_msg), decrypted_msg);
            free(encrypted_msg);
            // Process decrypted message
        } else {
            printf("Error decrypting message\n");
        }
    }

    return result;
}

// Helper function to write JSON response to memory buffer
size_t write_memory(void*ptr, size_t size, size_t nmemb, void*data) {
    char* json = (char*)data;
    memcpy(json, ptr, size * nmemb);
    return size * nmemb;
}

// Helper function to decrypt message using Triple DES encryption
int des_decrypt(char* key, char* iv, char* encrypted_msg, int len, unsigned char* decrypted_msg) {
    // Initialize DES context
    DES_key_schedule ks;
    if (!DES_setkey_cbc(&ks, (unsigned char*)key, strlen(key))) {
        printf("Error setting DES key\n");
        return 0;
    }

    // Decrypt message
    int offset = 0;
    while (offset < len) {
        int block_len = MIN_BLOCK_SIZE;
        if (offset + block_len > len) block_len = len - offset;
        memcpy(decrypted_msg + offset, encrypted_msg + offset, block_len);
        offset += block_len;
    }

    return len;
}

// Helper function to base64 decode a message
char* base64_decode(char* encoded_msg) {
    int len = strlen(encoded_msg);
    char* decoded_msg = malloc(len * 3 / 4 + 1);
    base64_decoded(encoded_msg, len, decoded_msg);
    return decoded_msg;
}

// Helper function to perform base64 decoding
void base64_decoded(char* encoded_msg, int len, char* decoded_msg) {
