#include <queue>
#include <mutex>
#include <condition_variable>
#include <thread>
#include <iostream>

class DynamicEventManager {
public:
    void enqueue(const CustomNetworkEvent& event) {
        std::unique_lock<std::mutex> lock(mutex_);
        queue_.push(event);
        cv_.notify_one();
    }

    bool dequeue(CustomNetworkEvent& event) {
        std::unique_lock<std::mutex> lock(mutex_);
        while (queue_.empty()) {
            cv_.wait(lock, [this] { return !queue_.empty(); });
        }
        event = queue_.front();
        queue_.pop();
        return true;
    }

private:
    std::queue<CustomNetworkEvent> queue_;
    std::mutex mutex_;
    std::condition_variable cv_;
};

class CustomNetworkEvent {
public:
    int eventID;
    long timestamp;
    std::string source;
    int priority;
};
