class UserSession {
public:
    std::string sessionID;
    std::string authToken;
    time_t loginTimestamp;
    std::string deviceInfo;
    std::string networkStats;
    std::map<std::string, std::any> configSettings;
};

class SessionManager {
private:
    std::mutex mtx;
    std::condition_variable cv;
    std::map<UserSession*, bool> sessions;
    int refreshInterval;

public:
    SessionManager(int refreshInterval) : refreshInterval(refreshInterval) {}

    void addSession(UserSession* session) {
        mtx.lock();
        sessions[session] = true;
        mtx.unlock();
    }

    void removeSession(UserSession* session) {
        mtx.lock();
        if (sessions.find(session) != sessions.end()) {
            sessions.erase(session);
        }
        mtx.unlock();
    }

    std::vector<UserSession*> getSessions() {
        std::vector<UserSession*> result;
        mtx.lock();
        for (auto& pair : sessions) {
            result.push_back(pair.first);
        }
        mtx.unlock();
        return result;
    }

    void updateSessions() {
        while (true) {
            std::this_thread::sleep_for(std::chrono::milliseconds(refreshInterval));
            mtx.lock();
            for (auto& pair : sessions) {
                // update session data here
            }
            mtx.unlock();
        }
    }

    bool isSessionValid(UserSession* session) {
        mtx.lock();
        if (sessions.find(session) != sessions.end()) {
            return true;
        }
        mtx.unlock();
        return false;
    }
};

