            webSocketServer.start("localhost", 8080);
        } catch (IOException e) {
            logger.error("Failed to start WebSocket server", e);
        }

        // Start processing pipelines in parallel
        executorService.submit(() -> {
            for (RealtimeProcessingPipeline pipeline : pipelines) {
                pipeline.process();
            }
        });
    }

