```java
package com.example.eventprocessing;

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class EventProcessor {
    private ExecutorService executor = Executors.newCachedThreadPool();
    private List<EventTransformer> transformers = new ArrayList<>();
    private List<DataSink> sinks = new ArrayList<>();

    public void addTransformer(EventTransformer transformer) {
        this.transformers.add(transformer);
    }

    public void removeTransformer(EventTransformer transformer) {
        this.transformers.remove(transformer);
    }

    public void addSink(DataSink sink) {
        this.sinks.add(sink);
    }

    public void removeSink(DataSink sink) {
        this.sinks.remove(sink);
    }

    public void processEvent(Event event) {
        executor.submit(() -> {
            for (EventTransformer transformer : transformers) {
                event = transformer.transform(event);
            }
            for (DataSink sink : sinks) {
                sink.send(event);
            }
        });
    }
}

interface EventTransformer {
    Event transform(Event event);
}

class IoTDeviceTransformer implements EventTransformer {
    @Override
    public Event transform(Event event) {
        // implement IoT device-specific transformation logic here
        return event;
    }
}

class WebAPITransformer implements EventTransformer {
