// Function to fetch a list of integers from an external data source
int* fetchData(int limit, int* count) {
    // Fetch the data and store it in the integer array
    int* data = (int*)malloc(limit * sizeof(int));
    *count = 0;

    while (*count < limit) {
        // Read data from the external source
        int value;
        if (fscanf(stdin, "%d", &value) != 1) {
            break; // Handle malformed data or end-of-file
        }
        data[*count] = value;
        (*count)++;
    }

    return data;
}

// Function to find and print the largest integer in the array
void printLargest(int* data, int count) {
    if (count == 0) {
        printf("Empty list\n");
    } else {
        int max = data[0];
        for (int i = 1; i < count; i++) {
            if (data[i] > max) {
                max = data[i];
            }
        }
        printf("Largest integer: %d\n", max);
    }
}

int main() {
    int limit = 100;
    int* data = fetchData(limit, &count);

    // Handle intermittent failures and malformed data gracefully
    if (count == 0) {
        free(data);
        return 1; // Handle error
    }

    printLargest(data, count);

    free(data);
    return 0;
}
