    pthread_mutex_t sensor_count_lock = PTHREAD_MUTEX_INITIALIZER;
    int* sensor_count = (int*)malloc(sizeof(int));
    *sensor_count = 0;

    return (void*)sensors;
}

// Function to free allocated memory and clean up resources
void cleanup(void* data) {
    EnvironmentalSensor** sensors = (EnvironmentalSensor**)data;
    for (int i = 0; i < MAX_SENSOR_NODES; i++) {
        if (sensors[i] != NULL) {
            free(sensors[i]);
        }
    }
    free(sensors);
}
