use std::fs;
use std::path::{Path, PathBuf};
use std::process::Command;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::time::{Duration, Instant};

struct Event {
    timestamp: u64,
    event_type: String,
    priority: u8,
}

fn main() {}

// Calculate the time taken and resident set size of a subprocess
async fn measure_rust_compiler_time_and_memory(path: &Path) -> Result<(u64, u64), std::io::Error> {
    let start = Instant::now();
    let output = Command::new("rustc")
        .arg("-O")
        .arg("--emit=llvm-ir")
        .arg("--crate-type=lib")
        .arg(path)
        .output()
        .await?
    ;

    let end = Instant::now();
    let time_taken = (end - start).as_millis() as u64;

    let mut rsz: AtomicUsize = AtomicUsize::new(0);
    fs::read_dir(path.parent().unwrap())?.flatten().for_each(|f| {
        if let Ok(dir_entry) = f {
            match dir_entry.path().extension() {
                Some(ext) => {
                    if ext.to_string_lossy().to_lowercase().contains("so") || 
                       ext.to_string_lossy().to_lowercase().contains("dll") {
                        rsz.fetch_add(1, Ordering::SeqCst);
                    }
                }
                None => {}
            }
        }
    });

    let resident_set_size = rsz.load(Ordering::SeqCst) as u64;

    Ok((time_taken, resident_set_size))
}
