// Node.js Service (node-logger.js)
const childProcess = require('child_process');
const net = require('net');

class SystemLogger {
  constructor() {
    this.cLogHandler = new CLogHandler();
    this.metrics = [];
  }

  async logSystemMetrics() {
    const metrics = await Promise.all([
      childProcess.execSync(`top -b -n 1 | grep "Cpu(s)"`).toString(),
      childProcess.execSync(`free -m | awk 'NR==2 {print $3}'`).toString(),
      childProcess.execSync(`df -h . | awk 'NR==3 {print $5}'`).toString(),
    ]);

    this.metrics = metrics.map((metric) => {
      const data = JSON.parse(metric);
      return { ...data, timestamp: Date.now() };
    });

    await this.cLogHandler.processMetrics(this.metrics);
  }
}

class CLogHandler {
  constructor() {
    this.logFile = 'system_metrics.log';
  }

  async processMetrics(metrics) {
    if (!metrics || metrics.length === 0) return;

    for (const metric of metrics) {
      const logMessage = `{"timestamp": ${metric.timestamp}, "host": "${process.env.HOSTNAME}", "metric": "${metric.type}", "value": ${metric.value}}`;
      await this.logMetrics(logMessage);
    }
  }

  async logMetrics(message) {
    const socket = net.createSocket('tcp', 8080);

    try {
      await socket.write(`{"log_message": "${message}"}`);
    } finally {
      socket.destroy();
    }
  }
}

// C-based Logging Component (c_log_handler.c)
#include <stdio.h>
#include <stdlib.h>
#include <stdarg.h>
#include <snprintf.h>

#define LOG_FILE "system_metrics.log"
#define MAX_LOG_LINE_LENGTH 1024

int main() {
  FILE *logFile = fopen(LOG_FILE, "a+");
  if (!logFile) {
    perror("Failed to open log file");
    return 1;
  }

  int lineCount = 0;

  while (1) {
    char buffer[MAX_LOG_LINE_LENGTH];
    ssize_t bytesRead = read(STDIN_FILENO, buffer, MAX_LOG_LINE_LENGTH);

    if (bytesRead < 0) {
      perror("Failed to read from socket");
      return 1;
    }

    const char *formatString = "{\"timestamp\": %llu, \"host\": \"%s\", \"metric\": \"%s\", \"value\": %f}";
    va_list ap;

    for (int i = 0; i < lineCount; i++) {
      if (fputs(buffer, logFile) < 0) {
        perror("Failed to write to log file");
        return 1;
      }
    }

    va_start(ap, formatString);
    vsnprintf(buffer, MAX_LOG_LINE_LENGTH, formatString, ap);
    va_end(ap);

    fprintf(logFile, buffer);
    fflush(logFile);
  }

  fclose(logFile);
}
