    ue_status** connections;
    time_t inactivity_threshold;
    int syncing; // flag for synchronization process
    FILE* log_file;
} ue_manager;

// Function prototypes
ue_manager* ue_manager_init(size_t initial_capacity);
void ue_manager_add_ue(ue_manager*, int, float, float);
int ue_manager_update_ue(ue_manager*, int, float, float);
ue_status* ue_manager_get_ue(ue_manager*, int);
