void ue_manager_sync_statuses(ue_manager*, FILE*);
int ue_manager_sync_error_handler(ue_manager*, int);

// Initialize a new UE manager instance with the given initial capacity
ue_manager* ue_manager_init(size_t initial_capacity) {
    ue_manager* manager = (ue_manager*)malloc(sizeof(ue_manager));
    manager->capacity = initial_capacity;
    manager->count = 0;
    manager->connections = (ue_status**)malloc(initial_capacity * sizeof(ue_status*));
    manager->inactivity_threshold = time(NULL) - 3600; // default to 1 hour
    manager->syncing = 0;
    manager->log_file = fopen("ue_manager.log", "a");
    return manager;
}

// Add a new UE connection status to the manager
void ue_manager_add_ue(ue_manager* manager, int ue_id, float signal_strength, float channel_quality) {
    if (manager->count >= manager->capacity) {
        // Realloc and resize connections array when full
        size_t new_capacity = manager->capacity * 2;
        ue_status** new_connections = (ue_status**)malloc(new_capacity * sizeof(ue_status*));
        memcpy(new_connections, manager->connections, manager->capacity * sizeof(ue_status*));
        free(manager->connections);
        manager->connections = new_connections;
        manager->capacity = new_capacity;
    }
    manager->connections[manager->count] = (ue_status*)malloc(sizeof(ue_status));
    manager->connections[manager->count]->ue_id = ue_id;
    manager->connections[manager->count]->signal_strength = signal_strength;
    manager->connections[manager->count]->channel_quality = channel_quality;
    manager->connections[manager->count]->last_update = time(NULL);
    manager->count++;
}

// Update the connection status of an existing UE
int ue_manager_update_ue(ue_manager* manager, int ue_id, float signal_strength, float channel_quality) {
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->connections[i]->ue_id == ue_id) {
            manager->connections[i]->signal_strength = signal_strength;
            manager->connections[i]->channel_quality = channel_quality;
            manager->connections[i]->last_update = time(NULL);
            return 1; // UE found and updated
        }
    }
    return 0; // UE not found
}

// Retrieve the connection status of a UE
ue_status* ue_manager_get_ue(ue_manager* manager, int ue_id) {
    for (size_t i = 0; i < manager->count; i++) {
        if (manager->connections[i]->ue_id == ue_id) {
            return manager->connections[i];
        }
    }
    return NULL; // UE not found
}

// Cleanup inactive connections based on the inactivity threshold
void ue_manager_cleanup_inactive(ue_manager* manager) {
    time_t current_time = time(NULL);
    for (size_t i = 0; i < manager->count; i++) {
        if (current_time - manager->connections[i]->last_update > manager->inactivity_threshold) {
            // Remove inactive connection
            memmove(&manager->connections[i], &manager->connections[i + 1], sizeof(ue_status*) * (manager->count - i));
            manager->count--;
            i--; // Re-check the next element since we moved it down
        }
    }
}

