// TX_PACKET structure definition
typedef struct {
    int transmission_tag;
    int sequence_number;
    int data_size;
} TX_PACKET;

// Packet Manager functions
TX_PACKET* insert_packet(TX_PACKET* packets, int num_packets, TX_PACKET new_packet);
void remove_packet(TX_PACKET** packets, int* num_packets, int packet_to_remove);
TX_PACKET* get_packet_by_sequence_number(TX_PACKET* packets, int num_packets, int sequence_number);

// Function to insert a new packet into the list
TX_PACKET* insert_packet(TX_PACKET* packets, int num_packets, TX_PACKET new_packet) {
    // Allocate memory for a new array with one extra slot
    TX_PACKET* new_packets = (TX_PACKET*)malloc((num_packets + 1) * sizeof(TX_PACKET));

    // Copy existing packets to the new array
    memcpy(new_packets, packets, num_packets * sizeof(TX_PACKET));

    // Insert the new packet into the array
    new_packets[num_packets] = new_packet;

    // Update the number of packets
    free(packets);
    return new_packets;
}

// Function to remove a packet from the list based on sequence number
void remove_packet(TX_PACKET** packets, int* num_packets, int packet_to_remove) {
    // Iterate through the array and find the packet with the matching sequence number
    for (int i = 0; i < *num_packets; i++) {
        if ((*packets)[i].sequence_number == packet_to_remove) {
            // Shift all packets after the removed one to fill the gap
            memmove(&(*packets)[i], &(*packets)[i + 1], (*num_packets - i - 1) * sizeof(TX_PACKET));
            break;
        }
    }

    // Decrement the number of packets
    (*num_packets]--;
}

// Function to retrieve a packet from the list based on sequence number
TX_PACKET* get_packet_by_sequence_number(TX_PACKET* packets, int num_packets, int sequence_number) {
    for (int i = 0; i < num_packets; i++) {
        if (packets[i].sequence_number == sequence_number) {
            return &packets[i];
        }
    }
    return NULL;
}

int main() {
    // Initialize the packet manager
    TX_PACKET* packets = NULL;
    int num_packets = 0;

    // Insert a new packet into the list
    TX_PACKET new_packet = {1, 1, 100};
    packets = insert_packet(packets, num_packets, new_packet);
    num_packets++;

    // Remove a packet from the list based on sequence number
    remove_packet(&packets, &num_packets, 1);

    // Retrieve a packet from the list based on sequence number
    TX_PACKET* retrieved_packet = get_packet_by_sequence_number(packets, num_packets, 2);
    if (retrieved_packet) {
        printf("Retrieved packet: Sequence Number %d\n", retrieved_packet->sequence_number);
    } else {
        printf("Packet not found.\n");
    }

    // Clean up
    free(packets);

    return 0;
}
