namespace fs = std::filesystem;

std::string create_dir(const std::string& dir_name) {
    // Check if environment variable is already set
    auto env_var_value = std::getenv("MY_ENV_VAR");
    if (!env_var_value) {
        // Create new directory
        try {
            fs::create_directory(dir_name);
        } catch (const fs::filesystem_error& e) {
            std::cerr << "Error creating directory: " << e.what() << std::endl;
            return "";
        }

        // Set environment variable with the path of the created directory
        std::string dir_path = dir_name + "/";
        setenv("MY_ENV_VAR", dir_path.c_str(), 1);
    } else {
        // Environment variable already set, use existing value
        auto env_var_path = fs::path(env_var_value).parent_path().string();
        return env_var_path;
    }
}

int main() {
    std::cout << "New directory path: " << create_dir("my_new_directory") << std::endl;
    return 0;
}
