#include <iostream>
#include <vector>
#include <string>
#include <memory>

// Define a base class for encryption algorithms
class EncryptionAlgorithm {
public:
    virtual ~EncryptionAlgorithm() {}
    virtual std::string encrypt(const std::string& data) const = 0;
};

// Implement AES algorithm
class AesEncryption : public EncryptionAlgorithm {
public:
    std::string encrypt(const std::string& data) const override {
        // AES encryption implementation
        return data + " AES encrypted";
    }
};

// Implement RSA algorithm
class RsaEncryption : public EncryptionAlgorithm {
public:
    std::string encrypt(const std::string& data) const override {
        // RSA encryption implementation
        return data + " RSA encrypted";
    }
};

// Implement ECC algorithm
class EccEncryption : public EncryptionAlgorithm {
public:
    std::string encrypt(const std::string& data) const override {
        // ECC encryption implementation
        return data + " ECC encrypted";
    }
};

// Define a modular encryption service class
class EncryptionService {
public:
    EncryptionService() = default;
    ~EncryptionService() = default;

    void setAlgorithm(const std::string& algorithmName) {
        // Determine the correct encryption algorithm based on runtime configuration
        if (algorithmName == "AES") {
            algorithm_ = std::make_unique<AesEncryption>();
        } else if (algorithmName == "RSA") {
            algorithm_ = std::make_unique<RsaEncryption>();
        } else if (algorithmName == "ECC") {
            algorithm_ = std::make_unique<EccEncryption>();
        }
    }

    std::string encrypt(const std::string& data) const {
        return algorithm_->encrypt(data);
    }

private:
    std::unique_ptr<EncryptionAlgorithm> algorithm_;
};

int main() {
    EncryptionService encryptionService;
    encryptionService.setAlgorithm("AES");
    std::cout << "AES Encrypted: " << encryptionService.encrypt("Hello, World!") << std::endl;

    return 0;
}
```

