['Here is the code block for the `RandomNumberService` library:

```cpp
#include <thread>
#include <mutex>

namespace RandomNumberService {
class MTGenerator {
public:
    MTGenerator(unsigned int seed) : mt_(seed) {}

    ~MTGenerator() {
        std::unique_lock<std::mutex> lock(mutex_);
        delete[] state_;
    }

    static unsigned int generate(MTGenerator& generator) {
        return static_cast<unsigned int>(mt_.next());
    }

private:
    class MersenneTwister {
    public:
        MersenneTwister(unsigned int seed) : state_(new unsigned long[624]) {
            unsigned long* s = state_;
            for (int i = 0; i < 624; ++i) {
                s[i] = (seed + i) & ((1 << 31) - 1);
            }
        }

        ~MersenneTwister() {
            delete[] state_;
        }

        unsigned long next() {
            unsigned long* s = state_ + 397;
            unsigned long y = *--s;
            y ^= (y >> 11);
            unsigned long t = (y << 7) & ((1 << 31) - 1);
            t ^= (t >> 15);
            t *= 0x7fe00000U;
            unsigned long z = (y >> 18) ^ (t >> 10);
            *s++ = (z << 11) | (z >> 3);
            return *s & ((1 << 31) - 1);
        }

    private:
        unsigned long* state_;
    };

    MersenneTwister mt_;
    std::mutex mutex_;
    unsigned long* state_ = nullptr;
};
}  // namespace RandomNumberService
```']

