            dataset = await UpdateSchemaModelAsync(dataset, filePathOrUri);

            // 3. Implement fault-tolerant batch processing with checkpointing
            int currentBatchSize = batchSize;
            int processedItems = 0;
            while (processedItems < dataset.Count)
            {
                var batch = dataset.Skip(processedItems).Take(currentBatchSize);
                await ProcessBatchAsync(batch, targetConfig);
                processedItems += currentBatchSize;
                if (processedItems >= dataset.Count)
                    break;

                // Implement retry policy for permanent errors
                while (true)
                {
                    try
                    {
                        await ProcessBatchAsync(dataset.Skip(processedItems).Take(currentBatchSize), targetConfig);
