        }
      };
    }),
    { concurrency: MAX_CONCURRENT_UPLOADED }
  );
}

// Retry strategy for failed uploads
async function retryUpload(fn, attempts) {
  let attempt = 0;
  const maxAttempts = attempts;

  async function upload() {
    try {
      await fn();
    } catch (error) {
      if (attempt < maxAttempts) {
        console.log(`Failed to upload file. Retrying in ${Math.pow(2, attempt + 1)} milliseconds...`);
        await new Promise((resolve) => setTimeout(resolve, Math.pow(2, attempt + 1)));
        attempt++;
        await upload();
      } else {
        throw error;
      }
    }
  }

  return upload();
}

