```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include <map>
#include <stdexcept>

class ResourceBundle {
public:
    static const std::string JSON_EXT;
    static const std::string XML_EXT;
    static const std::string YAML_EXT;

    // Load a resource bundle from a file
    static void load(const std::string& file_path, const std::string& ext);

    // Get all resources in the bundle
    static std::vector<std::pair<std::string, std::any>> get_resources();

    // Get metadata for a specific resource
    static std::any get_resource_metadata(const std::string& resource_name);

    // Update individual items in the resource bundle
    static void update_resource(const std::string& resource_name, const std::any& new_value);
};

std::map<std::string, std::any> ResourceBundle::resources;

const std::string ResourceBundle::JSON_EXT = ".json";
const std::string ResourceBundle::XML_EXT = ".xml";
const std::string ResourceBundle::YAML_EXT = ".yaml";

void ResourceBundle::load(const std::string& file_path, const std::string& ext) {
    // Load resource bundle from a file
    std::ifstream file(file_path + ext);
    if (!file.is_open()) {
        throw std::runtime_error("Failed to open file");
    }

    // Read and deserialize resources
    std::string line;
    while (std::getline(file, line)) {
        // Parse resource data
        size_t pos = 0;
        size_t next_pos = line.find(',');
        while (next_pos != std::string::npos) {
            // Get key-value pair
            std::string key = line.substr(pos, next_pos - pos);
            std::any value; // deserialize value based on ext
            resources[key] = value;

            pos = next_pos + 1;
            next_pos = line.find(',', pos);
        }
    }

    file.close();
}

std::vector<std::pair<std::string, std::any>> ResourceBundle::get_resources() {
    return std::vector<std::pair<std::string, std::any>>(resources.begin(), resources.end());
}

std::any ResourceBundle::get_resource_metadata(const std::string& resource_name) {
    if (resources.find(resource_name) == resources.end()) {
        throw std::runtime_error("Resource not found");
    }
    return resources[resource_name];
}

void ResourceBundle::update_resource(const std::string& resource_name, const std::any& new_value) {
    if (resources.find(resource_name) == resources.end()) {
        throw std::runtime_error("Resource not found");
    }
    resources[resource_name] = new_value;
}
