import java.util.*;

public class DisjointPairChecker {

    private Map<Integer, Integer> parentMap;
    private int threshold = 1000;

    public DisjointPairChecker() {
        this.parentMap = new HashMap<>();
    }

    public void checkPairs(int[] pairs) throws Exception {
        for (int pair : pairs) {
            if (Math.abs(pair) > threshold) {
