using System;

public class Program 
{
    public static void AddWebsiteToDirectory(string directoryPath, string siteName) 
    {
        if (!Directory.Exists(directoryPath)) 
            return; 

        string webConfigFilePath = Path.Combine(directoryPath, "web.config");

        if (!File.Exists(webConfigFilePath))
            return;

        ProcessStartInfo startInfo = new ProcessStartInfo("iisreset", "-start");
        startInfo.FileName = "iisreset.exe";
        startInfo.Arguments = $"-start {siteName}";
        startInfo.UseShellExecute = false;
        startInfo.CreateNoWindow = true;

        try 
        {
            using (Process process = Process.Start(startInfo))
            {
                process.WaitForExit();
            }
        } 
        catch (Exception ex) 
        {
            Console.WriteLine($"Error starting site: {ex.Message}");
        }
    }
}

// SQL query to retrieve employee details
using System;
using System.Data.SqlClient;

public class Program 
{
    public static void RetrieveEmployeeDetails(string supervisorId) 
    {
        string connectionString = "Server=myserver;Database=mydatabase;User Id=myuser;Password=mypassword;";
        SqlConnection connection = new SqlConnection(connectionString);

        try 
        {
            connection.Open();

            SqlCommand command = new SqlCommand("SELECT name, city, address FROM Employees WHERE supervisor_id = @supervisorId", connection);
            command.Parameters.AddWithValue("@supervisorId", supervisorId);

            SqlDataReader reader = command.ExecuteReader();

            while (reader.Read()) 
            {
                Console.WriteLine($"Name: {reader["name"]}, City: {reader["city"]}, Address: {reader["address"]}");
            }
        } 
        catch (Exception ex) 
        {
            Console.WriteLine($"Error retrieving employee details: {ex.Message}");
        } 
        finally 
        {
            connection.Close();
        }
    }
}
