    public function authenticate(Request $request): Response {
        if (!$request->has('provider')) {
            return new JsonResponse(['error' => 'Invalid provider'], 400);
        }
        $provider = $this->getProvider($request->get('provider'));
        if (!$provider) {
            return new JsonResponse(['error' => 'Unknown provider'], 404);
        }

        try {
            $accessToken = $provider->getAccessToken();
            // Validate access token
            if (!$accessToken->isValid()) {
                throw new Exception('Invalid access token');
            }
            // Create or update session token
            $sessionToken = $this->createSessionToken($request, $accessToken);
            return new JsonResponse(['token' => $sessionToken], 200);
        } catch (Exception $e) {
            return new JsonResponse(['error' => 'Authentication failed: ' . $e->getMessage()], 401);
        }
    }

