// Define a struct to represent an attack
struct Attack {
    std::string name;
    int cooldownDuration; // in seconds
    bool isAvailable = true;
};

// Define a class to manage attacks
class AttackManager {
public:
    AttackManager() : cooldownMap(), availableAttacks() {}

    void addAttack(const Attack& attack) {
        cooldownMap[attack.name] = attack.cooldownDuration;
        availableAttacks.insert(attack.name);
    }

    bool hasCooldownExpired(const std::string& attackName) const {
        auto it = cooldownMap.find(attackName);
        return it == cooldownMap.end() || it->second <= 0;
    }

    void updateCooldown(const std::string& attackName, int newCooldownDuration) {
        if (cooldownMap.find(attackName) != cooldownMap.end()) {
            cooldownMap[attackName] = newCooldownDuration;
        }
    }

    bool isValidAttack(const std::string& attackName) const {
        return availableAttacks.count(attackName);
    }

private:
    std::unordered_map<std::string, int> cooldownMap;
    std::unordered_set<std::string> availableAttacks;
};

// Define a class to manage character attacks
class CharacterAttackManager {
public:
    CharacterAttackManager(size_t numCharacters) : characterQueue(numCharacters), attackManager() {}

    void addCharacter(size_t characterId) {
        characterQueue.emplace(characterId);
    }

    void updateCooldown(const std::string& attackName, int newCooldownDuration) {
        attackManager.updateCooldown(attackName, newCooldownDuration);
    }

    bool hasCooldownExpired(const std::string& attackName, size_t characterId) const {
        return attackManager.hasCooldownExpired(attackName);
    }

    void processAttack(size_t characterId) {
        auto character = characterQueue.front();
        characterQueue.pop();

        // Simulate processing time
        std::this_thread::sleep_for(std::chrono::milliseconds(100));

        // Update cooldown and available attacks
        attackManager.updateCooldown("attack1", 5);
    }

private:
    std::queue<size_t> characterQueue;
    AttackManager attackManager;
};

int main() {
    size_t numCharacters = 10000;

    CharacterAttackManager manager(numCharacters);

    for (size_t i = 0; i < numCharacters; ++i) {
        manager.addCharacter(i);
    }

    // Simulate attacks
    while (true) {
        for (size_t i = 0; i < numCharacters; ++i) {
            if (!manager.hasCooldownExpired("attack1", i)) {
                manager.processAttack(i);
            }
        }
        std::this_thread::sleep_for(std::chrono::seconds(5));
    }

    return 0;
}
