['Here is the PHP function to update a database table:

```php
function update_clinic_status($clinic_id, $new_status) {
    $db_host = 'your_db_host';
    $db_username = 'your_db_username';
    $db_password = 'your_db_password';
    $db_name = 'your_db_name';

    // Establish connection to the database
    $conn = new mysqli($db_host, $db_username, $db_password, $db_name);

    // Check for any errors while connecting
    if ($conn->connect_error) {
        die("Connection failed: " . $conn->connect_error);
    }

    // Start transaction
    $conn->begin_transaction();

    try {
        // Update the clinic status in the database
        $sql = "UPDATE clinics SET status = ?, last_modified_ip_address = inet_aton(?), last_modified_date = NOW() WHERE id = ?";
        $stmt = $conn->prepare($sql);
        $stmt->bind_param("sss", $new_status, $_SERVER['REMOTE_ADDR'], $clinic_id);
        $stmt->execute();

        // Commit the transaction
        $conn->commit();
    } catch (Exception $e) {
        // Rollback the transaction if an error occurs
        $conn->rollback();
        throw $e;
    } finally {
        // Close the connection
        $conn->close();
    }
}
```']

