public class FlexibleApiGateway {

    private List<Service> services = new ArrayList<>();
    private LoadBalancer loadBalancer;
    private RequestQueue requestQueue;

    public void addService(Service service) {
        services.add(service);
        if (loadBalancer == null) {
            loadBalancer = new RoundRobinLoadBalancer(services);
        } else {
            loadBalancer.updateServices(services);
        }
    }

    public void removeService(Service service) {
        services.remove(service);
        if (services.isEmpty()) {
            loadBalancer = null;
        } else {
            loadBalancer.updateServices(services);
        }
    }

    public void handleRequest(Request request) {
        Service chosenService = loadBalancer.selectService();
        requestQueue.enqueue(request, chosenService);
    }

