        self.registry = {}
        self.loop = asyncio.get_event_loop()

    async def process_data(self, data: str) -> None:
        try:
            obj = json.loads(data)
            for key, value in obj.items():
                if isinstance(value, dict):
                    await self.process_nested_data(key, value)
        except Exception as e:
            print(f"Error processing data: {e}")

    async def process_nested_data(self, key: str, data: Dict[str, Any]) -> None:
        for k, v in data.items():
            if isinstance(v, dict):
                await self.process_nested_data(f"{key}.{k}", v)
            elif isinstance(v, list):
                await self.process_list_data(key, v)

    async def process_list_data(self, key: str, data: List[Any]) -> None:
