import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.*;

public class BatchProcessingSystem {

    // Define a list to hold batch processing tasks
    private List<Callable<Void>> batchTasks = new ArrayList<>();

    public void processBatch(String source, String transformationRule) {
        // Create a callable task for the batch processing
        Callable<Void> task = new BatchTask(source, transformationRule);

        // Add the task to the list of batch tasks
        batchTasks.add(task);

        // Submit all batch tasks for execution using an executor service
        ExecutorService executor = Executors.newFixedThreadPool(10); // adjust the thread pool size as needed
        List<Future<Void>> futures = executor.invokeAll(batchTasks);

        // Process each task's result
        for (Future<Void> future : futures) {
            try {
                future.get();
            } catch (InterruptedException | ExecutionException e) {
                System.out.println("Error processing batch: " + e.getMessage());
            }
        }

        // Close the executor service
        executor.shutdown();
    }

    private class BatchTask implements Callable<Void> {

        private String source;
        private String transformationRule;

        public BatchTask(String source, String transformationRule) {
            this.source = source;
            this.transformationRule = transformationRule;
        }

        @Override
        public Void call() throws Exception {
            // Implement the batch processing logic for the given source and transformation rule
            System.out.println("Processing batch from " + source + " with rule: " + transformationRule);

            // Simulate some processing time
            Thread.sleep(1000); // adjust this value as needed

            return null;
        }
    }
}
