#include <iostream>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <queue>
#include <functional>

class Middleware {
public:
    Middleware() : stopped(false) {}

    void start() {
        thread_ = std::thread([this] { run(); });
    }

    void stop() {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            stopped = true;
        }
        cv_.notify_one();
        if (thread_) {
            thread_->join();
            thread_.reset();
        }
    }

private:
    void run() {
        while (!stopped) {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this] { return stopped || !queue_.empty(); });

            while (!queue_.empty()) {
                auto task = queue_.front();
                queue_.pop();

                // Process the task
                processTask(task);

                if (stopped) break;
            }
        }
    }

    void enqueueTask(const std::function<void()> &task) {
        {
            std::unique_lock<std::mutex> lock(mutex_);
            queue_.push(task);
        }
        cv_.notify_one();
    }

    std::queue<std::function<void()>> queue_;
    std::thread thread_;
    std::mutex mutex_;
    std::condition_variable cv_;
    bool stopped;

    void processTask(const std::function<void()> &task) {
        // Implement your message processing logic here
        task();
    }
};
