using namespace std;

// Function to add a website to a directory and start it using Process class
void AddWebsiteToDirectory(const string& directoryPath) {
    if (directoryPath.empty()) {
        cout << "Error: Directory path cannot be empty." << endl;
        return;
    }

    // Check for existence of web.config file in the directory
    ifstream file(directoryPath + "/web.config");
    if (!file.is_open()) {
        return; // Return null if web.config file does not exist
    }

    try {
        // Start the website using Process class
        system(("start " + directoryPath).c_str());
    } catch (const runtime_error& e) {
        cout << "Error: " << e.what() << endl;
    }
}

// Function to traverse a directory and its subdirectories
void TraverseDirectory(const string& directoryPath, int depth = 0) {
    if (!filesystem::is_directory(directoryPath)) {
        return; // Return if the given path is not a directory
    }

    try {
        for (const auto& entry : filesystem::directory_iterator(directoryPath)) {
            const string& filePath = entry.path().string();
            if (depth > 0) {
                cout << string(depth * 4, ' ') << "Entry: " << filePath << endl;
            }

            // Recursively traverse subdirectories
            if (filesystem::is_directory(filePath)) {
                TraverseDirectory(filePath, depth + 1);
            }
        }
    } catch (const filesystem::filesystem_error& e) {
        cout << "Error: " << e.what() << endl;
    }
}

int main() {
    const string directoryPath = "/path/to/directory";
    int depth = 3; // Configurable depth for directory traversal

    TraverseDirectory(directoryPath, depth);

    return 0;
}
